reactions.evaluate:
function evaluate(type, data, token) {
  return data.triggeringToken?.id === token.id;
}

reactions.activationCode:
async function activation(type, data, token, item, name, api) {
  const value = Number(api.tierValue(token, [3, 4, 5]));
  const current = Number(token.actor?.system?.overshield?.value ?? 0);
  if (current < value)
    await token.actor.update({ "system.overshield.value": value });
}

reactions.onInit:
async function onInit(token, item, api) {
  if (!token?.actor || !item) return;
  await api.ensureLinkedBonus({
    items: [item], bonusData: {
      id: "rebaked-defender-ablative-size-v1",
      name: "Ablative Armor — Size 2",
      type: "stat", stat: "system.size", statMode: "replace", val: 2
    }, addOptions: { duration: "constant" }
  });
}

async function onInit(token, item, api) {
    if (!token?.actor || !item) return;
    await api.addConstantBonus(token.actor, {
      id: "rebaked-scourer-ablative-shielding-" + item.id,
      name: "Ablative Shielding — Energy Resistance",
      type: "resistance", damageTypes: ["Energy"]
    });
  }

reactions.evaluate:
function evaluate(triggerType, triggerData, reactorToken, item, activationName, api) {
    if (triggerData.target?.id !== reactorToken.id) return false;

    return (triggerData.damages ?? []).some(
        (damage) => Number(damage) > 0
    );
}

reactions.activationCode:
async function activation(triggerType, triggerData, reactorToken, item, activationName, api) {
    const gmId = api.getActiveGMId();
    if (!gmId) {
        ui.notifications.warn("Aggression: No active GM is available to resolve the retaliation.");
        return;
    }

    const firstThisRound = await api.consumeOncePerRound(
        reactorToken,
        "berserker_aggression"
    );
    if (!firstThisRound) return;

    api.afterFlow(triggerData, async () => {
        const activeGMId = api.getActiveGMId();
        if (!activeGMId || !game.users.get(activeGMId)?.active) {
            ui.notifications.warn("Aggression: The GM is no longer available to resolve the retaliation.");
            return;
        }

        await triggerData.sendMessageToReactor(
            {},
            activeGMId,
            { wait: true }
        );
    });
}

reactions.onMessage:
async function onMessage(triggerType, data, reactorToken, item, activationName, api) {
    if (!game.user.isGM) return;

    const chainAxe = api.findItemByLid(
        reactorToken,
        "npc-rebake_npcf_chain_axe_berserker"
    );
    if (!chainAxe) {
        ui.notifications.warn(`${reactorToken.name}: Aggression could not find the Chain Axe.`);
        return;
    }

    const adjacent = api.getTokensInRange(reactorToken, {
        range: 1,
        includeSelf: false,
        includeHidden: true,
        includeDefeated: false,
        includeDeployables: true
    }).filter((target) => target?.actor);

    if (!adjacent.length) {
        ui.notifications.info(`${reactorToken.name}: Aggression has no adjacent character to attack.`);
        return;
    }

    const target = adjacent[Math.floor(Math.random() * adjacent.length)];
    ui.notifications.info(`${reactorToken.name}: Aggression targets ${target.name}.`);

    await api.attackWith(chainAxe, [target], {
        fxSourceToken: reactorToken
    });
}

reactions.evaluate:
function evaluate(triggerType, triggerData, reactorToken, item, activationName, api) {
    const markName = "Sniper's Mark";

    if (triggerType === "onInitAttack") {
        return (triggerData.targets ?? []).some((target) => {
            if (!target?.actor) return false;

            const marked = api.findEffectsOnToken(target, markName, {
                extraFlags: { sniperSourceId: reactorToken.id }
            }).length > 0;

            const ignored = api.hasStatus(
                target,
                "prone",
                "cover_hard",
                "cover_soft"
            );

            return api.hasStatus(target, "prone") || (marked && !ignored);
        });
    }

    return (triggerData.hitTokens ?? []).some((target) => {
        if (!target?.actor) return false;

        const marked = api.findEffectsOnToken(target, markName, {
            extraFlags: { sniperSourceId: reactorToken.id }
        }).length > 0;

        const ignored = api.hasStatus(
            target,
            "prone",
            "cover_hard",
            "cover_soft"
        );

        return marked && !ignored;
    });
}

reactions.activationCode:
async function activation(triggerType, triggerData, reactorToken, item, activationName, api) {
    const markName = "Sniper's Mark";

    if (triggerType === "onInitAttack") {
        const proneTargets = [];
        const exposedMarkedTargets = [];

        for (const target of triggerData.targets ?? []) {
            if (!target?.actor) continue;

            if (api.hasStatus(target, "prone")) {
                proneTargets.push(target);
            }

            const marked = api.findEffectsOnToken(target, markName, {
                extraFlags: { sniperSourceId: reactorToken.id }
            }).length > 0;

            const ignored = api.hasStatus(
                target,
                "prone",
                "cover_hard",
                "cover_soft"
            );

            if (marked && !ignored) exposedMarkedTargets.push(target);
        }

        if (proneTargets.length) {
            await api.injectBonusToFlowState(triggerData.flowState, {
                id: `anti_materiel_ignore_prone_${item.id}`,
                name: "Anti-Materiel Rifle — Ignore Prone Accuracy",
                type: "difficulty",
                val: 1,
                rollTypes: ["attack"],
                applyTo: proneTargets.map((target) => target.id)
            });
        }

        if (exposedMarkedTargets.length) {
            await api.injectBonusToFlowState(triggerData.flowState, {
                id: `snipers_mark_accuracy_${item.id}`,
                name: "Sniper's Mark",
                type: "accuracy",
                val: 1,
                rollTypes: ["attack"],
                applyTo: exposedMarkedTargets.map((target) => target.id)
            });
        }

        return;
    }

    let replacedDamage = false;

    for (const target of triggerData.hitTokens ?? []) {
        const actor = target?.actor;
        if (!actor) continue;

        const marked = api.findEffectsOnToken(target, markName, {
            extraFlags: { sniperSourceId: reactorToken.id }
        }).length > 0;

        const ignored = api.hasStatus(
            target,
            "prone",
            "cover_hard",
            "cover_soft"
        );

        if (!marked || ignored) continue;

        const confirmed = await api.confirmCard({
            title: "SNIPER'S MARK",
            description: `<b>${target.name}</b> is marked and exposed. Replace the Anti-Materiel Rifle's normal damage with 1 structure damage?`,
            item,
            originToken: reactorToken,
            relatedToken: target,
            confirmText: "Deal 1 Structure",
            confirmIcon: "fas fa-skull"
        });

        if (!confirmed) continue;

        await actor.update({
            "system.hp.value": Number(actor.system.hp?.value ?? 0)
                - Number(actor.system.hp?.max ?? 0)
        });

        replacedDamage = true;
    }

    if (replacedDamage) {
        await triggerData.cancelDamage(
            "Sniper's Mark replaces the Anti-Materiel Rifle's normal damage.",
            "SNIPER'S MARK",
            false
        );
    }
}

reactions.evaluate:
function evaluate(type, data, token, item, name, api) {
    if (type === "onActivation")
      return data.triggeringToken?.id === token.id && data.item?.id === item.id;
    if (type === "onExitCombat")
      return data.triggeringToken?.id === token.id || !game.combat;
    const targetId = api.getActorFlags(token.actor, "rebakedAssassinMarkedTargetId");
    if (!targetId) return false;
    if (type === "onDestroyed" || type === "onTokenRemoved")
      return (data.triggeringToken ?? data.token ?? data.tokenDocument)?.id === token.id
        || (data.triggeringToken ?? data.token ?? data.tokenDocument)?.id === targetId
        || data.tokenId === targetId;
    if (type === "onHit")
      return (data.triggeringToken?.id === targetId
        && (data.targets ?? []).some(hit => hit?.target?.id === token.id))
        || (data.triggeringToken?.id === token.id
        && (data.targets ?? []).some(hit => hit?.target?.id === targetId));
    const rollerId = data.triggeringToken?.id;
    const sourceId = data.checkAgainstToken?.id;
    return (rollerId === token.id && sourceId === targetId)
      || (rollerId === targetId && sourceId === token.id);
  }

reactions.activationCode:
async function activation(type, data, token, item, name, api) {
    const key = "rebakedAssassinMarkedTargetId";
    if (type === "onDestroyed" || type === "onTokenRemoved" || type === "onExitCombat") {
      const gmId = api.getActiveGMId();
      if (gmId && game.users.get(gmId)?.active)
        await data.sendMessageToReactor({ clearMark: true }, gmId, { wait: true });
      return;
    }
    if (type === "onActivation") {
      const oldId = api.getActorFlags(token.actor, key);
      if (oldId && canvas.tokens.get(oldId)) {
        ui.notifications.warn("Assassin's Mark: the current target must be destroyed before choosing another.");
        return;
      }
      const target = (await api.chooseToken(token, {
        title: "ASSASSIN'S MARK — TARGET", count: 1,
        includeSelf: false, soft: false,
        description: "GM: choose one character in line of sight. The mark lasts for the scene."
      }))?.[0];
      if (!target) return;
      await api.addActorFlags(token.actor, { [key]: target.id });
      await api.applyEffectsToTokens({
        tokens: [target],
        effectNames: [{ name: "Assassin's Mark", icon: item.img, isCustom: true }],
        note: "Assassin resists this target's damage, and its own damage to this target cannot be reduced.",
        duration: { label: "indefinite" }
      }, { rebakedAssassinMarkSource: item.id, sourceTokenId: token.id });
      return;
    }
    if (type === "onHit") {
      if (data.triggeringToken?.id === token.id) {
        const markedId = api.getActorFlags(token.actor, key);
        await api.injectBonusToFlowState(data.flowState, {
          id: "rebaked-assassin-mark-irreducible-" + item.id,
          name: "Assassin's Mark — Cannot Be Reduced",
          type: "target_modifier", subtype: "paracausal",
          applyTo: [markedId], rollTypes: ["damage"]
        });
        return;
      }
      await api.injectBonusToFlowState(data.flowState, {
        id: "rebaked-assassin-mark-resistance-" + item.id,
        name: "Assassin's Mark — Resistance",
        type: "target_modifier", subtype: "half_damage",
        applyTo: [token.id], rollTypes: ["damage"]
      });
      return;
    }
    await api.injectBonusToFlowState(data.flowState, {
      id: "rebaked-assassin-mark-save-" + item.id,
      name: "Assassin's Mark — Save",
      type: data.triggeringToken?.id === token.id ? "accuracy" : "difficulty",
      val: 1, rollTypes: ["check"]
    });
  }

reactions.onMessage:
async function onMessage(type, data, token, item, name, api) {
    if (!game.user.isGM || !data.clearMark) return false;
    const key = "rebakedAssassinMarkedTargetId";
    const target = canvas.tokens.get(api.getActorFlags(token.actor, key));
    if (target) await api.removeEffectsByNameFromTokens({
      tokens: [target], effectNames: ["Assassin's Mark"],
      extraFlags: { rebakedAssassinMarkSource: item.id, sourceTokenId: token.id },
      notify: false
    });
    await api.removeActorFlags(token.actor, { [key]: true });
    return true;
  }

reactions.onInit:
async function onInit(token, item, api) {
  if (!token?.actor || !item) return;
  for (const [suffix, stat, val] of [
    ["evasion", "system.evasion", 2],
    ["armor", "system.armor", 1]
  ]) await api.ensureLinkedBonus({
    items: [item], bonusData: {
      id: "rebaked-striker-assault-armor-" + suffix + "-v1",
      name: "Assault Armor — " + suffix,
      type: "stat", stat, statMode: "add", val
    }, addOptions: { duration: "constant" }
  });
}

reactions.evaluate:
function evaluate(triggerType, triggerData, reactorToken, item, activationName, api) {
    const flowData = triggerData.flowState?.data;
    const attackTargets = flowData?.acc_diff?.targets ?? [];
    const hitResults = flowData?.hit_results ?? [];

    return hitResults.some((result, index) => {
        const cover = Number(attackTargets[index]?.cover ?? 0);
        return result?.hit === true && result?.crit === true && cover === 0;
    });
}

reactions.activationCode:
async function activation(triggerType, triggerData, reactorToken, item, activationName, api) {
    const flowData = triggerData.flowState?.data;
    const attackTargets = flowData?.acc_diff?.targets ?? [];
    const hitResults = flowData?.hit_results ?? [];

    const qualifyingTargetIds = hitResults
        .map((result, index) => {
            const cover = Number(attackTargets[index]?.cover ?? 0);
            if (!result?.hit || !result?.crit || cover !== 0)
                return null;
            return result.target?.id ?? null;
        })
        .filter(Boolean);

    if (!qualifyingTargetIds.length)
        return;

    await api.injectBonusToFlowState(triggerData.flowState, {
        id: `striker-assault-rifle-critical-${reactorToken.id}`,
        name: "Critical Momentum",
        type: "damage",
        damage: [{ val: "2", type: "Variable" }],
        applyTo: qualifyingTargetIds
    });

    api.afterFlow(triggerData, async () => {
        const choice = await api.askCard({
            title: "CRITICAL MOMENTUM",
            description: `<b>${reactorToken.name}</b> critically hit a target without cover and may immediately <b>Boost as a free action</b>.`,
            yesText: "Boost",
            yesIcon: "fas fa-forward",
            noText: "Decline",
            item,
            originToken: reactorToken,
            owner: reactorToken
        });

        if (!choice?.confirmed)
            return;

        const speed = Number(api.tokenSpeed(reactorToken)) || 0;
        if (speed <= 0) {
            ui.notifications.warn(`${reactorToken.name} has no available Boost movement.`);
            return;
        }

        const activation = await api.executeSimpleActivation(reactorToken, {
            title: "CRITICAL MOMENTUM — BOOST",
            action: { name: "Boost", activation: "Free" },
            detail: "Immediately Boost as a free action after scoring a critical hit against a target without cover."
        });

        if (!activation?.completed)
            return;

        api.recordBoostCast(reactorToken, speed);
        await api.moveTokenRuler(reactorToken, {
            range: speed,
            title: "CRITICAL MOMENTUM — BOOST",
            description: "Move up to your SPEED as a free-action Boost."
        });
    });
}

reactions.evaluate:
function evaluate(type, data, token, item) {
    if (type === "onActivation")
      return data.triggeringToken?.id === token.id && data.item?.id === item.id;
    if (type === "onExitCombat")
      return data.triggeringToken?.id === token.id || !game.combat;
    const round = Number(data.round ?? game.combat?.round ?? 0);
    return canvas.scene.templates.some(zone => {
      const mark = zone.getFlag("lancer-automations", "rebakedAtlasMissiles");
      return mark?.ownerTokenId === token.id
        && mark.combatId === game.combat?.id
        && Number(mark.detonateRound) <= round;
    });
  }

reactions.activationCode:
async function activation(type, data, token, item, name, api) {
    const scope = "lancer-automations";
    const key = "rebakedAtlasMissiles";
    if (type === "onExitCombat") {
      const gmId = api.getActiveGMId();
      if (gmId && game.users.get(gmId)?.active)
        await data.sendMessageToReactor({ cleanup: true }, gmId, { wait: true });
      return;
    }
    if (type === "onActivation") {
      const placed = await api.placeZone(token, {
        type: "Blast", size: 2, range: 15, count: 1,
        title: "ATLAS MISSILES — MARK BLAST 2",
        centerLabel: "INCOMING", fillColor: "#c45530", borderColor: "#ffd063",
        description: "GM: mark a ground space within line of sight and Range 15. Detonates at the end of the following round."
      });
      const zone = placed?.[0]?.template;
      if (!zone) return;
      await zone.update({ ["flags." + scope + "." + key]: {
        ownerTokenId: token.id, itemId: item.id,
        combatId: game.combat?.id,
        detonateRound: Number(game.combat?.round ?? 0) + 2
      } });
      return;
    }
    const due = canvas.scene.templates.filter(zone => {
      const mark = zone.getFlag(scope, key);
      return mark?.ownerTokenId === token.id
        && mark.combatId === game.combat?.id
        && Number(mark.detonateRound) <= Number(data.round ?? game.combat?.round ?? 0);
    });
    const gmId = api.getActiveGMId();
    if (!gmId || !game.users.get(gmId)?.active) {
      ui.notifications.warn("Atlas Missiles: an active GM is needed to resolve the impact.");
      return;
    }
    const zoneIds = [];
    for (const zone of due)
      if (await api.consumeOncePerRound(token, key + "_resolve_" + zone.id))
        zoneIds.push(zone.id);
    if (zoneIds.length)
      await data.sendMessageToReactor({ zoneIds }, gmId, { wait: true });
  }

reactions.onMessage:
async function onMessage(type, data, token, item, name, api) {
    if (!game.user.isGM) return false;
    const scope = "lancer-automations";
    const key = "rebakedAtlasMissiles";
    if (data.cleanup) {
      for (const zone of canvas.scene.templates.filter(zone =>
        zone.getFlag(scope, key)?.ownerTokenId === token.id)) await zone.delete();
      return true;
    }
    for (const zoneId of data.zoneIds ?? []) {
      const zone = canvas.scene.templates.get(zoneId);
      const mark = zone?.getFlag(scope, key);
      if (!zone || mark?.ownerTokenId !== token.id
        || mark.combatId !== game.combat?.id) continue;
      try {
        const targets = api.tokensInTemplate(zone).filter(target => target?.actor);
        for (const target of targets) {
          let difficulty = 0;
          if (api.isHostile(token, target) && api.hasStatus(target, "lockon")) {
            const choice = await api.askCard({
              title: "ATLAS MISSILES — LOCK ON",
              description: "Consume this target's Lock On to give its Agility save +1 Difficulty?",
              item, originToken: token, owner: token,
              yesText: "Consume Lock On", noText: "Keep Lock On"
            });
            if (choice?.confirmed) {
              difficulty = 1;
              await api.removeEffectsByNameFromTokens({
                tokens: [target], effectNames: ["lockon"], notify: false
              });
            }
          }
          const saves = await api.executeSaveVsEffect([target], {
            stat: "AGILITY", title: "Atlas Missiles", origin: token,
            difficulty,
            cardDescription: "Failure: 16/20/24 Explosive or Energy by tier and full damage. Success: half damage."
          });
          if (!saves?.[0]?.result?.completed) continue;
          await api.executeDamageRoll(token, [target],
            String(api.tierValue(token, [16,20,24])),
            "Explosive", "Atlas Missiles",
            { half_damage: saves[0].passed });

        }
      } finally { await zone.delete(); }
    }
    return true;
  }

reactions.evaluate:
function evaluate(type, data, token, item, name, api) {
  const attacker = data.triggeringToken;
  if (!attacker?.actor || attacker.id === token.id
    || attacker.actor.type === "deployable"
    || !api.isFriendly(token, attacker)
    || !api.hasReactionAvailable(token)
    || !api.checkGate(token, "rebaked_engineer_auto_tracking_" + item.id))
    return false;
  const hits = (data.targets ?? []).filter(entry =>
    entry?.target?.actor && entry.hit !== false && entry.miss !== true);
  if (!hits.length) return false;
  return canvas.tokens.placeables.some(turret =>
    turret.actor?.type === "deployable"
    && api.getLAFlag(turret.document, "ownerActorUuid") === token.actor?.uuid
    && api.getMinGridDistance(attacker, turret) <= 3
    && hits.some(entry => api.getMinGridDistance(turret, entry.target) <= 10
      && api.hasLineOfSight(turret, entry.target)));
}

reactions.activationCode:
async function activation(type, data, token, item, name, api) {
  const gmId = api.getActiveGMId();
  if (!gmId || !game.users.get(gmId)?.active) {
    ui.notifications.warn("Auto-Tracking requires an active GM.");
    return;
  }
  const attackerId = data.triggeringToken?.id;
  const hitIds = [...new Set((data.targets ?? [])
    .filter(entry => entry?.target?.actor
      && entry.hit !== false && entry.miss !== true)
    .map(entry => entry.target.id))];
  api.afterFlow(data, () => data.sendMessageToReactor({
    attackerId, hitIds
  }, gmId, { wait: true }));
}

reactions.onMessage:
async function onMessage(type, data, token, item, name, api) {
  if (!game.user.isGM) return false;
  const attacker = canvas.tokens.get(data.attackerId);
  if (!attacker?.actor || !api.isFriendly(token, attacker)
    || !api.hasReactionAvailable(token)) return false;
  const turrets = canvas.tokens.placeables.filter(other =>
    other.actor?.type === "deployable"
    && api.getLAFlag(other.document, "ownerActorUuid") === token.actor?.uuid
    && api.getMinGridDistance(attacker, other) <= 3);
  const hits = (data.hitIds ?? []).map(id => canvas.tokens.get(id))
    .filter(target => target?.actor);
  const pairs = turrets.flatMap(turret => hits
    .filter(target => api.getMinGridDistance(turret, target) <= 10
      && api.hasLineOfSight(turret, target))
    .map(target => ({ turret, target })));
  if (!pairs.length) return false;
  const answer = await api.askCard({
    title: "AUTO-TRACKING", item, originToken: token,
    relatedToken: attacker, owner: token,
    description: attacker.name + " hit a target within a nearby turret's Range. Spend the Engineer's Reaction to fire one turret at that target?",
    yesText: "Fire Turret", noText: "Decline"
  });
  if (!answer?.confirmed) return false;
  const selectedTurret = (await api.chooseToken(token, {
    title: "AUTO-TRACKING — TURRET", count: 1, soft: true,
    filter: other => pairs.some(pair => pair.turret.id === other.id),
    description: "GM: choose a turret within Range 3 of the allied attacker."
  }))?.[0];
  if (!selectedTurret) return false;
  const targets = pairs.filter(pair => pair.turret.id === selectedTurret.id)
    .map(pair => pair.target);
  const target = targets.length === 1 ? targets[0]
    : (await api.chooseToken(selectedTurret, {
      title: "AUTO-TRACKING — HIT TARGET", count: 1, soft: true,
      filter: other => targets.some(hit => hit.id === other.id),
      description: "GM: choose one target the allied character just hit."
    }))?.[0];
  if (!target?.actor || !targets.some(hit => hit.id === target.id))
    return false;
  if (!await api.consumeOncePerRound(token,
    "rebaked_engineer_auto_tracking_" + item.id)) return false;
  await api.setReaction(token, false);
  const tier = Number(api.getTier(token)) || 1;
  await api.executeBasicAttack(selectedTurret.actor, {
    targets: [target], fxSourceToken: selectedTurret,
    attack_type: "Ranged", flat_bonus: tier,
    damage: [{ val: String(3 + tier), type: "Kinetic" }]
  });
  return true;
}

reactions.activationCode:
async function activation(triggerType, triggerData, reactorToken, item, activationName, api) {
    const speed = Number(reactorToken.actor?.system?.speed) || 0;

    const chainAxe = api.findItemByLid(
        reactorToken,
        "npc-rebake_npcf_chain_axe_berserker"
    );

    if (!chainAxe) {
        ui.notifications.warn(`${reactorToken.name}: Avalanche Charge could not find the Chain Axe.`);
        return;
    }

    if (speed <= 0) {
        ui.notifications.warn(`${reactorToken.name}: Avalanche Charge could not determine the Berserker's Speed.`);
        return;
    }

    ui.notifications.info(`${reactorToken.name}: Select a destination exactly ${speed} spaces away in a straight line.`);

    const moved = await api.moveToken(reactorToken, {
        range: speed,
        free: true,
        urgent: true,
        title: "AVALANCHE CHARGE",
        description: `Move exactly ${speed} spaces in a straight line. This movement ignores engagement and does not provoke reactions.`
    });

    if (!moved) return;

    const juggernaut = api.findItemByLid(reactorToken,
        "npc-rebake_npcf_juggernaut_berserker");
    if (juggernaut) {
        const targets = await api.chooseToken(reactorToken, {
            title: "JUGGERNAUT — CHARGE PATH",
            count: 30, includeSelf: false, soft: true,
            allowEmptyConfirm: true, urgent: true,
            description: "GM: select every character, allied or hostile, adjacent to any part of Avalanche Charge's path or its final position. Confirm with none if there are no affected characters."
        }) ?? [];
        if (targets.length) {
            const results = await api.executeSaveVsEffect(targets, {
                stat: "HULL", title: "Juggernaut", origin: reactorToken,
                cardDescription: "Every selected character makes a Hull save. Any failure falls Prone."
            });
            for (let index = 0; index < targets.length; index++) {
                if (!results?.[index]?.result?.completed || results[index].passed) continue;
                await api.applyEffectsToTokens({
                    tokens: [targets[index]], effectNames: ["prone"],
                    note: "Juggernaut"
                });
            }
        }
    }

    const adjacent = api.getTokensInRange(reactorToken, {
        range: 1,
        includeSelf: false,
        includeHidden: true,
        includeDefeated: false,
        includeDeployables: true
    }).filter((target) => target?.actor);

    if (!adjacent.length) {
        ui.notifications.info(`${reactorToken.name}: Avalanche Charge has no adjacent character to attack.`);
        return;
    }

    const target = adjacent[Math.floor(Math.random() * adjacent.length)];

    ui.notifications.info(`${reactorToken.name}: Avalanche Charge targets ${target.name}.`);

    await api.attackWith(chainAxe, [target], {
        fxSourceToken: reactorToken
    });
}

