async function onMessage(type, data, token, item, name, api) {
  if (!game.user.isGM) return false;
  const acting = canvas.tokens.get(data.actingId);
  if (!acting?.actor || !api.isHostile(token, acting)
    || !api.hasLineOfSight(token, acting)) return false;
  const answer = await api.askCard({
    title: "BLIP", item, originToken: token, owner: token,
    description: acting.name + " is taking an action in line of sight. Teleport an ally within Sensors 5 spaces as a Reaction?",
    yesText: "Use Blip", noText: "Decline"
  });
  if (!answer?.confirmed) return false;
  if (!api.hasReactionAvailable(token)
    || !api.checkGate(token, "rebaked_mirage_blip_" + item.id)) return false;
  const ally = (await api.chooseToken(token, {
    title: "BLIP — ALLY TO TELEPORT", count: 1,
    range: "sensors", includeSelf: true, soft: false,
    filter: candidate => api.isFriendly(token, candidate),
    description: "GM: choose one allied character in Sensors to teleport up to 5 spaces."
  }))?.[0];
  if (!ally?.actor || !api.isFriendly(token, ally)
    || api.getMinGridDistance(token, ally) > api.getSensorRange_WithBonus(token)) return false;
  const moved = await api.moveTokenRuler(ally, {
    range: 5, cost: 0, free: true, action: "blink", urgent: true,
    title: "BLIP — TELEPORT " + ally.name,
    description: "GM: teleport this ally to a free space within 5."
  });
  if (!moved) return false;
  if (!await api.consumeOncePerRound(token,
    "rebaked_mirage_blip_" + item.id)) return false;
  await api.setReaction(token, false);
  return true;
}

