async function activation(type, data, token, item, name, api) {
    const key = "rebakedBombardSpecialShell";
    const reloadFlags = { rebakedBombardShellReloadItemId: item.id };
    if (type === "onInitAttack" && api.findEffectsOnToken(
      token, "Bombard Cannon — Reload Required", { extraFlags: reloadFlags }
    ).length) {
      ui.notifications.warn("Bombard Cannon is marked Reload Required. Resolve a reload when appropriate; this attack may continue.");
    }
    const options = [
      { lid: "npc-rebake_npcf_bunker_buster_bombard", label: "Bunker Buster" },
      { lid: "npc-rebake_npcf_earthshaker_shells_bombard", label: "Earthshaker" },
      { lid: "npc-rebake_npcf_high_impact_shells_bombard", label: "High-Impact" }
    ].filter(shell => api.findItemByLid(token.actor, shell.lid));
    if (type === "onInitAttack") {
      if (!options.length) return;
      const choice = await api.startChoiceCard({
        title: "BOMBARD CANNON — SPECIAL SHELL", item, originToken: token,
        owner: token, mode: "or",
        description: "Fire exactly one special shell, or use the normal Bombard Cannon. A special shell requires reloading unless two or more characters are targeted.",
        choices: [
          { text: "Standard Shell", icon: "fas fa-crosshairs" },
          ...options.map(shell => ({ text: shell.label, icon: "fas fa-bomb" }))
        ]
      });
      const selected = choice?.choiceIdx > 0 ? options[choice.choiceIdx - 1]?.label : null;
      if (selected) api.setFlowFlag(data, key, selected);
      return;
    }
    const selected = api.getFlowFlag(data, key);
    if (!selected) return;
    if (type === "onAttack") {
      const ids = [...new Set((data.targets ?? []).map(target => target?.id).filter(Boolean))];
      api.setFlowFlag(data, key + "TargetIds", ids);
      api.afterFlow(data, async () => {
        const state = data.flowState?.data;
        if (!(state?.attack_rolls?.length || state?.attack_results?.length)) return;
        const targets = ids.map(id => canvas.tokens.get(id)).filter(Boolean);
        if (selected === "Bunker Buster") {
          ui.notifications.info("Bunker Buster: GM, apply "
            + api.tierValue(token, [10, 20, 30])
            + " AP Explosive damage to objects and terrain in the affected area.");
          let chosen = targets[0];
          if (targets.length > 1) chosen = (await api.chooseToken(token, {
            title: "BUNKER BUSTER — CHARACTER", count: 1, soft: true,
            filter: candidate => ids.includes(candidate.id),
            description: "Choose one character in the Blast for a Hull save."
          }))?.[0];
          if (chosen) {
            const saves = await api.executeSaveVsEffect([chosen], {
              stat: "HULL", title: "Bunker Buster", origin: token,
              cardDescription: "On failure, Shredded until the end of the target's next turn."
            });
            if (saves?.[0]?.result?.completed && !saves[0].passed)
              await api.applyEffectsToTokens({
                tokens: [chosen], effectNames: ["shredded"], note: "Bunker Buster",
                duration: api.untilEndOfTurn(chosen, 1)
              });
          }
        }
        if (selected === "Earthshaker") {
          let chosen = targets[0];
          if (targets.length > 1) chosen = (await api.chooseToken(token, {
            title: "EARTHSHAKER — CHARACTER", count: 1, soft: true,
            filter: candidate => ids.includes(candidate.id),
            description: "Choose one character in the Blast for a Hull save."
          }))?.[0];
          if (chosen) {
            const saves = await api.executeSaveVsEffect([chosen], {
              stat: "HULL", title: "Earthshaker Shells", origin: token,
              cardDescription: "On failure, knocked Prone."
            });
            if (saves?.[0]?.result?.completed && !saves[0].passed)
              await api.applyEffectsToTokens({
                tokens: [chosen], effectNames: ["prone"], note: "Earthshaker Shells"
              });
          }
          const tht = game.modules.get("terrain-height-tools")?.api
            ?? globalThis.terrainHeightTools;
          const hardCover = tht?.getTerrainTypes?.().filter(type =>
            type.name?.localeCompare("Hard Cover", undefined,
              { sensitivity: "base" }) === 0) ?? [];
          if (!tht?.paintCells || hardCover.length !== 1) {
            ui.notifications.warn("Earthshaker: THT Hard Cover terrain type unavailable or ambiguous; GM, place two Size 1 segments manually.");
          } else {
            const impactMarks = await api.placeZone(token, {
              type: "Blast", size: 0, count: 1,
              title: "EARTHSHAKER — IMPACT HEX",
              description: "GM: click the exact hex targeted by this attack. The next picker places two cover segments within Range 3.",
              centerLabel: "IMPACT", fillColor: "#a88044", borderColor: "#ffd18a"
            });
            const impact = impactMarks?.[0]?.template;
            if (impact) {
              try {
                const tm = game.modules.get("templatemacro")?.api;
                const impactCells = tm?.getTemplateOccupiedOffsets?.(impact);
                if (impactCells?.size !== 1) {
                  ui.notifications.warn("Earthshaker: impact marker does not highlight exactly one hex; no terrain was painted.");
                  return;
                }
                const [impactRow, impactCol] = [...impactCells][0]
                  .split(",").map(Number);
                const impactCenter = api.getHexCenter(impactCol, impactRow);
                const placed = await api.placeZone(token, {
                  type: "Blast", size: 0, count: 2, range: 3,
                  rangeOrigin: impactCenter,
                  title: "EARTHSHAKER — TWO COVER HEXES",
                  description: "GM: select two distinct free hexes within Range 3 of the impact hex. Each becomes Size 1 Hard Cover (10 HP, Evasion 5).",
                  centerLabel: "COVER", fillColor: "#816d4e", borderColor: "#f6d99d"
                });
                const markers = placed?.map(result => result.template)
                  .filter(Boolean) ?? [];
                try {
                  if (markers.length !== 2) {
                    ui.notifications.warn("Earthshaker: exactly two cover hexes are required; no terrain was painted.");
                  } else {
                    const selected = markers.map(marker =>
                      tm.getTemplateOccupiedOffsets(marker));
                    if (selected.some(offsets => offsets?.size !== 1)) {
                      ui.notifications.warn("Earthshaker: each cover marker must highlight exactly one hex; no terrain was painted.");
                      return;
                    }
                    const cells = selected.map(offsets => {
                      const [row, col] = [...offsets][0].split(",").map(Number);
                      return [row, col];
                    });
                    const keys = cells.map(([row, col]) => row + ":" + col);
                    const occupied = new Set(canvas.tokens.placeables.flatMap(other =>
                      api.getOccupiedCenters(other).map(center => {
                        const offset = api.pixelToOffset(center.x, center.y);
                        return offset.row + ":" + offset.col;
                      })));
                    if (new Set(keys).size !== 2 || keys.some(key => occupied.has(key))
                      || cells.some(([row, col]) => tht.getShapes(col, row)
                        .some(shape => shape.terrainTypeId === hardCover[0].id))) {
                      ui.notifications.warn("Earthshaker: choose two distinct free hexes without existing Hard Cover; no terrain was painted.");
                    } else {
                      await tht.paintCells(cells, {
                        id: hardCover[0].id,
                        height: hardCover[0].usesHeight
                          ? Number(canvas.scene.grid.distance ?? 1) : 0,
                        elevation: Number(impact.elevation ?? 0)
                      }, { mode: "additiveMerge" });
                      ui.notifications.info("Earthshaker: two Hard Cover hexes placed. GM tracks 10 HP and Evasion 5 per segment.");
                    }
                  }
                } finally {
                  for (const marker of markers) await marker.delete();
                }
              } finally { await impact.delete(); }
            }
          }
        }
        if (ids.length < 2) {
          if (!api.findEffectsOnToken(token, "Bombard Cannon — Reload Required",
            { extraFlags: reloadFlags }).length)
            await api.applyEffectsToTokens({
              tokens: [token],
              effectNames: [{ name: "Bombard Cannon — Reload Required",
                icon: item.img, isCustom: true }],
              note: "Special shell fired at fewer than two characters. Reload before firing again.",
              duration: { label: "indefinite" }, notify: false
            }, reloadFlags);
        }
      });
      return;
    }
    if (selected !== "High-Impact") return;
    const count = (api.getFlowFlag(data, key + "TargetIds") ?? []).length;
    const distance = Math.min(5, 2 + Math.max(0, count - 1));
    for (const hit of data.targets ?? []) {
      const target = hit?.target;
      if (!target?.actor) continue;
      await api.moveTokenRuler(target, {
        range: distance, cost: 0, free: true, action: "forced", urgent: true,
        title: "HIGH-IMPACT SHELLS — KNOCKBACK " + distance,
        description: "GM: move directly away from the Bombard or the Blast center; stop at obstructions."
      });
    }
  }

