reactions.onMessage:
async function onMessage(type, data, reactorToken, item, name, api) {
const hasSuperiorRam = !!api.findItemByLid(
    reactorToken,
    "npcf_superior_ram_breacher"
);

const ramRange = hasSuperiorRam ? 10 : 6;

const moved = await api.moveToken(reactorToken, {
    range: ramRange,
    cost: 0,
    action: "forced",
    title: "BREACH RAM",
    description: `Move up to ${ramRange} spaces in a straight line. Resolve any obstructions in the path manually. Do not end this movement overlapping another character.`
});

if (!moved)
    return;

const victims = await api.chooseToken(reactorToken, {
    count: -1,
    includeSelf: false,
    title: "BREACH RAM — TARGETS",
    description: "Select all characters that were in the Breacher's path."
});

if (!victims?.length)
    return;

const superiorRamBonusId =
    `superior-ram-${reactorToken.id}-${foundry.utils.randomID()}`;

if (hasSuperiorRam) {
    await api.addGlobalBonus(
        reactorToken.actor,
        {
            id: superiorRamBonusId,
            name: "Superior Ram",
            type: "difficulty",
            val: 1,
            rollTypes: ["check"],
            applyToTargetter: true,

            context: {
                rammerTokenId: reactorToken.id
            },

            condition: (state, actor, data, context) => {
                const path = String(
                    data?.path ?? ""
                ).toLowerCase();

                return path.includes("agi") &&
                    state.la_extraData?.targetTokenId ===
                        context.rammerTokenId;
            }
        },
        {
            origin: reactorToken
        }
    );
}

let saves;

try {
    saves = await api.executeForceCheck(
        "AGI",
        victims,
        {
            saveVs: reactorToken,
            sendToOwner: true,
            title: hasSuperiorRam
                ? "Breach Ram — Agility Save (+1 Difficulty)"
                : "Breach Ram — Agility Save"
        }
    );
}
finally {
    if (hasSuperiorRam) {
        await api.removeGlobalBonus(
            reactorToken.actor,
            bonus => bonus.id === superiorRamBonusId
        );
    }
}

const failed = saves.results
    .filter(result =>
        result.completed && !result.passed
    )
    .map(result => result.token);

if (failed.length) {

await api.knockBackToken(failed, -1, {
    triggeringToken: reactorToken,
    actionName: "Breach Ram",
    item,
    title: "BREACH RAM — PUSH",
    description: "Move each failed character out of the Breacher's path as directly as possible."
});

await api.applyEffectsToTokens({
    tokens: failed,
    effectNames: ["prone"],
    note: "Breach Ram"
});
}
const breachAndClear = api.findItemByLid(reactorToken.actor,
  "npc-rebake_npcf_breach_and_clear_breacher");
const shotgun = api.findItemByLid(reactorToken.actor,
  "npc-rebake_npcf_dual_shotguns_breacher");
if (!breachAndClear || !shotgun) return;
const pathIds = new Set(victims.map(victim => victim.id));
const chosen = await api.chooseToken(reactorToken, {
  title: "BREACH AND CLEAR — SHOTGUN TARGETS", count: -1,
  includeSelf: false, soft: true,
  filter: candidate => pathIds.has(candidate.id),
  description: "GM: choose any characters in the Breach Ram path to attack once each with Dual Shotguns. Each hit deals half damage."
});
for (const target of chosen ?? []) {
  await shotgun.setFlag("lancer-automations", "rebakedBreachAndClearActive", reactorToken.id);
  try {
    await api.beginWeaponAttackFlow(shotgun, { targets: [target] },
      { rebakedBreachAndClear: true });
  } finally {
    await shotgun.unsetFlag("lancer-automations", "rebakedBreachAndClearActive");
  }
}
}

