reactions.onMessage:
async function onMessage(type, data, token, item, name, api) {
  if (!game.user.isGM) return false;
  const own = () => canvas.scene.templates.filter(zone =>
    zone.getFlag("lancer-automations", "rebakedWitchChain")
      ?.ownerActorUuid === token.actor?.uuid);
  const clear = async zones => {
    for (const zone of zones) {
      const mark = zone.getFlag("lancer-automations", "rebakedWitchChain");
      const target = canvas.tokens.get(mark.targetId);
      if (target?.actor) await api.removeEffectsByNameFromTokens({
        tokens: [target], effectNames: ["Chain"],
        extraFlags: { rebakedWitchChainZone: zone.id }, notify: false
      });
      else if (mark.targetActorUuid) {
        const actor = await fromUuid(mark.targetActorUuid);
        const ids = Array.from(actor?.effects ?? []).filter(effect =>
          effect.name === "Chain" && effect.getFlag(
            "lancer-automations", "rebakedWitchChainZone") === zone.id
        ).map(effect => effect.id);
        if (ids.length) await actor.deleteEmbeddedDocuments("ActiveEffect", ids);
      }
      await zone.delete();
    }
  };
  if (["onDestroyed", "onExitCombat", "onStatusApplied"].includes(data.event)
    || (data.event === "onTokenRemoved" && data.subjectId === token.id)) {
    await clear(own());
    return true;
  }
  if (data.event === "onTechHit") {
    for (const targetId of data.targetIds ?? []) {
      const target = canvas.tokens.get(targetId);
      if (!target?.actor) continue;
      const placed = await api.placeZone(target, {
        type: "Blast", size: 0, range: 3, count: 1,
        title: "CHAIN — ANCHOR", centerLabel: "CHAIN",
        fillColor: "#654f83", borderColor: "#c7a7ef",
        description: "GM: mark a space within Range 3 of " + target.name
          + ". The target suffers Heat and Jammed if it moves more than 3 spaces from this point."
      });
      const zone = placed?.[0]?.template;
      if (!zone) continue;
      const size = canvas.grid.size;
      const anchor = { document: {
        x: zone.x - size / 2, y: zone.y - size / 2,
        width: 1, height: 1, elevation: zone.elevation ?? 0,
        getCenterPoint: () => ({ x: zone.x, y: zone.y })
      } };
      if (api.getMinGridDistance(target, anchor, null, false) > 3) {
        await zone.delete();
        ui.notifications.warn("Chain anchor must be within Range 3 of the target.");
        continue;
      }
      await clear(own().filter(old => old.getFlag(
        "lancer-automations", "rebakedWitchChain")?.targetId === target.id));
      await zone.setFlag("lancer-automations", "rebakedWitchChain", {
        ownerActorUuid: token.actor.uuid, ownerTokenId: token.id,
        targetId: target.id, targetActorUuid: target.actor.uuid,
        itemId: item.id
      });
      await api.applyEffectsToTokens({
        tokens: [target],
        effectNames: [{ name: "Chain", icon: item.img, isCustom: true }],
        note: "Moving more than 3 spaces from the marked point deals tier Heat and Jammed, then ends Chain.",
        duration: { label: "indefinite" }
      }, { rebakedWitchChainZone: zone.id });
    }
    return true;
  }
  const zones = own().filter(zone => zone.getFlag(
    "lancer-automations", "rebakedWitchChain")?.targetId === data.subjectId);
  if (data.event === "onTokenRemoved") {
    await clear(zones); return true;
  }
  const subject = canvas.tokens.get(data.subjectId);
  if (!subject?.actor) return false;
  for (const zone of zones) {
    const size = canvas.grid.size;
    const anchor = { document: {
      x: zone.x - size / 2, y: zone.y - size / 2,
      width: 1, height: 1, elevation: zone.elevation ?? 0,
      getCenterPoint: () => ({ x: zone.x, y: zone.y })
    } };
    if (api.getMinGridDistance(subject, anchor, null, false) <= 3) continue;
    await clear([zone]);
    await api.executeDamageRoll(token, [subject],
      String(api.tierValue(token, [2, 3, 4])), "Heat", "Chain");
    await api.applyEffectsToTokens({
      tokens: [subject], effectNames: ["jammed"], note: "Chain",
      duration: api.untilEndOfTurn(subject, 1)
    }, { rebakedWitchChainSource: item.id });
  }
  return true;
}

