async function activation(type, data, token, item, name, api) {
  const target = (await api.chooseToken(token, {
    title: "CHARGED SLASH", count: 1, range: 2,
    includeSelf: false, soft: false,
    description: "GM: choose a character within Range 2 to make an Agility save."
  }))?.[0];
  if (!target?.actor || api.getMinGridDistance(token, target) > 2) return;
  await api.setItemResource(item, false);
  const saves = await api.executeSaveVsEffect([target], {
    stat: "AGILITY", title: "Charged Slash", origin: token,
    cardDescription: "Success: Impaired until end of next turn. Failure: choose Jammed, or one of the target's equipped weapons deals damage and then Impaired."
  });
  if (!saves?.[0]?.result?.completed) return;
  if (!saves[0].passed) {
    const weapons = api.getWeapons(target)
      .filter(feature => !feature.system?.destroyed);
    if (!weapons.length) {
      await api.applyEffectsToTokens({
        tokens: [target], effectNames: ["jammed"], note: "Charged Slash",
        duration: api.untilEndOfTurn(target, 1)
      }, { rebakedRoninChargedSlash: item.id });
      return;
    }
    const ownerId = api.getTokenOwnerUserId(target);
    const chooser = ownerId && game.users.get(ownerId)?.active
      ? ownerId : api.getActiveGMId();
    const choice = await api.askCard({
      title: "CHARGED SLASH — FAILED SAVE", item,
      originToken: token, relatedToken: target, owner: target,
      userIdControl: chooser,
      description: target.name + ": choose Jammed until the end of your next turn, or take damage from one of your equipped weapons and become Impaired instead.",
      yesText: "Become Jammed", noText: "Weapon Damage + Impaired"
    });
    if (!choice) return;
    if (choice.confirmed) {
      await api.applyEffectsToTokens({
        tokens: [target], effectNames: ["jammed"], note: "Charged Slash",
        duration: api.untilEndOfTurn(target, 1)
      }, { rebakedRoninChargedSlash: item.id });
      return;
    }
    const weapon = await api.pickCard(weapons, {
      title: "CHARGED SLASH — WEAPON DAMAGE", item,
      originToken: token,
      description: "GM: choose one of the target's equipped weapons. The target takes that weapon's damage without an attack roll."
    });
    if (!weapon) return;
    const tier = Math.max(0, Math.min(2,
      Number(weapon.system?.tier_override || target.actor.system?.tier || 1) - 1));
    const raw = weapon.system?.damage ?? [];
    const profile = weapon.system?.profiles?.[
      Number(weapon.system?.selected_profile_index ?? 0)];
    const damage = profile?.damage ??
      (Array.isArray(raw[0]) ? raw[tier] ?? [] : raw);
    if (damage.length) await api.executeDamageRoll(token, [target],
      null, null, "Charged Slash — " + weapon.name,
      { damage, add_burn: true });
  }
  await api.applyEffectsToTokens({
    tokens: [target], effectNames: ["impaired"], note: "Charged Slash",
    duration: api.untilEndOfTurn(target, 1)
  }, { rebakedRoninChargedSlash: item.id });
}

