async function activation(type, data, token, item, name, api) {
  const countKey = "rebakedBombardClusterTargetCount";
  const injectedKey = "rebakedBombardClusterDamageInjected";
  if (type === "onAttack") {
    const ids = (data.targets ?? []).map(target => target?.id).filter(Boolean);
    api.setFlowFlag(data, countKey, new Set(ids).size);
    return;
  }
  if (api.getFlowFlag(data, injectedKey)) return;
  const beyondFirst = Math.max(0, Number(api.getFlowFlag(data, countKey) ?? 0) - 1);
  if (!beyondFirst) return;
  const allHits = (data.flowState?.data?.hit_results ?? [])
    .filter(result => result?.hit && result.target?.id)
    .map(result => result.target.id);
  const currentHits = (data.targets ?? [])
    .map(entry => entry?.target?.id).filter(Boolean);
  const ids = [...new Set(allHits.length ? allHits : currentHits)];
  if (!ids.length) return;
  const bonusId = "rebaked-bombard-cluster-" + item.id;
  if ((data.flowState?.la_extraData?.flow_bonus ?? [])
    .some(bonus => bonus.id === bonusId)) return;
  api.setFlowFlag(data, injectedKey, true);
  await api.injectBonusToFlowState(data.flowState, {
    id: bonusId, name: "Cluster Munitions",
    type: "damage", damageMode: "add",
    damage: [{
      val: String(beyondFirst * Number(api.tierValue(token, [2, 3, 4]))),
      type: "Explosive"
    }],
    applyTo: ids, rollTypes: ["damage"]
  });
}

