reactions.onMessage:
async function onMessage(type, data, token, item, name, api) {
    if (!game.user.isGM) return false;
    const chosen = await api.chooseToken(token, {
      title: "COMMAND OVERRIDE — SELECT DRONES", count: -1,
      range: "sensors", includeSelf: false, soft: true,
      filter: other => other?.actor?.type === "deployable",
      description: "GM: choose up to three Drone-tagged deployable tokens within Sensors, including other characters' drones. Do not select non-drone deployables."
    });
    const drones = [...new Map((chosen ?? [])
      .filter(other => other?.actor?.type === "deployable")
      .map(other => [other.id, other])).values()].slice(0, 3);
    if ((chosen ?? []).length > 3)
      ui.notifications.info("Command Override: only the first three selected drones are used.");
    const swarmFlag = "hecatoncheiresRazorSwarm";
    const availableSwarms = (canvas.scene?.templates ?? []).filter(template =>
      !!template.getFlag("lancer-automations", swarmFlag));
    const selectedSwarms = [];
    while (drones.length + selectedSwarms.length < 3) {
      const remaining = availableSwarms.filter(template =>
        !selectedSwarms.some(selected => selected.id === template.id));
      if (!remaining.length) break;
      const choice = await api.startChoiceCard({
        title: "COMMAND OVERRIDE — RAZOR SWARM DRONE", item,
        originToken: token, owner: token, mode: "or",
        description: "GM: choose a Hecatoncheires Razor Swarm within Sensors, if any. Its Blast 1 area counts as a Drone. Select Done to proceed.",
        choices: [
          ...remaining.map(template => ({
            text: "Razor Swarm — "
              + (template.getFlag("lancer-automations", swarmFlag)?.ownerName
                ?? template.id),
            icon: "fas fa-bugs"
          })),
          { text: "Done", icon: "fas fa-check" }
        ]
      });
      if (!choice || choice.choiceIdx == null
        || choice.choiceIdx >= remaining.length) break;
      selectedSwarms.push(remaining[choice.choiceIdx]);
    }
    if (!drones.length && !selectedSwarms.length) return false;
    await api.setItemResource(item, false);
    await api.executeDamageRoll(token, [token], "4", "Heat", "Command Override");
    for (const drone of drones) await api.moveTokenRuler(drone, {
      range: 3, cost: 0, free: true, action: "forced", urgent: true,
      title: "COMMAND OVERRIDE — MOVE " + drone.name,
      description: "GM: move this Drone up to 3 spaces in any direction; adjudicate obstructions."
    });
    for (const swarm of selectedSwarms) {
      const move = await api.placeZone(token, {
        type: "Blast", size: 1, range: 3,
        rangeOrigin: { x: swarm.x, y: swarm.y }, count: 1,
        title: "COMMAND OVERRIDE — MOVE RAZOR SWARM",
        description: "GM: move this Hecatoncheires Razor Swarm up to 3 spaces from its current position. Cancel to leave it in place."
      });
      const marker = move?.[0]?.template;
      if (!marker) continue;
      try {
        await swarm.update({ x: marker.x, y: marker.y });
        swarm.object?.refresh();
      } finally { await marker.delete(); }
    }
    const adjacentIds = new Set(canvas.tokens.placeables
      .filter(other => other?.actor && other.actor.type !== "deployable"
        && drones.some(drone => api.getMinGridDistance(drone, other) <= 1))
      .map(other => other.id));
    for (const swarm of selectedSwarms) {
      const measured = await api.placeZone(token, {
        type: "Blast", size: 2, count: 1,
        x: swarm.x, y: swarm.y, hidden: true,
        elevation: swarm.elevation,
        title: "COMMAND OVERRIDE — SWARM ADJACENCY"
      });
      const measureZone = measured?.[0]?.template;
      if (!measureZone) continue;
      try {
        for (const other of api.tokensInTemplate(measureZone))
          if (other?.actor && other.actor.type !== "deployable")
            adjacentIds.add(other.id);
      } finally { await measureZone.delete(); }
    }
    const adjacent = [...adjacentIds].map(id => canvas.tokens.get(id))
      .filter(Boolean);
    for (const target of adjacent) {
      const saves = await api.executeSaveVsEffect([target], {
        stat: "SYSTEMS", title: "Command Override", origin: token,
        cardDescription: "Failure: take tier Burn and gain Lock On. This Burn counts as Razor Swarm Burn."
      });
      if (!saves?.[0]?.result?.completed || saves[0].passed) continue;
      await api.executeDamageRoll(token, [target],
        String(api.tierValue(token, [2, 3, 4])), "Burn",
        "Razor Swarm — Command Override", { add_burn: true });
      await api.applyEffectsToTokens({
        tokens: [target], effectNames: ["lockon"], note: "Command Override"
      });
    }
    return true;
  }

