async function activation(type, data, token, item, name, api) {
    const movedKey = "rebakedScourerMovedSinceTurnEnd";
    const cooledKey = "rebakedScourerCoolingThisTurn";
    if (type === "onTurnEnd") {
      await api.addActorFlags(token.actor, { [movedKey]: false });
      return;
    }
    if (type === "onMove" || type === "onInvoluntaryMove") {
      await api.addActorFlags(token.actor, { [movedKey]: true });
      return;
    }
    const moved = api.getActorFlags(token.actor, movedKey) === true;
    await api.addActorFlags(token.actor, { [cooledKey]: !moved });
    const rangeBonusId = "rebaked-scourer-thermal-overload-range";
    await api.removeGlobalBonus(token.actor, bonus => bonus.id === rangeBonusId);
    const overload = api.findItemByLid(token.actor,
      "npc-rebake_npcf_thermal_overload_scourer");
    const lance = api.findItemByLid(token.actor,
      "npc-rebake_npcf_thermal_lance_scourer");
    if (moved && overload && !overload.system?.destroyed && lance) {
      await api.addGlobalBonus(token.actor, {
        id: rangeBonusId, name: "Thermal Overload — Range",
        type: "range", rangeType: "Range", rangeMode: "add", val: 4,
        itemId: lance.id, rollTypes: ["attack"]
      }, { origin: token });
    }
    if (moved) return;
    const heat = Number(token.actor.system?.heat?.value ?? 0);
    if (heat > 0) await token.actor.update({ "system.heat.value": 0 });
    const laser = api.findItemByLid(token.actor,
      "npc-rebake_npcf_pulse_laser_scourer");
    if (laser) await api.setItemResource(laser, true);
  }

