function evaluate(type, data, token, item, name, api) {
  if (type === "onAttack") {
    const attacker = data.triggeringToken;
    if (!attacker?.actor || attacker.id === token.id
      || !api.isHostile(token, attacker)
      || api.getMinGridDistance(token, attacker) > 5) return false;
    const kind = String(api.getWeaponType(data.weapon)
      ?? data.attackType ?? "").toLowerCase();
    return ["cqb", "rifle", "launcher", "cannon", "ranged"].includes(kind);
  }
  return data.triggeringToken?.id === token.id
    && data.weapon?.system?.lid === "npc-rebake_npcf_carbon_fiber_sword_ronin"
    && (data.targets ?? []).some(hit => hit?.target?.actor
      && api.findEffectsOnToken(hit.target, "Ronin's Mark", {
        extraFlags: { rebakedRoninMarkSourceId: token.id }
      }).length > 0);
}

