async function activation(type, data, token, item, name, api) {
  const gmId = api.getActiveGMId();
  if (!gmId || !game.users.get(gmId)?.active) {
    ui.notifications.warn("Counter-Ballistic Suite requires an active GM.");
    return;
  }
  if (type === "onAttack") {
    await data.sendMessageToReactor({ action: "mark",
      attackerId: data.triggeringToken.id }, gmId, { wait: true });
    return;
  }
  const markedHits = [...new Set((data.targets ?? [])
    .map(hit => hit?.target).filter(target => target?.actor
      && api.findEffectsOnToken(target, "Ronin's Mark", {
        extraFlags: { rebakedRoninMarkSourceId: token.id }
      }).length > 0))];
  if (!markedHits.length) return;
  const selectedId = await data.sendMessageToReactor({
    action: "consume", targetIds: markedHits.map(target => target.id)
  }, gmId, { wait: true });
  const target = markedHits.find(hit => hit.id === selectedId);
  if (!target) return;
  await api.injectBonusToFlowState(data.flowState, {
    id: "rebaked-ronin-counter-ballistic-" + item.id + "-" + target.id,
    name: "Counter-Ballistic Suite — Ronin's Mark",
    type: "damage", damageMode: "add",
    damage: [{ val: "1d6", type: "Kinetic" }],
    applyTo: [target.id], rollTypes: ["damage"]
  });
  await api.clearMarks(token, "Ronin's Mark", {
    flagKey: "rebakedRoninMarkSourceId"
  });
}

