async function onMessage(type, data, token, item, name, api) {
  if (!game.user.isGM) return false;
  if (data.action === "mark") {
    const attacker = canvas.tokens.get(data.attackerId);
    if (!attacker?.actor || !api.isHostile(token, attacker)
      || api.getMinGridDistance(token, attacker) > 5) return false;
    const answer = await api.askCard({
      title: "COUNTER-BALLISTIC SUITE", item,
      originToken: token, relatedToken: attacker, owner: token,
      description: attacker.name + " is making a ranged attack. Give them Ronin's Mark? This replaces any previous mark.",
      yesText: "Mark Attacker", noText: "Decline"
    });
    if (!answer?.confirmed) return false;
    await api.clearMarks(token, "Ronin's Mark", {
      flagKey: "rebakedRoninMarkSourceId"
    });
    await api.applyMark(token, [attacker], {
      effect: { name: "Ronin's Mark", icon: item.img, isCustom: true },
      note: "The Ronin may consume this mark on a Carbon Fiber Sword hit for +1d6 bonus damage.",
      duration: { label: "indefinite" },
      flagKey: "rebakedRoninMarkSourceId"
    });
    return true;
  }
  const choices = (data.targetIds ?? [])
    .map(id => canvas.tokens.get(id)).filter(Boolean);
  if (!choices.length) return false;
  const target = choices.length === 1 ? choices[0]
    : (await api.chooseToken(token, {
      title: "RONIN'S MARK — TARGET", count: 1,
      includeSelf: false, soft: true,
      filter: candidate => choices.some(hit => hit.id === candidate.id),
      description: "GM: choose one marked character hit by the Carbon Fiber Sword."
    }))?.[0];
  if (!target) return false;
  const answer = await api.askCard({
    title: "RONIN'S MARK", item, originToken: token,
    relatedToken: target, owner: token,
    description: "Consume Ronin's Mark on " + target.name
      + " to add 1d6 bonus damage to this Sword hit?",
    yesText: "Consume Mark", noText: "Keep Mark"
  });
  return answer?.confirmed ? target.id : false;
}

