reactions.evaluate:
function evaluate(type, data, token, item, name, api) {
  if (type === "onActivation")
    return data.triggeringToken?.id === token.id && data.item?.id === item.id;
  const targetId = api.getActorFlags(token.actor, "rebakedGoliathCrushTargetId");
  if (!targetId) return false;
  if (type === "onStatusApplied")
    return data.triggeringToken?.id === token.id
      && ["jammed", "stunned"].includes(String(data.statusId).toLowerCase());
  if (type === "onTurnStart" || type === "onDestroyed")
    return data.triggeringToken?.id === token.id;
  if (data.triggeringToken?.id !== targetId) return false;
  if (api.hasStatus(token, "jammed", "stunned")) return false;
  return (data.targets ?? []).some(target => target?.actor && target.id !== token.id);
}

