async function activation(type, data, token, item, name, api) {
  const key = "rebakedGoliathCrushTargetId";
  const flags = { rebakedGoliathCrushSource: item.id, sourceTokenId: token.id };
  const clear = async () => {
    const previous = canvas.tokens.get(api.getActorFlags(token.actor, key));
    if (previous) await api.removeEffectsByNameFromTokens({
      tokens: [previous], effectNames: ["Crush Targeting"],
      extraFlags: flags, notify: false
    });
    await api.removeActorFlags(token.actor, { [key]: true });
  };
  if (["onTurnStart", "onDestroyed", "onStatusApplied"].includes(type)) {
    await clear();
    return;
  }
  if (type === "onActivation") {
    const target = (await api.chooseToken(token, {
      title: "CRUSH TARGETING — TARGET", count: 1,
      range: "sensors", includeSelf: false, soft: false,
      filter: candidate => api.isHostile(token, candidate),
      description: "GM: choose a hostile character in Sensors and line of sight."
    }))?.[0];
    if (!target || !api.isHostile(token, target)
      || api.getMinGridDistance(token, target) > api.getSensorRange_WithBonus(token)) return;
    await clear();
    await api.addActorFlags(token.actor, { [key]: target.id });
    await api.applyEffectsToTokens({
      tokens: [target],
      effectNames: [{ name: "Crush Targeting", icon: item.img, isCustom: true }],
      note: "+3 Difficulty on attacks against anyone other than the Goliath.",
      duration: api.untilStartOfTurn(token, 1)
    }, flags);
    return;
  }
  const otherIds = [...new Set((data.targets ?? [])
    .filter(target => target?.actor && target.id !== token.id)
    .map(target => target.id))];
  if (!otherIds.length) return;
  await api.injectBonusToFlowState(data.flowState, {
    id: "rebaked-goliath-crush-targeting-" + item.id,
    name: "Crush Targeting", type: "difficulty", val: 3,
    applyTo: otherIds,
    rollTypes: type === "onInitTechAttack" ? ["tech_attack", "tech"] : ["attack"]
  });
}

