reactions.onMessage:
async function onMessage(type, data, token, item, name, api) {
  if (!game.user.isGM) return false;
  const ownerUuid = token.actor?.uuid;
  const owned = () => canvas.tokens.placeables.filter(other =>
    other.actor?.type === "deployable"
    && api.getLAFlag(other.document, "ownerActorUuid") === ownerUuid);
  if (data.event === "onDestroyed") {
    for (const turret of owned()) await turret.document.delete();
    return true;
  }
  if (data.event === "onDeploy") {
    const tier = Number(api.getTier(token)) || 1;
    for (const id of data.deployedIds ?? []) {
      const turret = canvas.tokens.get(id);
      if (!turret?.actor || !owned().some(other => other.id === id)) continue;
      const fortifications = api.findItemByLid(token.actor,
        "npc-rebake_npcf_deployable_fortifications_engineer");
      if (fortifications && !fortifications.system?.destroyed) {
        if (Number(turret.actor.system?.size) !== 1)
          await turret.actor.update({ "system.stats.size": 1 });
        if (!api.hasStatus(turret, "bulwark"))
          await api.applyEffectsToTokens({
            tokens: [turret], effectNames: ["bulwark"],
            note: "Deployable Fortifications: adjacent allies can use this turret as hard cover.",
            duration: { label: "indefinite" }, notify: false
          }, { rebakedEngineerFortifications: token.actor.uuid });
      }
      const sourceActor = game.actors.get(turret.document.actorId);
      if (sourceActor?.name !== "Engineer Turret")
        await sourceActor?.update({ name: "Engineer Turret" });
      if (turret.document.name !== "Engineer Turret")
        await turret.document.update({ name: "Engineer Turret" });
      await api.setActionOverlay(turret.actor, "Turret Attack (Auto)", {
        laCombat: "attack", attack_bonus: tier,
        attack_type: "Ranged",
        range: [{ type: "Range", val: 10 },
          ...(fortifications && !fortifications.system?.destroyed
            ? [{ type: "Threat", val: 3 }] : [])],
        damage: [{ val: String(3 + tier), type: "Kinetic" }]
      });
    }
    while (owned().length > 6) {
      const excess = (await api.chooseToken(token, {
        title: "DEPLOYABLE TURRET — MAXIMUM SIX",
        count: 1, soft: true,
        filter: other => owned().some(turret => turret.id === other.id),
        description: "GM: choose one of this Engineer's turrets to destroy; no more than six may remain."
      }))?.[0] ?? owned()[0];
      if (!excess) break;
      await excess.document.delete();
    }
    return true;
  }
  if (data.event !== "onTurnEnd"
    || api.hasStatus(token, "jammed")
    || api.hasStatus(token, "stunned")) return false;
  const tier = Number(api.getTier(token)) || 1;
  const designation = token.document.getFlag("lancer-automations",
    "rebakedEngineerTargetDesignation");
  const marked = designation?.targetId
    ? canvas.tokens.get(designation.targetId) : null;
  const directed = marked?.actor
    ? owned().filter(turret => api.getMinGridDistance(turret, marked) <= 10
      && api.hasLineOfSight(turret, marked)) : [];
  const directedIds = new Set();
  if (directed.length) {
    const chosen = await api.chooseToken(token, {
      title: "TARGET DESIGNATOR — DIRECT TURRETS",
      count: -1, soft: true, includeSelf: false,
      filter: other => directed.some(turret => turret.id === other.id),
      description: "GM: choose up to two turrets to attack " + marked.name
        + " instead of their nearest hostile. Leave unchosen turrets on their normal targeting."
    });
    if ((chosen ?? []).length > 2)
      ui.notifications.info("Target Designator: only the first two selected turrets are directed.");
    for (const turret of (chosen ?? []).slice(0, 2))
      directedIds.add(turret.id);
  }
  for (const turret of owned()) {
    if (!turret?.actor || api.hasStatus(turret, "shutdown")) continue;
    if (directedIds.has(turret.id)) {
      await api.executeBasicAttack(turret.actor, {
        targets: [marked], fxSourceToken: turret,
        attack_type: "Ranged", flat_bonus: tier,
        damage: [{ val: String(3 + tier), type: "Kinetic" }]
      });
      continue;
    }
    const candidates = canvas.tokens.placeables.filter(other => other?.actor
      && other.actor.type !== "deployable"
      && api.isHostile(turret, other)
      && api.getMinGridDistance(turret, other) <= 10
      && api.hasLineOfSight(turret, other));
    if (!candidates.length) continue;
    const nearestDistance = Math.min(...candidates.map(other =>
      api.getMinGridDistance(turret, other)));
    const nearest = candidates.filter(other =>
      api.getMinGridDistance(turret, other) === nearestDistance);
    const target = nearest.length === 1 ? nearest[0]
      : (await api.chooseToken(turret, {
        title: "DEPLOYABLE TURRET — NEAREST TARGET",
        count: 1, soft: true,
        filter: other => nearest.some(candidate => candidate.id === other.id),
        description: "GM: choose one of the tied nearest hostile targets."
      }))?.[0] ?? nearest[0];
    if (!target?.actor) continue;
    await api.executeBasicAttack(turret.actor, {
      targets: [target], fxSourceToken: turret,
      attack_type: "Ranged",
      flat_bonus: tier,
      damage: [{ val: String(3 + tier), type: "Kinetic" }]
    });
  }
  return true;
}

