  await api.addExtraActions(item, [
    { name: "Board Desant Hardpoints (GM)", activation: "Free Action",
      detail: "GM: record an adjacent ally's Quick Action to board." },
    { name: "Disembark Desant Hardpoints (GM)", activation: "Free Action",
      detail: "GM: disembark a rider as part of their movement." }
  ]);
}

reactions.onMessage:
async function onMessage(type, data, token, item, name, api) {
  if (!game.user.isGM) return false;
  const attacher = globalThis.tokenAttacher;
  const riders = () => canvas.tokens.placeables.filter(other =>
    other.document.getFlag("lancer-automations",
      "rebakedDesantCarrierId") === token.id);
  const disembark = async (rider, fall) => {
    if (!rider?.actor) return;
    if (attacher?.detachElementFromToken)
      await attacher.detachElementFromToken(rider, token, true);
    await rider.document.unsetFlag("lancer-automations",
      "rebakedDesantCarrierId");
    await rider.document.unsetFlag("lancer-automations",
      "rebakedDesantSquad");
    await api.removeEffectsByNameFromTokens({
      tokens: [rider], effectNames: ["cover_soft"],
      extraFlags: { rebakedDesantCarrierId: token.id }, notify: false
    });
    if (!fall) return;
    if (Number(rider.actor.system?.hp?.value ?? 1) <= 0) return;
    await api.moveTokenRuler(rider, {
      range: 1, cost: 0, free: true, action: "forced", urgent: true,
      title: "DESANT HARDPOINTS — LAND ADJACENT",
      description: "GM: place the fallen rider in a free space adjacent to the Support."
    });
    await api.applyEffectsToTokens({
      tokens: [rider], effectNames: ["prone"], note: "Desant Hardpoints"
    });
  };
  if (data.event !== "onActivation") {
    const affected = data.subjectId === token.id ? riders()
      : riders().filter(rider => rider.id === data.subjectId);
    for (const rider of affected) await disembark(rider, true);
    return true;
  }
  if (data.action === "Disembark Desant Hardpoints (GM)") {
    const current = riders();
    if (!current.length) return false;
    const choice = await api.startChoiceCard({
      title: "DESANT HARDPOINTS — DISEMBARK", item,
      originToken: token, owner: token, mode: "or",
      userIdControl: api.getActiveGMId(),
      description: "Choose a rider to detach before moving them away.",
      choices: current.map(rider => ({
        text: rider.name, icon: "fas fa-person-walking"
      }))
    });
    if (!Number.isInteger(choice?.choiceIdx)) return false;
    await disembark(current[choice.choiceIdx], false);
    return true;
  }
  if (!attacher?.attachElementToToken) {
    ui.notifications.warn("Desant Hardpoints needs the active Token Attacher module.");
    return false;
  }
  const selected = await api.chooseToken(token, {
    title: "DESANT HARDPOINTS — RIDER", count: 1, range: 1,
    includeSelf: false, soft: true,
    filter: other => other?.actor && api.isFriendly(token, other)
      && other.id !== token.id && !api.hasStatus(other, "immobilized")
      && !other.document.getFlag("lancer-automations",
        "rebakedDesantCarrierId"),
    description: "GM: choose an adjacent allied character that is not Immobilized. Record that character's Quick Action."
  });
  const rider = selected?.[0];
  if (!rider?.actor || !api.isFriendly(token, rider)
    || api.hasStatus(rider, "immobilized")
    || api.getMinGridDistance(token, rider) > 1) return false;
  const squad = await api.askCard({
    title: "DESANT HARDPOINTS — CAPACITY", item,
    originToken: token, relatedToken: rider, owner: token,
    description: "Is " + rider.name + " a Squad? A Support can carry one Squad, or other characters whose combined Size is less than its own.",
    yesText: "Squad", noText: "Other Character"
  });
  const current = riders();
  const ownSize = Number(Math.max(token.document.width, token.document.height));
  const occupied = current.reduce((sum, other) => sum
    + Number(Math.max(other.document.width, other.document.height)), 0);
  const riderSize = Number(Math.max(rider.document.width, rider.document.height));
  if (squad?.confirmed ? current.length > 0
    : current.some(other => other.document.getFlag(
        "lancer-automations", "rebakedDesantSquad"))
      || occupied + riderSize >= ownSize) {
    ui.notifications.warn("Desant Hardpoints has insufficient carrying capacity.");
    return false;
  }
  const grid = canvas.grid.size;
  await rider.document.update({
    x: token.center.x - rider.document.width * grid / 2,
    y: token.center.y - rider.document.height * grid / 2,
    elevation: token.document.elevation
  });
  await attacher.attachElementToToken(rider, token, true);
  await rider.document.setFlag("lancer-automations",
    "rebakedDesantCarrierId", token.id);
  if (squad?.confirmed) await rider.document.setFlag("lancer-automations",
    "rebakedDesantSquad", true);
  await api.applyEffectsToTokens({
    tokens: [rider], effectNames: ["cover_soft"],
    note: "Desant Hardpoints: soft cover while riding the Support.",
    duration: { label: "indefinite" }, notify: false
  }, { rebakedDesantCarrierId: token.id });
  return true;
}

reactions.evaluate:
function evaluate(triggerType, triggerData, reactorToken, item, activationName, api) {
    return triggerData.triggeringToken?.id === reactorToken.id
        && triggerData.targets?.some((entry) => entry?.target);
}

reactions.activationCode:
async function activation(triggerType, triggerData, reactorToken, item, activationName, api) {
    const targets = (triggerData.targets ?? [])
        .map((entry) => entry?.target)
        .filter(Boolean);

    if (!targets.length) return;

    await api.knockBackToken(targets, 2, {
        title: "DESTABILIZE — PUSH",
        description: "Move each affected target up to 2 spaces in any direction.",
        triggeringToken: reactorToken,
        actionName: item?.name ?? "Destabilize",
        item,
        icon: "modules/lancer-automations/icons/black/push.svg",
    });

    await api.executeSaveVsEffect(targets, {
        stat: "SYS",
        title: item?.name ?? "Destabilize",
        origin: reactorToken,
        effects: ["prone"],
        note: item?.name ?? "Destabilize",
        cardTitle: "DESTABILIZE — SYSTEMS SAVE",
        cardDescription: (target) => `<b>${target.name}</b> must pass a Systems save or be knocked <b>Prone</b>.`,
    });
}

const targets = await api.chooseToken(reactorToken, {
    count: 1,
    range: reactorToken.actor.system.sensor_range,
    includeSelf: true,
    filter: token =>
        api.isFriendly(reactorToken, token) &&
        !api.findEffectOnToken(token, "Dispersal Shield"),
    filterWarning: "Dispersal Shield must target the Priest or an allied character that is not already protected by Dispersal Shield.",
    soft: false,
    title: "DISPERSAL SHIELD",
    description: "Choose the Priest or an allied character within Sensors."
});

if (!targets?.length)
    return;

const target = targets[0];

const shieldValue = api.tierValue(
    reactorToken,
    [5, 6, 7]
);

const currentOvershield = Number(
    target.actor.system.overshield?.value ?? 0
);

const newOvershield = Math.max(
    currentOvershield,
    shieldValue
);

if (newOvershield !== currentOvershield) {
    await target.actor.update({
        "system.overshield.value": newOvershield
    });
}

const bonusId = "dispersal-shield-half-" + item.id + "-" + target.id;

await api.removeGlobalBonus(target.actor, bonus => bonus.context?.dispersalShield === true && bonus.context?.sourceItemId === item.id);
await api.removeConstantBonus(target.actor, bonus => bonus.context?.dispersalShield === true && bonus.context?.sourceItemId === item.id);

await api.addConstantBonus(target.actor, {
    id: bonusId,
    name: "Dispersal Shield",
    type: "target_modifier",
    subtype: "half_damage",
    rollTypes: ["damage"],
    applyToTargetter: true,
    context: {
        dispersalShield: true,
        sourceItemId: item.id,
        sourcePriestTokenId: reactorToken.id,
        protectedTokenId: target.id
    }
});

await api.applyEffectsToTokens(
    {
        tokens: [target],
        effectNames: [{ name: "Dispersal Shield", icon: item.img, isCustom: true }],
        note: "Dispersal Shield — next successful attack deals half damage",
        duration: { label: "indefinite" },
        notify: false
    },
    {
        dispersalShield: true,
        dispersalShieldSourceItemId: item.id,
        dispersalShieldBonusId: bonusId
    }
);

reactions.evaluate:
const target = triggerData.target;
if (!target?.actor) return false;
const effects = api.findEffectsOnToken(target, "Dispersal Shield", { extraFlags: { dispersalShieldSourceItemId: item.id } });
return effects.some(effect => {
    const bonusId = effect.flags?.["lancer-automations"]?.dispersalShieldBonusId;
    return !!bonusId
        && !!triggerData.flowState?.la_extraData?.bonusUsage?.candidates?.[bonusId]
        && api.getConstantBonuses(target.actor).some(bonus => bonus.id === bonusId);
});

reactions.activationCode:
const target = triggerData.target;
if (!target?.actor) return;
const effects = api.findEffectsOnToken(target, "Dispersal Shield", { extraFlags: { dispersalShieldSourceItemId: item.id } });
for (const effect of effects) {
    const bonusId = effect.flags?.["lancer-automations"]?.dispersalShieldBonusId;
    if (bonusId) await api.removeConstantBonus(target.actor, bonusId);
}
await api.removeEffectsByNameFromTokens({
    tokens: [target],
    effectNames: ["Dispersal Shield"],
    extraFlags: { dispersalShieldSourceItemId: item.id },
    notify: false
});

reactions.evaluate:
function evaluate(triggerType, data, token, item) {
    if (triggerType === "onTurnStart") return data.triggeringToken?.id === token.id;
    if (triggerType === "onExitCombat") return true;
    return data.triggeringToken?.id === token.id
      && data.weapon?.system?.lid === item?.system?.lid;
  }

reactions.activationCode:
async function activation(triggerType, data, token, item, name, api) {
    const source = "rebaked-artillery-dmr-" + item.id;
    const clear = () => api.removeGlobalBonus(token.actor, bonus => bonus.id === source);
    if (triggerType === "onTurnStart" || triggerType === "onExitCombat" || triggerType === "onDamage") {
      await clear();
      return;
    }
    if (triggerType === "onMiss") {
      if (!(data.flowState?.data?.hit_results ?? []).some(entry => entry?.hit)) await clear();
      return;
    }
    await clear();
    function resolve(entry) {
  const direct = entry?.target ?? entry?.token ?? entry?.object ?? entry;
  if (direct?.actor) return direct;
  if (direct?.object?.actor) return direct.object;
  const uuid = entry?.targetUuid ?? entry?.target_uuid ?? entry?.tokenUuid;
  if (uuid) {
    const document = fromUuidSync(uuid);
    const token = document?.object ?? document;
    if (token?.actor) return token;
  }
  return null;
}
    const targets = (data.flowState?.data?.acc_diff?.targets ?? data.targets ?? [])
      .map(resolve).filter(target => target && api.hasStatus(target, "lockon"));
    if (!targets.length) return;
    await api.addGlobalBonus(token.actor, {
      id: source, name: "DMR — Lock On AP", type: "target_modifier", subtype: "ap",
      itemId: item.id, applyTo: [...new Set(targets.map(target => target.id))],
      rollTypes: ["damage"], context: { rebakedArtilleryDmr: true, sourceItemId: item.id }
    }, { duration: "indefinite", origin: token });
  }

const speed = reactorToken.actor.system.speed;

const moved = await api.moveToken(reactorToken, {
    range: speed,
    cost: 0,
    title: "DOUBLE TIME"
});

if (!moved)
    return;

