reactions.onMessage:
async function onMessage(type, data, token, item, name, api) {
  if (!game.user.isGM) return false;
  const flags = { rebakedDragCablesSource: token.id };
  const linkedId = token.document.getFlag("lancer-automations", "rebakedDragCablesTargetId");
  const linked = linkedId ? canvas.tokens.get(linkedId) : null;
  const clear = async () => {
    await api.removeEffectsByNameFromTokens({
      tokens: canvas.tokens.placeables,
      effectNames: ["Drag Cables — Anchored"],
      extraFlags: flags, notify: false
    });
    await token.document.unsetFlag("lancer-automations", "rebakedDragCablesTargetId");
  };
  if (data.cableAction === "clear" || data.cableAction === "cleanup"
    || data.cableAction === "Clear Drag Cables (GM)") {
    await clear(); return true;
  }
  if (data.cableAction === "mirror") {
    if (!linked?.actor) { await clear(); return false; }
    const spaces = Math.max(0, Number(data.movedSpaces ?? 0));
    if (!spaces) return false;
    await api.moveTokenRuler(linked, {
      range: spaces, cost: 0, free: true, action: "forced", urgent: true,
      title: "DRAG CABLES — MIRROR MOVEMENT",
      description: "GM: move " + linked.name + " to mirror the Demolisher's last movement. Keep the cable within 5 spaces and adjudicate obstructions."
    });
    return true;
  }
  if (data.cableAction === "Reel In Drag Cables") {
    if (!linked?.actor) {
      await clear();
      ui.notifications.warn("Drag Cables: no embedded target."); return false;
    }
    const saves = await api.executeSaveVsEffect([linked], {
      stat: "HULL", title: "Drag Cables — Reel In", origin: token,
      cardDescription: "Failure: the GM pulls you adjacent to the Demolisher."
    });
    if (!saves?.[0]?.result?.completed || saves[0].passed) return true;
    const distance = api.getMinGridDistance(linked, token);
    if (distance > 1) await api.moveTokenRuler(linked, {
      range: distance - 1, cost: 0, free: true, action: "forced", urgent: true,
      title: "DRAG CABLES — PULL ADJACENT",
      description: "GM: pull the embedded character directly toward the Demolisher until adjacent. Adjudicate obstructions."
    });
    if (api.getMinGridDistance(linked, token) > 1)
      ui.notifications.warn("Drag Cables: target is not adjacent; GM, finish or adjudicate the pull.");
    return true;
  }
  const target = (await api.chooseToken(token, {
    title: "DRAG CABLES — EMBED TARGET", count: 1, range: 5,
    includeSelf: false, soft: false,
    description: "GM: choose a character within Range 5 for a Hull save. Using the system on a new target releases the old one."
  }))?.[0];
  if (!target?.actor || api.getMinGridDistance(token, target) > 5) return false;
  await clear();
  const saves = await api.executeSaveVsEffect([target], {
    stat: "HULL", title: "Drag Cables", origin: token,
    cardDescription: "Failure: embedded with Drag Cables. Neither linked character can move more than 5 spaces from the other."
  });
  if (!saves?.[0]?.result?.completed || saves[0].passed) return true;
  await token.document.setFlag("lancer-automations", "rebakedDragCablesTargetId", target.id);
  await api.applyEffectsToTokens({
    tokens: [token, target],
    effectNames: [{ name: "Drag Cables — Anchored", icon: item.img, isCustom: true }],
    note: "Linked by Drag Cables: maximum separation 5. An embedded target smaller than the Demolisher mirrors its movement. Cables can be cut by a melee hit vs Evasion 10.",
    duration: { label: "indefinite" }
  }, flags);
  return true;
}

