reactions.activationCode:
async function activation(triggerType, triggerData, reactorToken, item, activationName, api) {
    const heat = api.tierValue(reactorToken, [2, 3, 4]);

    const zoneTrigger = `
const api = game.modules.get("lancer-automations")?.api;
if (!api || !token) return;

const data = template.getFlag("lancer-automations", "electroChaffData");
if (!data) return;

const source = canvas.tokens.get(data.sourceTokenId);
const affectedToken = token.object ?? token;
const tokenDocument = token.document ?? token;

if (!source || !affectedToken?.actor || !tokenDocument) return;
if (!api.isHostile(source, affectedToken)) return;

const turnKey = api.currentTurnKey();
if (!turnKey) return;

const triggerKeys = api.getTokenFlags(tokenDocument, "electroChaffTurnKeys") || {};
if (triggerKeys[template.id] === turnKey) return;

triggerKeys[template.id] = turnKey;
await api.addTokenFlags(tokenDocument, {
    electroChaffTurnKeys: triggerKeys,
});

await api.executeDamageRoll(
    source,
    [affectedToken],
    String(data.heat),
    "Heat",
    "Electro-Chaff",
);

await api.executeSaveVsEffect([affectedToken], {
    stat: "SYS",
    title: "Electro-Chaff",
    origin: source,
    effects: ["slowed"],
    note: "Electro-Chaff",
    duration: api.untilEndOfTurn(affectedToken),
    cardTitle: "ELECTRO-CHAFF — SYSTEMS SAVE",
    cardDescription: (target) => "<b>" + target.name + "</b> must pass a Systems save or become <b>Slowed</b> until the end of their next turn.",
});
`;

    const zoneCleanup = `
const api = game.modules.get("lancer-automations")?.api;
if (!api) return;

for (const affectedToken of canvas.tokens.placeables) {
    const tokenDocument = affectedToken.document;
    const triggerKeys = api.getTokenFlags(tokenDocument, "electroChaffTurnKeys") || {};

    if (!(template.id in triggerKeys)) continue;

    delete triggerKeys[template.id];
    await api.addTokenFlags(tokenDocument, {
        electroChaffTurnKeys: triggerKeys,
    });
}
`;

    let templateDocument = null;

    while (!templateDocument) {
        const result = await api.placeZone(reactorToken, {
            range: 5,
            size: 1,
            type: "Blast",
            count: 1,
            fillColor: "#45d9e8",
            borderColor: "#157f91",
            title: "ELECTRO-CHAFF",
            description: "Place a free Blast 1 area within Range 5. The area cannot contain any tokens.",
            icon: "fas fa-bolt",
            centerLabel: "CHFF",
            hooks: {
                entered: {
                    command: zoneTrigger,
                    asGM: true,
                },
                turnStart: {
                    command: zoneTrigger,
                    asGM: true,
                },
                deleted: {
                    command: zoneCleanup,
                    asGM: true,
                },
            },
        });

        const placedTemplate = result?.[0]?.template;
        if (!placedTemplate) return;

        const occupyingTokens = api.tokensInTemplate(placedTemplate);

        if (occupyingTokens.length) {
            const names = occupyingTokens.map((token) => token.name).join(", ");
            await placedTemplate.delete();
            ui.notifications.warn(`Electro-Chaff must be placed in a free area. Occupied by: ${names}. Please place it again.`);
            continue;
        }

        templateDocument = placedTemplate;
    }

    await templateDocument.setFlag("lancer-automations", "electroChaffData", {
        sourceTokenId: reactorToken.id,
        sourceActorUuid: reactorToken.actor.uuid,
        heat,
        itemId: item.id,
    });
}

