reactions.evaluate:
function evaluate(type, data, token, item, name, api) {
  const subject = data.triggeringToken;
  if (type === "onActivation")
    return subject?.id === token.id && data.item?.id === item.id;
  const state = api.getActorFlags(token.actor, "empoweredInvestitureState");
  if (!state?.targetId) return false;
  if (type === "onTurnEnd") return subject?.id === state.targetId;
  if (type === "onTurnStart")
    return subject?.id === token.id
      && api.getActorFlags(token.actor, "investitureTargetId") !== state.targetId;
  if (type === "onExitCombat") return subject?.id === token.id;
  return ["onDestroyed", "onTokenRemoved"].includes(type)
    && (subject?.id === token.id || subject?.id === state.targetId);
}

