reactions.onMessage:
async function onMessage(type, data, token, item, name, api) {
  if (!game.user.isGM) return false;
  const key = "empoweredInvestitureState";
  const state = api.getActorFlags(token.actor, key);
  const linkItem = api.findItemByLid(token.actor,
    "npc-rebake_npcf_investiture_priest");
  const clear = async (stunPriest = true) => {
    const target = state?.targetId ? canvas.tokens.get(state.targetId) : null;
    const targets = [token, target].filter(Boolean);
    for (const subject of targets) await api.removeGlobalBonus(subject.actor,
      bonus => String(bonus.id ?? "").startsWith("rebaked-priest-empowered-" + item.id));
    await api.removeEffectsByNameFromTokens({
      tokens: [token], effectNames: ["immobilized"],
      extraFlags: { rebakedPriestEmpoweredSource: item.id }, notify: false
    });
    if (target && linkItem) {
      for (const prefix of ["investiture-attack-", "investiture-systems-",
        "investiture-tech-"])
        await api.removeConstantBonus(target.actor, prefix + linkItem.id);
      await api.removeEffectsByNameFromTokens({
        tokens: [token, target], effectNames: ["jammed", "stunned"],
        extraFlags: { investitureMirrorSourceItemId: linkItem.id },
        notify: false
      });
    }
    await api.removeActorFlags(token.actor, {
      empoweredInvestitureActive: true, empoweredInvestitureState: true,
      investitureTargetId: true
    });
    await token.document.unsetFlag("lancer-automations", "ownerActorUuid");
    await token.document.unsetFlag("lancer-automations", "ownerName");
    if (stunPriest && token.actor
      && Number(token.actor.system?.hp?.value ?? 1) > 0)
      await api.applyEffectsToTokens({
        tokens: [token], effectNames: ["stunned"],
        note: "Empowered Investiture ended",
        duration: api.untilEndOfTurn(token, 1)
      }, { rebakedPriestEmpoweredAftershock: item.id });
  };
  if (data.event !== "onActivation") {
    if (!state?.targetId) return false;
    await clear(data.event !== "onExitCombat");
    return true;
  }
  const targetId = api.getActorFlags(token.actor, "investitureTargetId");
  const target = targetId ? canvas.tokens.get(targetId) : null;
  if (!target?.actor || !linkItem) {
    ui.notifications.warn("Empowered Investiture needs an active Investiture link.");
    return false;
  }
  if (state?.targetId) {
    ui.notifications.warn("Empowered Investiture is already active.");
    return false;
  }
  await api.removeEffectsByNameFromTokens({
    tokens: [target], effectNames: ["impaired", "slow", "slowed"],
    notify: false
  });
  const common = { type: "resistance",
    damageTypes: ["all"], rollTypes: ["damage"] };
  for (const subject of [token, target])
    await api.addGlobalBonus(subject.actor, {
      ...common,
      id: "rebaked-priest-empowered-resistance-" + item.id,
      name: "Empowered Investiture — Damage and Heat Resistance"
    }, { origin: token, duration: "indefinite" });
  await api.addGlobalBonus(target.actor, {
    id: "rebaked-priest-empowered-immunity-" + item.id,
    name: "Empowered Investiture — Condition Immunity",
    type: "immunity", subtype: "effect",
    effects: ["impaired", "slow", "slowed"]
  }, { origin: token, duration: "indefinite" });
  await api.applyEffectsToTokens({
    tokens: [token], effectNames: ["immobilized"],
    note: "Empowered Investiture: linked without Range 5 limit until the end of the linked character's next turn.",
    duration: { label: "indefinite" }
  }, { rebakedPriestEmpoweredSource: item.id });
  await api.addActorFlags(token.actor, {
    empoweredInvestitureActive: true,
    empoweredInvestitureState: { targetId: target.id }
  });
  return true;
}

