async function activation(type, data, token, item, name, api) {
  if (type === "onTurnStart") {
    if (api.hasStatus(token, "dangerzone"))
      await api.setItemResource(item, true);
    return;
  }
  const danger = api.hasStatus(token, "dangerzone");
  const burstGuide = api.drawRangeHighlight(token, 2, 0xff7138, 0.14, true,
    { glowColor: 0xff7138, lineColor: 0xffb27a });
  try {
  const targets = canvas.tokens.placeables.filter(other =>
    other.id !== token.id && other.actor
      && api.isHostile(token, other)
      && api.getMinGridDistance(token, other) <= 2);
