    const saves = await api.executeSaveVsEffect([target], {
      stat: "HULL", title: "Explosive Jet", origin: token,
      difficulty: danger ? 1 : 0,
      cardDescription: "Failure: pushed outside Burst 2 and Prone. Danger Zone gives +1 Difficulty."
    });
