    });
    await api.applyEffectsToTokens({
      tokens: [target], effectNames: ["prone"], note: "Explosive Jet"
    });
  }
  } finally {
    burstGuide?.destroy();
  }
  await api.moveTokenRuler(token, {
    range: 5, cost: 0, free: true, action: "forced", urgent: true,
    title: "EXPLOSIVE JET — FLY 5",
    description: "GM: fly the Pyro up to 5 spaces in any direction. It must land when this move ends."
  });
