reactions.activationCode:
async function activation(type, data, token, item, name, api) {
    const key = "rebakedAssassinExplosiveKnives";
    if (type === "onActivation") {
      const gmId = api.getActiveGMId();
      if (!gmId || !game.users.get(gmId)?.active) {
        ui.notifications.warn("Explosive Knives requires an active GM to make its attack.");
        return;
      }
      await data.sendMessageToReactor({ startAttack: true }, gmId, { wait: true });
      return;
    }
    if (type === "onHit") {
      const pending = [...(api.getActorFlags(token.actor, key) ?? [])];
      for (const hit of data.targets ?? []) {
        const target = hit?.target;
        if (!target?.actor) continue;
        const mark = {
          id: foundry.utils.randomID(), targetId: target.id,
          combatId: game.combat?.id,
          skipCurrent: game.combat?.combatant?.tokenId === target.id
        };
        pending.push(mark);
        await api.applyEffectsToTokens({
          tokens: [target],
          effectNames: [{ name: "Embedded Knife", icon: item.img, isCustom: true }],
          note: "Explosive Knives: detonates at the end of the target's next turn.",
          duration: { label: "indefinite" }, notify: false
        }, { rebakedAssassinKnifeItemId: item.id, rebakedAssassinKnifeMarkId: mark.id });
      }
      await api.addActorFlags(token.actor, { [key]: pending });
      return;
    }
    const gmId = api.getActiveGMId();
    if (!gmId || !game.users.get(gmId)?.active) {
      ui.notifications.warn("Explosive Knives requires an active GM for delayed detonation.");
      return;
    }
    await data.sendMessageToReactor(type === "onExitCombat"
      ? { clearKnives: true }
      : { turnEndTargetId: data.triggeringToken?.id },
      gmId, { wait: true });
  }

reactions.onMessage:
async function onMessage(type, data, token, item, name, api) {
    if (!game.user.isGM) return false;
    if (data.startAttack) {
      const target = (await api.chooseToken(token, {
        title: "EXPLOSIVE KNIVES — TARGET", count: 1,
        range: 5, soft: false, includeSelf: false,
        description: "Choose a character within Range 5 for the ranged knife attack."
      }))?.[0];
      if (!target) return false;
      const attack = await api.executeBasicAttack(token.actor, {
        item, targets: [target], fxSourceToken: token,
        attack_type: "Ranged", flat_bonus: api.tierValue(token, [2, 4, 6])
      });
      return attack.completed;
    }
    const key = "rebakedAssassinExplosiveKnives";
    if (data.clearKnives) {
      await api.removeEffectsByNameFromTokens({
        tokens: canvas.tokens.placeables, effectNames: ["Embedded Knife"],
        extraFlags: { rebakedAssassinKnifeItemId: item.id }, notify: false
      });
      await api.removeActorFlags(token.actor, { [key]: true });
      return true;
    }
    const pending = [...(api.getActorFlags(token.actor, key) ?? [])];
    const remaining = [];
    const due = [];
    for (const mark of pending) {
      if (mark.targetId !== data.turnEndTargetId
        || mark.combatId !== game.combat?.id) {
        remaining.push(mark);
      } else if (mark.skipCurrent) {
        remaining.push({ ...mark, skipCurrent: false });
      } else due.push(mark);
    }
    await api.addActorFlags(token.actor, { [key]: remaining });
    for (const mark of due) {
      const target = canvas.tokens.get(mark.targetId);
      if (!target) continue;
      await api.removeEffectsByNameFromTokens({
        tokens: [target], effectNames: ["Embedded Knife"],
        extraFlags: { rebakedAssassinKnifeMarkId: mark.id }, notify: false
      });
      const burst = canvas.tokens.placeables.filter(other =>
        other.actor && api.getMinGridDistance(target, other) <= 1);
      if (burst.length) await api.executeDamageRoll(token, burst,
        String(api.tierValue(token, [4, 6, 8])), "Explosive",
        "Explosive Knives");
      const saves = await api.executeSaveVsEffect([target], {
        stat: "HULL", title: "Explosive Knives", origin: token,
        cardDescription: "Failure: Shredded until the end of your next turn."
      });
      if (saves?.[0]?.result?.completed && !saves[0].passed)
        await api.applyEffectsToTokens({
          tokens: [target], effectNames: ["shredded"],
          note: "Explosive Knives",
          duration: api.untilEndOfTurn(target, 1)
        }, { rebakedAssassinExplosiveKnives: item.id });
    }
    return true;
  }

