  if (heat > 0) await token.actor.update({ "system.heat.value": 0 });
  const burstGuide = api.drawRangeHighlight(token, 2, 0xff7138, 0.14, true,
    { glowColor: 0xff7138, lineColor: 0xffb27a });
  try {
  const burst = canvas.tokens.placeables.filter(other =>
    other.actor && api.getMinGridDistance(token, other) <= 2);
  for (const target of burst) {
    const saves = await api.executeSaveVsEffect([target], {
      stat: "AGILITY", title: "Explosive Vent", origin: token,
      cardDescription: "Failure: take Heat equal to half the amount cleared (rounded up) and become Prone."
    });
    if (!saves?.[0]?.result?.completed || saves[0].passed) continue;
    const amount = Math.ceil(heat / 2);
