      String(amount), "Heat", "Explosive Vent");
    await api.applyEffectsToTokens({
      tokens: [target], effectNames: ["prone"], note: "Explosive Vent"
    });
  }
  } finally {
    burstGuide?.destroy();
  }
}

reactions.evaluate:
function evaluate(type, data, token, item, name, api) {
  const attacker = data.triggeringToken;
  if (!attacker?.actor) return false;
  const hits = [
    ...(data.hitTokens ?? []),
    ...(data.targets ?? []).map(entry => entry?.target)
  ].filter(target => target?.actor);
  if (!hits.length) return false;
  if (attacker.id === token.id)
    return data.weapon?.system?.lid === "npc-rebake_npcf_marker_rifle_scout";
  return api.isFriendly(token, attacker) && hits.some(target =>
    api.findEffectsOnToken(target, "Scout's Mark", {
      extraFlags: { rebakedScoutSourceId: token.id }
    }).length > 0);
}

reactions.activationCode:
async function activation(type, data, token, item, name, api) {
  const hits = [...new Set([
    ...(data.hitTokens ?? []),
    ...(data.targets ?? []).map(entry => entry?.target)
  ].filter(target => target?.actor))];
  const markName = "Scout's Mark";
  if (data.triggeringToken?.id === token.id) {
    const target = hits[0];
    if (!target) return;
    await api.clearMarks(token, markName, {
      flagKey: "rebakedScoutSourceId"
    });
    await api.applyMark(token, [target], {
      effect: { name: markName, icon: item.img, isCustom: true },
      note: "The next allied hit may consume this mark for extra damage, Prone, or push and Impaired.",
      duration: { label: "indefinite" },
      flagKey: "rebakedScoutSourceId"
    });
    return;
  }
  const target = hits.find(candidate =>
    api.findEffectsOnToken(candidate, markName, {
      extraFlags: { rebakedScoutSourceId: token.id }
    }).length > 0);
  if (!target) return;
  const gmId = api.getActiveGMId();
  if (!gmId || !game.users.get(gmId)?.active) return;
  const choice = await data.sendMessageToReactor({
    targetId: target.id, attackerId: data.triggeringToken?.id
  }, gmId, { wait: true });
  if (!Number.isInteger(choice) || choice < 0 || choice > 2) return;
  await api.clearMarks(token, markName, {
    flagKey: "rebakedScoutSourceId"
  });
  if (choice === 0) await api.injectBonusToFlowState(data.flowState, {
    id: "rebaked-scout-expose-weakness-" + item.id,
    name: "Expose Weakness", type: "damage", damageMode: "add",
    damage: [{ val: "1d6", type: "Variable" }],
    applyTo: [target.id], rollTypes: ["damage"]
  });
}

