reactions.evaluate:
function evaluate(triggerType, triggerData, reactorToken, item, activationName, api) {
    const mover = triggerData.triggeringToken ?? triggerData.token;
    if (!mover || mover.id === reactorToken.id) return false;

    const active = api.getActivatedItems(reactorToken)
        ?.some(activeItem => activeItem.id === item.id);
    if (!active) return false;

    if (!api.isHostile(reactorToken, mover)) return false;

    const moveInfo = triggerData.moveInfo ?? {};
    if (moveInfo.isTeleport || moveInfo.isInvoluntary || moveInfo.isUndo) return false;

    const shotgun = api.findItemByLid(
        reactorToken.actor,
        "npc-rebake_npcf_combat_shotgun_sentinel",
    );
    if (!shotgun) return false;

    const threat = Number(
        api.getMaxWeaponRanges_WithBonus(shotgun)?.Threat ?? 0,
    );
    if (threat <= 0) return false;

    if (triggerType === "onMove") {
        const extra = moveInfo.extraData ?? {};
        return extra.eyeOfMidnightInterceptItemId === item.id
            && extra.eyeOfMidnightInterceptReactorId === reactorToken.id
            && extra.eyeOfMidnightInterceptMoverId === mover.id;
    }

    if (triggerType !== "onPreMove") return false;

    const pending = api.getActorFlags(
        reactorToken.actor,
        "eyeOfMidnightPendingIntercept",
    );

    if (
        moveInfo.isModified
        && pending?.itemId === item.id
        && pending?.moverId === mover.id
    ) {
        return false;
    }

    const startDistance = api.getMinGridDistance(
        mover,
        reactorToken,
        triggerData.startPos,
    );

    if (startDistance <= threat) return true;

    const path = moveInfo.pathHexes ?? [];
    const startIndex = Math.max(0, path.historyStartIndex ?? 0);

    for (let index = startIndex; index < path.length; index++) {
        const step = path[index];
        const distance = api.getMinGridDistance(
            mover,
            reactorToken,
            { x: step.x, y: step.y },
        );

        if (distance <= threat) return true;
    }

    return false;
}

reactions.activationCode:
async function activation(triggerType, triggerData, reactorToken, item, activationName, api) {
    const mover = triggerData.triggeringToken ?? triggerData.token;
    if (!mover) return;

    const shotgun = api.findItemByLid(
        reactorToken.actor,
        "npc-rebake_npcf_combat_shotgun_sentinel",
    );

    if (!shotgun) {
        ui.notifications.warn(
            `Eye of Midnight: Combat Shotgun not found on ${reactorToken.name}.`,
        );
        return;
    }

    const threat = Number(
        api.getMaxWeaponRanges_WithBonus(shotgun)?.Threat ?? 0,
    );
    if (threat <= 0) return;

    const fireShotgun = async () => {
        const gmId = api.getActiveGMId();
        if (!gmId || !game.users.get(gmId)?.active) {
            ui.notifications.warn("Eye of Midnight: No active GM is available to fire the Combat Shotgun.");
            return;
        }

        await triggerData.sendMessageToReactor(
            { moverTokenId: mover.id },
            gmId,
            { wait: true }
        );
    };

    const askToFire = async description => {
        const result = await api.askCard({
            owner: reactorToken,
            originToken: reactorToken,
            relatedToken: mover,
            item,
            title: "EYE OF MIDNIGHT — OVERWATCH",
            description,
            icon: api.getActivationIcon("reaction"),
            yesText: "Fire",
            yesIcon: "fas fa-crosshairs",
            noText: "Let Them Move",
            noIcon: "fas fa-person-running",
        });

        return result.confirmed;
    };

    if (triggerType === "onMove") {
        await api.removeActorFlags(reactorToken.actor, {
            eyeOfMidnightPendingIntercept: true,
        });

        await fireShotgun();
        return;
    }

    const startDistance = api.getMinGridDistance(
        mover,
        reactorToken,
        triggerData.startPos,
    );

    if (startDistance <= threat) {
        const preConfirm = async () => {
            const fire = await askToFire(
                `<strong>${mover.name}</strong> is moving from within <strong>${reactorToken.name}</strong>'s Threat. Fire the Combat Shotgun?`,
            );

            if (!fire) return false;

            await fireShotgun();
            return false;
        };

        await triggerData.cancelTriggeredMove(
            `<strong>${reactorToken.name}</strong> may use Eye of Midnight against <strong>${mover.name}</strong>.`,
            false,
            api.getTokenOwnerUserId(mover),
            preConfirm,
            undefined,
            {
                item,
                originToken: reactorToken,
                relatedToken: mover,
            },
        );

        return;
    }

    const path = triggerData.moveInfo?.pathHexes ?? [];
    const startIndex = Math.max(0, path.historyStartIndex ?? 0);
    let interceptIndex = -1;

    for (let index = startIndex; index < path.length; index++) {
        const step = path[index];
        const distance = api.getMinGridDistance(
            mover,
            reactorToken,
            { x: step.x, y: step.y },
        );

        if (distance <= threat) {
            interceptIndex = index;
            break;
        }
    }

    if (interceptIndex < 0) return;

    const interceptPoint = path.getPathPositionAt?.(interceptIndex)
        ?? {
            x: path[interceptIndex].x,
            y: path[interceptIndex].y,
        };

    const preConfirm = async () => {
        const fire = await askToFire(
            `<strong>${mover.name}</strong> is about to enter <strong>${reactorToken.name}</strong>'s Threat. Fire the Combat Shotgun as they cross the line?`,
        );

        if (!fire) return false;

        await api.addActorFlags(reactorToken.actor, {
            eyeOfMidnightPendingIntercept: {
                itemId: item.id,
                moverId: mover.id,
            },
        });

        return true;
    };

    await triggerData.changeTriggeredMove(
        interceptPoint,
        {
            eyeOfMidnightInterceptItemId: item.id,
            eyeOfMidnightInterceptReactorId: reactorToken.id,
            eyeOfMidnightInterceptMoverId: mover.id,
        },
        `<strong>${mover.name}</strong> reaches <strong>${reactorToken.name}</strong>'s Threat.`,
        false,
        api.getTokenOwnerUserId(mover),
        preConfirm,
        undefined,
        {
            item,
            originToken: reactorToken,
            relatedToken: mover,
        },
    );
}

