reactions.evaluate:
function evaluate(triggerType, triggerData, reactorToken, item, activationName, api) {
    const source = triggerData.triggeringToken ?? triggerData.token;
    const targetId = api.getActorFlags(
        reactorToken.actor,
        "followerCountTargetId",
    );

    if (triggerType === "onInitTechAttack") {
        if (source?.id !== reactorToken.id) return false;
        if (triggerData.techItem?.system?.lid !== item?.system?.lid) return false;

        const attemptedTarget = triggerData.targets?.[0];
        return !!attemptedTarget
            && !!targetId
            && attemptedTarget.id !== targetId;
    }

    if (triggerType === "onTechHit") {
        return source?.id === reactorToken.id
            && triggerData.techItem?.system?.lid === item?.system?.lid
            && !!triggerData.targets?.[0]?.target;
    }

    if (triggerType === "onDestroyed") {
        return source?.id === reactorToken.id
            || (!!targetId && source?.id === targetId);
    }

    return false;
}

reactions.activationCode:
async function activation(triggerType, triggerData, reactorToken, item, activationName, api) {
    const BOOST_ACTION = "Follower Count Boost";
    const BONUS_ID = `follower-count-${item.id}`;

    const getTarget = explicitTargetId => {
        const storedTargetId = api.getActorFlags(
            reactorToken.actor,
            "followerCountTargetId",
        );

        const targetIds = [explicitTargetId, storedTargetId]
            .filter(Boolean);

        for (const targetId of targetIds) {
            const directTarget = canvas.tokens.get(targetId);
            if (directTarget?.actor) return directTarget;

            const matchingTarget = canvas.tokens.placeables.find(token =>
                token.id === targetId
                || token.document?.id === targetId
                || token.document?.uuid === targetId,
            );

            if (matchingTarget?.actor) return matchingTarget;
        }

        const targetActorUuid = reactorToken.document.getFlag(
            "lancer-automations",
            "ownerActorUuid",
        );

        if (targetActorUuid) {
            const actorTarget = canvas.tokens.placeables.find(token =>
                token.actor?.uuid === targetActorUuid,
            );

            if (actorTarget?.actor) return actorTarget;
        }

        return null;
    };

    const isDestroyed = token => {
        if (!token?.actor) return true;

        const structure = Number(token.actor.system.structure?.value);
        const structureMax = Number(token.actor.system.structure?.max);

        if (
            Number.isFinite(structure)
            && Number.isFinite(structureMax)
            && structureMax > 0
            && structure <= 0
        ) {
            return true;
        }

        return api.hasStatus(token, "destroyed");
    };

    const cleanup = async () => {
        await api.removeGlobalBonus(reactorToken.actor, BONUS_ID);

        await api.removeGlobalBonus(
            reactorToken.actor,
            bonus => bonus.context?.followerCount === true
                && bonus.id !== BONUS_ID,
        );

        await api.removeExtraActions(item, BOOST_ACTION);
        await api.removeExtraActions(reactorToken.actor, BOOST_ACTION);

        const legacyFeature = api.findItemByLid(
            reactorToken.actor,
            "rtm_npcf_follower_count_boost",
        );
        if (legacyFeature) await legacyFeature.delete();

        await api.removeActorFlags(reactorToken.actor, {
            followerCountTargetId: true,
            followerCountBoostActive: true,
            followerCountBoostUsedTurnKey: true,
            followerCountBonusId: true,
            followerCountBoostBaseCap: true,
            followerCountBoostStartCost: true,
            followerCountBoostRejected: true,
        });

        await reactorToken.document.unsetFlag(
            "lancer-automations",
            "ownerActorUuid",
        );
        await reactorToken.document.unsetFlag(
            "lancer-automations",
            "ownerName",
        );
    };

    if (triggerType === "onInitTechAttack") {
        const oldTarget = getTarget();

        if (!oldTarget || isDestroyed(oldTarget)) {
            await cleanup();
            return;
        }

        const preConfirm = async () => {
            const result = await api.executeDamageRoll(
                reactorToken,
                [reactorToken],
                4,
                "Heat",
                "Follower Count — Retarget Cost",
            );

            if (!result?.completed) return true;
            return isDestroyed(reactorToken);
        };

        triggerData.cancelTechAttack(
            `<strong>${reactorToken.name}</strong> takes <strong>4 Heat</strong> to attempt to change Follower Count targets.`,
            "FOLLOWER COUNT — RETARGET",
            false,
            api.getTokenOwnerUserId(reactorToken),
            preConfirm,
            undefined,
            {
                item,
                originToken: reactorToken,
                relatedToken: triggerData.targets?.[0] ?? null,
            },
        );

        await triggerData.cancelTechAttack.wait();
        return;
    }

    if (triggerType === "onTechHit") {
        const target = triggerData.targets?.[0]?.target;
        if (!target) return;

        await api.removeGlobalBonus(
            reactorToken.actor,
            bonus => bonus.context?.followerCount === true,
        );

        await api.addGlobalBonus(reactorToken.actor, {
            id: BONUS_ID,
            name: "Follower Count",
            type: "accuracy",
            val: 1,
            rollTypes: ["attack"],
            applyTo: [target.id],
            context: {
                followerCount: true,
                sourceItemId: item.id,
                targetTokenId: target.id,
            },
        });

        await api.addActorFlags(reactorToken.actor, {
            followerCountTargetId: target.id,
            followerCountBonusId: BONUS_ID,
        });

        await reactorToken.document.setFlag(
            "lancer-automations",
            "ownerActorUuid",
            target.actor.uuid,
        );
        await reactorToken.document.setFlag(
            "lancer-automations",
            "ownerName",
            target.actor.name,
        );

        await api.removeExtraActions(item, BOOST_ACTION);
        await api.removeExtraActions(reactorToken.actor, BOOST_ACTION);

        const legacyFeature = api.findItemByLid(
            reactorToken.actor,
            "rtm_npcf_follower_count_boost",
        );
        if (legacyFeature) await legacyFeature.delete();

        await api.addExtraActions(reactorToken.actor, {
            name: BOOST_ACTION,
            activation: "Free",
            detail: `Once per turn, Boost up to Speed. Move as close as possible to ${target.name}.`,
            icon: "fas fa-forward",
        });

        return;
    }

    if (triggerType === "onDestroyed") {
        await cleanup();
    }
}

