async function activation(type, data, token, item, name, api) {
  const linkedId = api.getActorFlags(token.actor, "investitureTargetId");
  const gmId = api.getActiveGMId();
  if (!linkedId || !gmId || !game.users.get(gmId)?.active) {
    ui.notifications.warn("Fractal Assault requires an active GM and Investiture link.");
    return;
  }
  const choice = await data.sendMessageToReactor({
    attackerId: data.triggeringToken?.id, linkedId
  }, gmId, { wait: true });
  if (!choice?.branch) return;
  if (choice.branch === "zero") {
    const linked = canvas.tokens.get(linkedId);
    if (!linked?.actor) return;
    const id = "rebaked-priest-fractal-zero-" + item.id + "-" + foundry.utils.randomID();
    await api.addGlobalBonus(linked.actor, {
      id, name: "Fractal Assault — No Damage",
      type: "immunity", subtype: "damage", damageTypes: ["all"]
    }, { origin: token, duration: "indefinite" });
    api.afterFlow(data, async () => {
      await api.removeGlobalBonus(linked.actor, bonus => bonus.id === id);
    });
    return;
  }
  const attackerId = choice.attackerId;
  api.afterFlow(data, async () => {
    const attacker = canvas.tokens.get(attackerId);
    if (!attacker?.actor) return;
    await api.applyEffectsToTokens({
      tokens: [attacker], effectNames: ["stunned"],
      note: "Fractal Assault",
      duration: api.untilEndOfTurn(attacker, 1)
    }, { rebakedPriestFractalSource: item.id });
  });
}

