async function onMessage(type, data, token, item, name, api) {
  if (!game.user.isGM) return null;
  const attacker = canvas.tokens.get(data.attackerId);
  const linked = canvas.tokens.get(data.linkedId);
  if (!attacker?.actor || !linked?.actor
    || api.getActorFlags(token.actor, "investitureTargetId") !== linked.id
    || !api.hasReactionAvailable(token)
    || item.system?.charged === false
    || !api.checkGate(token, "rebaked_priest_fractal_assault_" + item.id))
    return null;
  const spend = await api.askCard({
    title: "FRACTAL ASSAULT", item, originToken: token,
    relatedToken: linked, owner: token,
    description: linked.name + " would take damage. Spend the Priest's Reaction to force "
      + attacker.name + " to choose between dealing 0 damage to the linked character (and recharging Fractal Assault) or becoming Stunned?",
    yesText: "Use Fractal Assault", noText: "Decline"
  });
  if (!spend?.confirmed) return null;
  const answer = await api.startChoiceCard({
    mode: "or", title: "FRACTAL ASSAULT — ATTACKER'S CHOICE",
    item, originToken: token, relatedToken: attacker,
    userIdControl: api.getTokenOwnerUserId(attacker),
    description: "Choose: your current effect deals 0 damage to "
      + linked.name + " and Fractal Assault recharges, or you become Stunned until the end of your next turn after this effect resolves.",
    choices: [
      { text: "Deal 0 Damage", icon: "fas fa-shield-alt" },
      { text: "Become Stunned", icon: "fas fa-bolt" }
    ]
  });
  if (!answer || ![0, 1].includes(answer.choiceIdx)) return null;
  if (!await api.consumeOncePerRound(token,
    "rebaked_priest_fractal_assault_" + item.id)) return null;
  await api.setReaction(token, false);
  await api.setItemResource(item, answer.choiceIdx === 0);
  return { branch: answer.choiceIdx === 0 ? "zero" : "stun",
    attackerId: attacker.id };
}

