reactions.activationCode:
async function activation(type, data, token, item, name, api) {
    const ownerBonusId = "rebaked-bastion-interdiction-owner-" + item.id;
    const allyBonusId = "rebaked-bastion-interdiction-ally-" + item.id;
    const old = api.getActorFlags(token.actor, "rebakedBastionInterdiction") ?? {};
    const clear = async () => {
      await api.removeGlobalBonus(token.actor, b => b.id === ownerBonusId);
      const oldAlly = canvas.tokens.get(old.allyId);
      const oldAllyActor = oldAlly?.actor
        ?? (old.allyActorUuid ? await fromUuid(old.allyActorUuid) : null);
      if (oldAllyActor) await api.removeGlobalBonus(oldAllyActor, b => b.id === allyBonusId);
      await api.removeActorFlags(token.actor, { rebakedBastionInterdiction: true });
    };
    if (type !== "onActivation") {
      const ally = canvas.tokens.get(old.allyId);
      const enemy = canvas.tokens.get(old.enemyId);
      if (type === "onDestroyed" || type === "onTokenRemoved") {
        if ([token.id, old.enemyId].includes(data.triggeringToken?.id)) await clear();
        else if (data.triggeringToken?.id === old.allyId) {
          const allyActor = ally?.actor
            ?? (old.allyActorUuid ? await fromUuid(old.allyActorUuid) : null);
          if (allyActor) await api.removeGlobalBonus(allyActor, b => b.id === allyBonusId);
          await api.addActorFlags(token.actor, {
            rebakedBastionInterdiction: { ...old, allyId: null }
          });
        }
        return;
      }
      if (ally && api.getMinGridDistance(token, ally) > 1) {
        await api.removeGlobalBonus(ally.actor, b => b.id === allyBonusId);
        await api.addActorFlags(token.actor, {
          rebakedBastionInterdiction: { ...old, allyId: null }
        });
      }
      if (!enemy) await clear();
      return;
    }
    const ally = (await api.chooseToken(token, {
      title: "FRIENDLY INTERDICTION — ALLY", count: 1, range: 1,
      includeSelf: false, disposition: "friendly", soft: false,
      filter: candidate => api.isFriendly(token, candidate),
      description: "Choose one adjacent allied character."
    }))?.[0];
    if (!ally) return;
    const enemy = (await api.chooseToken(token, {
      title: "FRIENDLY INTERDICTION — SOURCE", count: 1,
      includeSelf: false, disposition: "hostile", soft: true,
      filter: candidate => api.isHostile(token, candidate)
        && api.hasLineOfSight(token, candidate),
      filterWarning: "The selected character must be in line of sight.",
      description: "Choose one character in line of sight whose damage both allies resist."
    }))?.[0];
    if (!enemy) return;
    await clear();
    const condition = (state, actor, data, context) => {
      if (actor?.id !== context.enemyActorId) return false;
      if (!context.requireAdjacency) return true;
      const api = game.modules.get("lancer-automations")?.api;
      const source = canvas.tokens.get(context.sourceTokenId);
      const defended = canvas.tokens.get(context.defenderTokenId);
      return !!api && !!source && !!defended
        && api.getMinGridDistance(source, defended) <= 1;
    };
    const common = {
      type: "resistance", damageTypes: ["all"],
      rollTypes: ["damage"], condition
    };
    await api.addGlobalBonus(token.actor, {
      ...common, id: ownerBonusId, name: "Friendly Interdiction — Bastion",
      context: { enemyActorId: enemy.actor.id, sourceTokenId: token.id,
        defenderTokenId: token.id, requireAdjacency: false }
    }, { origin: token, duration: "indefinite" });
    await api.addGlobalBonus(ally.actor, {
      ...common, id: allyBonusId, name: "Friendly Interdiction — Ally",
      context: { enemyActorId: enemy.actor.id, sourceTokenId: token.id,
        defenderTokenId: ally.id, requireAdjacency: true }
    }, { origin: ally, duration: "indefinite" });
    await api.addActorFlags(token.actor, {
      rebakedBastionInterdiction: { allyId: ally.id, enemyId: enemy.id,
        enemyActorId: enemy.actor.id, allyActorUuid: ally.actor.uuid }
    });
  }

