reactions.activationCode:
async function activation(type, data, token, item, name, api) {
    const key = "rebakedGhostwalkReady";
    if (type === "onActivation") {
      await api.applyEffectsToTokens({
        tokens: [token], effectNames: ["intangible"], note: "Ghostwalk",
        duration: api.untilStartOfTurn(token, 1)
      }, { rebakedGhostwalkSource: item.id });
      await api.addActorFlags(token.actor, { [key]: "pending" });
      await api.moveTokenRuler(token, {
        range: Number(api.tokenSpeed(token)) || 0,
        cost: 0, free: true, action: "displace", urgent: true,
        title: "GHOSTWALK — MOVE SPEED",
        description: "GM: move up to Speed while Intangible, ignoring engagement and reactions."
      });
      return;
    }
    if (type === "onTurnStart") {
      if (api.getActorFlags(token.actor, key) === "pending")
        await api.addActorFlags(token.actor, { [key]: "ready" });
      return;
    }
    if (type === "onInitAttack") {
      if (api.getActorFlags(token.actor, key) !== "ready") return;
      api.setFlowFlag(data, "rebakedGhostwalkAttack", true);
      await api.addActorFlags(token.actor, { [key]: null });
      await api.injectBonusToFlowState(data.flowState, {
        id: "rebaked-ghostwalk-accuracy-" + item.id,
        name: "Ghostwalk", type: "accuracy", val: 1,
        rollTypes: ["attack"]
      });
      return;
    }
    const hitResults = [
      ...(data.flowState?.data?.hit_results ?? []),
      ...(data.targets ?? [])
    ];
    const critTargets = [...new Set(hitResults
      .filter(entry => entry?.hit !== false && entry?.crit === true
        && entry.target?.actor)
      .map(entry => entry.target.id))];
    if (!critTargets.length) return;
    await api.injectBonusToFlowState(data.flowState, {
      id: "rebaked-ghostwalk-critical-" + item.id,
      name: "Ghostwalk", type: "damage", damageMode: "add",
      damage: [{ val: "1d6", type: "Kinetic" }],
      applyTo: critTargets, rollTypes: ["damage"]
    });
  }

