reactions.activationCode:
async function activation(type, data, token, item, name, api) {
    const scope = "lancer-automations";
    const key = "rebakedBombardHighAngle";
    const owned = () => canvas.scene.templates.filter(zone =>
      zone.getFlag(scope, key)?.ownerTokenId === token.id);
    if (type === "onDestroyed" || type === "onExitCombat") {
      const gmId = api.getActiveGMId();
      if (gmId && game.users.get(gmId)?.active)
        await data.sendMessageToReactor({ cleanup: true }, gmId, { wait: true });
      return;
    }
    if (type === "onActivation") {
      const placed = await api.placeZone(token, {
        type: "Blast", size: 3, range: 25, count: 1,
        title: "HIGH-ANGLE FIRE — MARK BLAST 3",
        centerLabel: "INCOMING", fillColor: "#d25030", borderColor: "#ffcf55",
        description: "GM: mark a Blast 3 area within Bombard Cannon Range. It detonates at the end of the next round."
      });
      const zone = placed?.[0]?.template;
      if (!zone) return;
      if (!await api.consumeOncePerRound(token,
        "rebaked_bombard_high_angle_" + item.id)) {
        await zone.delete();
        return;
      }
      await zone.update({ ["flags." + scope + "." + key]: {
        ownerTokenId: token.id, itemId: item.id,
        combatId: game.combat?.id,
        detonateRound: Number(game.combat?.round ?? 0) + 1
      } });
      return;
    }
    const dueIds = owned().filter(zone => {
      const mark = zone.getFlag(scope, key);
      return mark?.combatId === game.combat?.id
        && Number(mark.detonateRound) <= Number(data.round ?? game.combat?.round ?? 0);
    }).map(zone => zone.id);
    if (!dueIds.length) return;
    const gmId = api.getActiveGMId();
    if (!gmId || !game.users.get(gmId)?.active) {
      ui.notifications.warn("High-Angle Fire requires an active GM to resolve its marked area.");
      return;
    }
    const freshIds = [];
    for (const zoneId of dueIds)
      if (await api.consumeOncePerRound(token,
        "rebaked_bombard_high_angle_resolve_" + zoneId)) freshIds.push(zoneId);
    if (freshIds.length)
      await data.sendMessageToReactor({ templateIds: freshIds }, gmId, { wait: true });
  }

reactions.onMessage:
async function onMessage(type, data, token, item, name, api) {
    if (!game.user.isGM) return false;
    const scope = "lancer-automations";
    const key = "rebakedBombardHighAngle";
    if (data.cleanup) {
      for (const zone of canvas.scene.templates.filter(zone =>
        zone.getFlag(scope, key)?.ownerTokenId === token.id)) await zone.delete();
      return true;
    }
    const cannon = api.findItemByLid(token.actor,
      "npc-rebake_npcf_bombard_cannon_bombard");
    for (const zoneId of data.templateIds ?? []) {
      const zone = canvas.scene.templates.get(zoneId);
      const mark = zone?.getFlag(scope, key);
      if (!zone || mark?.ownerTokenId !== token.id
        || mark.combatId !== game.combat?.id) continue;
      const targets = api.tokensInTemplate(zone).filter(target => target?.actor);
      try {
        if (!cannon) {
          ui.notifications.error("High-Angle Fire: Bombard Cannon is missing.");
          continue;
        }
        if (!targets.length) {
          ui.notifications.info("High-Angle Fire: the marked area contains no characters.");
          continue;
        }
        const bonusId = "rebaked-bombard-high-angle-blast-" + zone.id;
        await api.addGlobalBonus(token.actor, {
          id: bonusId, name: "High-Angle Fire — Blast 3",
          type: "range", rangeType: "Blast", rangeMode: "add", val: 1,
          itemId: cannon.id, rollTypes: ["attack"]
        }, { origin: token });
        try { await api.attackWith(cannon, targets); }
        finally { await api.removeGlobalBonus(token.actor, bonus => bonus.id === bonusId); }
      }
      finally { await zone.delete(); }
    }
    return true;
  }

