reactions.activationCode:
async function activation(triggerType, triggerData, reactorToken, item, activationName, api) {
    const effectFlags = {
        hostileSyncSourceId: reactorToken.id,
        hostileSyncItemId: item.id,
    };

    const findSyncedTargets = () => canvas.tokens.placeables.filter(
        token => api.findEffectsOnToken(token, "impaired", {
            extraFlags: effectFlags,
        }).length > 0,
    );

    const clearHostileSync = async () => {
        const syncedTargets = findSyncedTargets();

        if (syncedTargets.length) {
            await api.removeEffectsByNameFromTokens({
                tokens: syncedTargets,
                effectNames: ["impaired"],
                extraFlags: effectFlags,
                notify: false,
            });
        }

        await api.removeEffectsByNameFromTokens({
            tokens: [reactorToken],
            effectNames: ["immobilized"],
            extraFlags: effectFlags,
            notify: false,
        });
    };

    const isActive = () => api.getActivatedItems(reactorToken)
        .some(activeItem => activeItem.id === item.id);

    if (triggerType === "onEndActivation") {
        await clearHostileSync();
        return;
    }

    if (triggerType === "onDestroyed") {
        await clearHostileSync();

        if (isActive())
            await api.endItemActivation(item, reactorToken);

        return;
    }

    const selected = await api.chooseToken(reactorToken, {
        title: "HOSTILE SYNC",
        description: "Choose a hostile character within Sensors to become Impaired.",
        icon: "fas fa-link",
        range: "sensors",
        count: 1,
        disposition: "hostile",
        includeSelf: false,
        soft: false,
    });

    const target = selected?.[0];
    if (!target) return;

    await clearHostileSync();

    await api.applyEffectsToTokens(
        {
            tokens: [reactorToken],
            effectNames: ["immobilized"],
            note: `Hostile Sync: linked to ${target.name}.`,
            duration: { label: "indefinite" },
        },
        effectFlags,
    );

    await api.applyEffectsToTokens(
        {
            tokens: [target],
            effectNames: ["impaired"],
            note: `Hostile Sync: linked by ${reactorToken.name}.`,
            duration: { label: "indefinite" },
        },
        effectFlags,
    );

    await api.setItemAsActivated(
        item,
        reactorToken,
        "Protocol",
        "End Hostile Sync",
    );
}

