reactions.onInit:
async function onInit(token, item, api) {
  if (!item) return;
  const sources = [];
  for (const tier of [1, 2, 3]) {
    const sourceName = "Re:Baked Hound Missile T" + tier + " (NPC)";
    let source = null;
    for (const pack of game.packs.filter(pack => pack.documentName === "Actor")) {
      const entry = (await pack.getIndex()).find(entry => entry.name === sourceName);
      if (!entry) continue;
      const candidate = await pack.getDocument(entry._id);
      if (candidate?.type === "deployable" && candidate.system?.lid) {
        source = candidate;
        break;
      }
    }
    if (!source) {
      ui.notifications.warn("Hound Missile: import Rebaked_NPC_Deployables_Public_v1.lcp, then reload Foundry to register its Deployables entry.");
      return;
    }
    sources.push({ lid: source.system.lid, tier });
  }
  const previous = item.getFlag("lancer-automations", "extraDeployables") ?? [];
  if (item.system?.deployables?.length)
    await item.update({ "system.deployables": [] });
  if (previous.length !== 3 || previous.some((lid, index) =>
    lid !== sources[index].lid)) {
    await api.addItemFlags(item, {
      extraDeployables: [], extraDeployableLidsViaUI: [],
      extraDeployableOpts: {}
    });
    await api.addExtraDeploymentLids(item, sources);
  }
  if (item.getFlag("lancer-automations", "deployRange") !== 1
    || item.getFlag("lancer-automations", "deployCount") !== 1)
    await api.addItemFlags(item, { deployRange: 1, deployCount: 1 });
  await api.setHidePrimaryAction(item);
}

reactions.onMessage:
async function onMessage(type, data, token, item, name, api) {
  if (!game.user.isGM) return false;
  const drones = () => canvas.tokens.placeables.filter(drone =>
    api.getLAFlag(drone.document, "rebakedHoundOwner") === token.actor?.uuid
    && api.getLAFlag(drone.document, "rebakedHoundItem") === item.id);
  if (data.event === "onDeploy") {
    for (const id of data.deployedIds ?? []) {
    const drone = canvas.tokens.get(id);
    if (!drone?.actor
      || api.getLAFlag(drone.document, "ownerActorUuid") !== token.actor?.uuid)
      continue;
    const selected = await api.chooseToken(token, {
      title: "HOUND MISSILE — TARGET", count: 1, range: 15,
      includeSelf: false, soft: false,
      description: "GM: choose a target in Range 15 and line of sight."
    });
    const target = selected?.[0];
    if (!target?.actor || !api.hasLineOfSight(token, target)) {
      await drone.document.delete();
      ui.notifications.warn("Hound Missile: choose a visible target within Range 15; deployment cancelled.");
      continue;
    }
    const droneDoc = drone.document;
    await api.setLAFlag(droneDoc, "rebakedHoundOwner", token.actor.uuid);
    await api.setLAFlag(droneDoc, "rebakedHoundItem", item.id);
    await api.setLAFlag(droneDoc, "rebakedHoundTarget", target.id);
    const sourceActor = game.actors.get(droneDoc.actorId);
    if (sourceActor?.name !== "Hound Missile")
      await sourceActor?.update({ name: "Hound Missile" });
    if (droneDoc.name !== "Hound Missile")
      await droneDoc.update({ name: "Hound Missile" });
    }
    return true;
  }
  for (const drone of drones()) {
    const target = canvas.tokens.get(api.getLAFlag(drone.document, "rebakedHoundTarget"));
    if (!target?.actor) {
      ui.notifications.warn("Hound Missile has no valid target; GM must retarget or remove it.");
      continue;
    }
    const range = api.hasStatus(target, "lockon") ? 6 : 3;
    await api.moveTokenRuler(drone, {
      range, cost: 0, free: true, action: "fly", urgent: true,
      title: "HOUND MISSILE — FLY " + range,
      description: "GM: move directly toward " + target.name
        + ", maneuvering around cover and terrain as needed. Detonate if it reaches adjacency or collides with any character."
    });
    if (!canvas.tokens.get(drone.id)) continue;
    const adjacent = api.getMinGridDistance(drone, target) <= 1;
    const answer = adjacent ? { confirmed: true } : await api.askCard({
      title: "HOUND MISSILE — COLLISION", item,
      originToken: drone, owner: token,
      description: "Did this missile collide with a character during its movement?",
      yesText: "Detonate", noText: "Remain in Flight"
    });
    if (!answer?.confirmed) continue;
    const placed = await api.placeZone(drone, {
      type: "Burst", size: 1, range: 0, count: 1,
      title: "HOUND MISSILE — BURST 1",
      description: "GM: center Burst 1 on the missile's collision space."
    });
    const zone = placed?.[0]?.template;
    if (!zone) continue;
    try {
      for (const victim of api.tokensInTemplate(zone).filter(t => t?.actor)) {
        const saves = await api.executeSaveVsEffect([victim], {
          stat: "AGILITY", title: "Hound Missile", origin: token,
          cardDescription: "Failure: full Explosive damage. Success: half damage."
        });
        if (!saves?.[0]?.result?.completed) continue;
        await api.executeDamageRoll(token, [victim],
          String(api.tierValue(token, [16, 20, 24])),
          "Explosive", "Hound Missile", { half_damage: saves[0].passed });
      }
      await drone.document.delete();
    } finally {
      await zone.delete();
    }
  }
  return true;
}

