        name: "Illusory Subroutines — Invisible to " + victim.name,
        type: "target_modifier", subtype: "invisible",
        applyToTargetter: true, applyTo: [victim.id],
        rollTypes: ["attack", "tech_attack"]
      }, { duration: "start", durationTurns: 1,
        origin: token, refresh: true });
    }
  }
}

async function activation(type, data, token, item, name, api) {
  const targets = [...new Set((data.targets ?? [])
    .map(entry => entry?.target).filter(target => target?.actor))];
  for (const target of targets) {
    if (type === "onTechMiss") {
      await api.executeDamageRoll(token, [target], "2", "Heat", "Immolate — Miss");
      await api.applyEffectsToTokens({
        tokens: [target], effectNames: ["impaired"], note: "Immolate",
        duration: api.untilEndOfTurn(target, 1)
      }, { rebakedWitchImmolate: item.id });
      continue;
    }
    const heat = Math.max(0, Number(target.actor.system?.heat?.value ?? 0));
    if (heat > 0) await api.executeDamageRoll(token, [target],
      String(heat), "Burn", "Immolate");
    if (!api.hasStatus(target, "dangerzone") || heat <= 0) continue;
    const splash = await api.chooseToken(target, {
      title: "IMMOLATE — DANGER ZONE SPLASH",
      count: -1, range: 2, includeSelf: true, soft: true,
      description: "GM: select any characters within Burst 2 of " + target.name
        + " to make Systems saves against half the primary target's Burn (rounded up)."
    });
    const damage = Math.ceil(heat / 2);
    for (const other of splash ?? []) {
      if (!other?.actor || api.getMinGridDistance(target, other) > 2) continue;
      const saves = await api.executeSaveVsEffect([other], {
        stat: "SYSTEMS", title: "Immolate — Splash", origin: token,
        cardDescription: "Failure: take " + damage + " Burn."
      });
      if (!saves?.[0]?.result?.completed || saves[0].passed) continue;
      await api.executeDamageRoll(token, [other],
        String(damage), "Burn", "Immolate — Splash");
    }
  }
}

