    const lmg = api.findItemByLid(token.actor, "npc-rebake_npcf_light_machine_gun_archer");
    if (!acting || !movingTarget || !lmg) return false;
    const answer = await api.askCard({
      title: "IMPENDING THREAT", item, originToken: token,
      relatedToken: acting, owner: token,
      description: acting.name + " is taking an action. If that action does NOT target the Archer, use Moving Target to fire the Light Machine Gun before it resolves?",
      yesText: "Does Not Target Archer — Fire", noText: "Targets Archer / Decline"
    });
    if (!answer?.confirmed) return false;
    if (!await api.consumeOncePerRound(token, "moving_target_" + movingTarget.id)) return false;
    await api.setReaction(token, false);
    await api.removeEffectsByNameFromTokens({
      tokens: [acting], effectNames: ["Suppress", "impaired"],
      extraFlags: { suppressSourceId: token.id }, notify: false
    });
    await api.removeActorFlags(token.actor, {
      suppressTargetId: true, suppressLosLost: true
    });
    const suppress = api.findItemByLid(token.actor, "npc-rebake_npcf_suppress_archer");
    if (suppress && api.getActivatedItems(token).some(active => active.id === suppress.id))
      await api.endItemActivation(suppress, token);
    const hasSuperior = token.actor.items.some(i =>
      i.system?.lid === "npc-rebake_npcf_superior_sentinel_archer" && !i.system?.destroyed);
    const bonusId = "rebaked-archer-superior-sentinel-impending-" + item.id;
    if (hasSuperior) await api.addGlobalBonus(token.actor, {
      id: bonusId, name: "Superior Sentinel", type: "accuracy", val: 1,
      rollTypes: ["attack"], applyTo: [acting.id]
    }, { origin: token });
    try { await api.attackWith(lmg, [acting]); }
    finally {
      if (hasSuperior) await api.removeGlobalBonus(token.actor, b => b.id === bonusId);
    }
    return true;
  }

