reactions.evaluate:
function evaluate(triggerType, triggerData, reactorToken, item, activationName, api) {
const linkedTargetId = api.getActorFlags(
    reactorToken.actor,
    "investitureTargetId"
);

const triggeringToken = triggerData.triggeringToken ?? triggerData.token;

const getLinkedTarget = () =>
    linkedTargetId ? canvas.tokens.get(linkedTargetId) : null;

const isParticipant = token =>
    !!token && (
        token.id === reactorToken.id ||
        (!!linkedTargetId && token.id === linkedTargetId)
    );

if (triggerType === "onActivation") {
    return triggeringToken?.id === reactorToken.id
        && triggerData.item?.system?.lid === item?.system?.lid;
}

if (!linkedTargetId)
    return false;

if (triggerType === "onPreMove") {
    if (api.getActorFlags(reactorToken.actor, "empoweredInvestitureActive")) return false;
    if (!isParticipant(triggeringToken))
        return false;

    if (triggerData.moveInfo?.isInvoluntary || triggerData.moveInfo?.isUndo)
        return false;

    const linkedTarget = getLinkedTarget();
    if (!linkedTarget)
        return false;

    const otherToken = triggeringToken.id === reactorToken.id
        ? linkedTarget
        : reactorToken;

    if (triggerData.moveInfo?.isTeleport) {
        return api.getMinGridDistance(
            triggeringToken,
            otherToken,
            triggerData.endPos
        ) > 5;
    }

    const path = triggerData.moveInfo?.pathHexes ?? [];
    const startIndex = Math.max(0, path.historyStartIndex ?? 0);

    for (let i = startIndex; i < path.length; i++) {
        const step = path[i];

        const distance = api.getMinGridDistance(
            triggeringToken,
            otherToken,
            { x: step.x, y: step.y }
        );

        if (distance > 5)
            return true;
    }

    return api.getMinGridDistance(
        triggeringToken,
        otherToken,
        triggerData.endPos
    ) > 5;
}

if (triggerType === "onUpdate") {
    if (api.getActorFlags(reactorToken.actor, "empoweredInvestitureActive")) return false;
    if (!isParticipant(triggeringToken))
        return false;

    const change = triggerData.change ?? {};
    const positionChanged =
        Object.prototype.hasOwnProperty.call(change, "x") ||
        Object.prototype.hasOwnProperty.call(change, "y") ||
        Object.prototype.hasOwnProperty.call(change, "elevation");

    if (!positionChanged)
        return false;

    const linkedTarget = getLinkedTarget();

    if (!linkedTarget)
        return true;

    return api.getMinGridDistance(
        reactorToken,
        linkedTarget
    ) > 5;
}

if (triggerType === "onStatusApplied" || triggerType === "onStatusRemoved") {
    if (!isParticipant(triggeringToken))
        return false;

    const statusId = String(triggerData.statusId ?? "").toLowerCase();
    if (statusId !== "jammed" && statusId !== "stunned")
        return false;

    const flags = triggerData.effect?.flags?.["lancer-automations"] ?? {};
    return flags.investitureMirrorSourceItemId !== item.id;
}

if (triggerType === "onDestroyed") {
    return isParticipant(triggeringToken);
}

return false;
}

reactions.activationCode:
async function activation(triggerType, triggerData, reactorToken, item, activationName, api) {
if (triggerType === "onActivation") {
    }

const ATTACK_BONUS_ID = `investiture-attack-${item.id}`;
const SYSTEMS_BONUS_ID = `investiture-systems-${item.id}`;
const TECH_BONUS_ID = `investiture-tech-${item.id}`;

const getLinkedTarget = () => {
    const targetId = api.getActorFlags(
        reactorToken.actor,
        "investitureTargetId"
    );

    return targetId ? canvas.tokens.get(targetId) : null;
};

const clearInvestitureMirrors = async (tokens) => {
    const validTokens = tokens.filter(Boolean);
    if (!validTokens.length)
        return;

    await api.removeEffectsByNameFromTokens({
        tokens: validTokens,
        effectNames: ["jammed", "stunned"],
        extraFlags: {
            investitureMirrorSourceItemId: item.id
        },
        notify: false
    });
};

const removeInvestitureBonuses = async (target) => {
    if (!target?.actor)
        return;

    await api.removeConstantBonus(target.actor, ATTACK_BONUS_ID);
    await api.removeConstantBonus(target.actor, SYSTEMS_BONUS_ID);
    await api.removeConstantBonus(target.actor, TECH_BONUS_ID);
};

const clearInvestiture = async () => {
    const linkedTarget = getLinkedTarget();

    await removeInvestitureBonuses(linkedTarget);
    await clearInvestitureMirrors([reactorToken, linkedTarget]);

    await api.removeActorFlags(reactorToken.actor, {
        investitureTargetId: true
    });

    await reactorToken.document.unsetFlag(
        "lancer-automations",
        "ownerActorUuid"
    );

    await reactorToken.document.unsetFlag(
        "lancer-automations",
        "ownerName"
    );
};

const installInvestitureBonuses = async (target) => {
    const hasFortress = reactorToken.actor.items.some(feature => {
        const lid = String(feature.system?.lid ?? "").toLowerCase();
        const name = String(feature.name ?? "").toLowerCase();
        return lid === "npc-rebake_npcf_fortress_priest"
            || lid === "npcf_fortress_priest"
            || name === "fortress";
    });

    const hardenedValue = hasFortress ? 3 : 1;
    const hardenedName = hasFortress
        ? "Investiture — Hardened Target — Fortress"
        : "Investiture — Hardened Target";

    await api.addConstantBonus(target.actor, {
        id: ATTACK_BONUS_ID,
        name: "Investiture",
        type: "accuracy",
        val: 1,
        rollTypes: ["attack"],
        context: {
            investiture: true,
            sourcePriestTokenId: reactorToken.id,
            sourceItemId: item.id
        }
    });

    await api.addConstantBonus(target.actor, {
        id: SYSTEMS_BONUS_ID,
        name: hardenedName,
        type: "accuracy",
        val: hardenedValue,
        rollTypes: ["systems"],
        condition: (_state, _actor, data) =>
            String(data?.title ?? "").toLowerCase().includes("save"),
        context: {
            investiture: true,
            hardenedTarget: true,
            sourcePriestTokenId: reactorToken.id,
            sourceItemId: item.id
        }
    });

    await api.addConstantBonus(target.actor, {
        id: TECH_BONUS_ID,
        name: hardenedName,
        type: "difficulty",
        val: hardenedValue,
        rollTypes: ["tech_attack", "tech"],
        applyToTargetter: true,
        context: {
            investiture: true,
            hardenedTarget: true,
            sourcePriestTokenId: reactorToken.id,
            sourceItemId: item.id
        }
    });
};

if (triggerType === "onActivation") {
    const selected = await api.chooseToken(reactorToken, {
        range: 5,
        count: 1,
        disposition: "friendly",
        includeSelf: false,
        soft: false,
        title: "INVESTITURE — SELECT LINK",
        description: "Choose one allied mech or vehicle within Range 5.",
        icon: "fas fa-link",
        autoConfirm: true,
        filter: token => ["mech", "npc", "vehicle"].includes(token.actor?.type),
        filterWarning: "Investiture can only link to an allied mech or vehicle."
    });

    const target = selected?.[0];
    if (!target)
        return;

    const oldTarget = getLinkedTarget();

    if (oldTarget?.id === target.id) {
        await installInvestitureBonuses(target);
        return;
    }

    if (oldTarget)
        await clearInvestiture();

    await api.addActorFlags(reactorToken.actor, {
        investitureTargetId: target.id
    });

    await installInvestitureBonuses(target);

    await reactorToken.document.setFlag(
        "lancer-automations",
        "ownerActorUuid",
        target.actor.uuid
    );

    await reactorToken.document.setFlag(
        "lancer-automations",
        "ownerName",
        target.actor.name
    );

    return;
}

if (triggerType === "onPreMove") {
    const mover = triggerData.triggeringToken ?? triggerData.token;
    const linkedTarget = getLinkedTarget();

    if (!mover || !linkedTarget)
        return;

    const otherToken = mover.id === reactorToken.id
        ? linkedTarget
        : reactorToken;

    const preConfirm = async () => {
        const result = await api.startChoiceCard({
            mode: "or",
            title: "INVESTITURE — LINK BREAK",
            icon: "fas fa-link-slash",
            description: `Moving <b>${mover.name}</b> along this path will take them more than <b>Range 5</b> from <b>${otherToken.name}</b> and disable Investiture.`,
            item,
            originToken: reactorToken,
            relatedToken: mover,
            userIdControl: api.getTokenOwnerUserId(mover),
            choices: [
                {
                    text: "Break Link and Move",
                    icon: "fas fa-link-slash"
                },
                {
                    text: "Keep Link",
                    icon: "fas fa-link"
                }
            ]
        });

        if (!result || result.choiceIdx !== 0)
            return true;

        await clearInvestiture();
        return false;
    };

    await triggerData.cancelTriggeredMove(
        `<b>${mover.name}</b>'s movement would break Investiture with <b>${otherToken.name}</b>.`,
        false,
        api.getTokenOwnerUserId(mover),
        preConfirm,
        null,
        {
            item,
            originToken: reactorToken,
            relatedToken: otherToken
        }
    );

    return;
}

if (triggerType === "onUpdate") {
    await clearInvestiture();
    return;
}

if (triggerType === "onStatusApplied") {
    const affected = triggerData.triggeringToken;
    const linkedTarget = getLinkedTarget();

    if (!affected || !linkedTarget)
        return;

    const otherToken = affected.id === reactorToken.id
        ? linkedTarget
        : reactorToken;

    const statusId = String(triggerData.statusId ?? "").toLowerCase();

    await api.applyEffectsToTokens(
        {
            tokens: [otherToken],
            effectNames: [statusId],
            note: "Investiture",
            duration: { label: "indefinite" },
            notify: false
        },
        {
            investitureMirrorSourceItemId: item.id,
            investitureMirrorSourcePriestId: reactorToken.id,
            investitureOriginalEffectId: triggerData.effect?.id,
            investitureOriginalTokenId: affected.id
        }
    );

    return;
}

if (triggerType === "onStatusRemoved") {
    const affected = triggerData.triggeringToken;
    const linkedTarget = getLinkedTarget();

    if (!affected || !linkedTarget)
        return;

    const otherToken = affected.id === reactorToken.id
        ? linkedTarget
        : reactorToken;

    const statusId = String(triggerData.statusId ?? "").toLowerCase();

    await api.removeEffectsByNameFromTokens({
        tokens: [otherToken],
        effectNames: [statusId],
        extraFlags: {
            investitureMirrorSourceItemId: item.id,
            investitureOriginalEffectId: triggerData.effect?.id
        },
        notify: false
    });

    return;
}

if (triggerType === "onDestroyed") {
    await clearInvestiture();
}
}

