reactions.activationCode:
async function activation(type, data, token, item, name, api) {
    const bonusId = "rebaked-demolisher-kinetic-compensation-" + item.id;
    const flag = "rebakedDemolisherKineticCompensation";
    if (type === "onHit") {
      await api.removeGlobalBonus(token.actor, bonus => bonus.id === bonusId);
      await api.removeTokenFlags(token.document, { [flag]: true });
      return;
    }
    const count = Math.max(0, Number(api.getTokenFlags(token.document, flag) ?? 0)) + 1;
    const hammer = api.findItemByLid(token.actor,
      "npc-rebake_npcf_demolition_hammer_demolisher");
    if (!hammer) return;
    await api.removeGlobalBonus(token.actor, bonus => bonus.id === bonusId);
    await api.addTokenFlags(token.document, { [flag]: count });
    await api.addGlobalBonus(token.actor, {
      id: bonusId, name: "Kinetic Compensation (" + count + ")",
      type: "accuracy", val: count, rollTypes: ["attack"], itemId: hammer?.id,
      context: { rebakedDemolisherKineticCompensation: true }
    }, { duration: "indefinite", origin: token });
  }

async function activation(triggerType, data, token, item, name, api) {
    const targets = await api.chooseToken(token, {
      title: "LANCE SHOT — LINE 5", count: 99, pattern: "line",
      areaRange: 5, range: 5, size: 1, soft: false,
      description: "Place Line 5 and include every character at least partially within it."
    });
    if (!targets?.length) return;
    const results = await api.executeSaveVsEffect(targets, {
      stat: "HULL", title: "Lance Shot", origin: token,
      cardDescription: "On failure, Knockback 3; collision also Immobilizes until end of next turn."
    });
    for (const result of results ?? []) {
      if (!result.result?.completed || result.passed) continue;
      await api.knockBackToken(result.target, 3, {
        triggeringToken: token, item, actionName: "Lance Shot",
        title: "LANCE SHOT — KNOCKBACK 3",
        description: "GM: push away from the Cataphract, stopping at an obstruction or character."
      });
      const collided = await api.askCard({
        title: "LANCE SHOT — COLLISION", item, originToken: token, owner: token,
        description: "Did " + result.target.name + " collide with an obstruction or another character?",
        yesText: "Yes — Immobilize", noText: "No Collision"
      });
      if (collided?.confirmed) {
        await api.applyEffectsToTokens({
          tokens: [result.target], effectNames: ["immobilized"],
          note: "Lance Shot collision", duration: api.untilEndOfTurn(result.target, 1)
        });
      }
    }
  }

reactions.evaluate:
function evaluate(type, data, token, item, name, api) {
  if (type === "onActivation")
    return data.triggeringToken?.id === token.id
      && data.item?.id === item.id;
  const mover = data.triggeringToken;
  return !!mover?.actor && mover.id !== token.id
    && api.isHostile(token, mover)
    && api.getMinGridDistance(token, mover) <= 3
    && (Number(token.actor?.system?.hp?.value ?? 1) <= 0
      || api.hasReactionAvailable(token))
    && !api.getActorFlags(token.actor, "rebakedLastLineDisabled")
    && Number(item.system?.uses?.value ?? 1) > 0;
}

