reactions.onMessage:
async function onMessage(type, data, token, item, name, api) {
  if (!game.user.isGM) return false;
  if (data.action === "Disable Last Line (GM)") {
    await api.addActorFlags(token.actor, { rebakedLastLineDisabled: true });
    return true;
  }
  const mover = canvas.tokens.get(data.moverId);
  if (!mover?.actor || api.getMinGridDistance(token, mover) > 3
    || Number(item.system?.uses?.value ?? 1) <= 0
    || (Number(token.actor?.system?.hp?.value ?? 1) > 0
      && !api.hasReactionAvailable(token))
    || api.getActorFlags(token.actor, "rebakedLastLineDisabled")) return false;
  const fire = await api.askCard({
    title: "LAST LINE — HIDDEN MINE", item,
    originToken: token, relatedToken: mover, owner: token,
    description: mover.name + " moved within Range 3. Spend Last Line's Reaction and Limited use to detonate a hidden mine beneath them? This can be used while the Seeder is destroyed.",
    yesText: "Detonate", noText: "Hold"
  });
  if (!fire?.confirmed) return false;
  const kinds = ["Sealant","Explosive","Shock","Thermite"];
  const choice = await api.startChoiceCard({
    title: "LAST LINE — MINE TYPE", item,
    originToken: token, relatedToken: mover, owner: token,
    userIdControl: api.getActiveGMId(), mode: "or",
    description: "Choose the buried mine type.",
    choices: kinds.map(kind => ({ text: kind + " Mine", icon: "fas fa-bomb" }))
  });
  if (!Number.isInteger(choice?.choiceIdx)) return false;
  const placed = await api.placeZone(token, {
    type: "Blast", size: 1, range: 3, count: 1,
    title: "LAST LINE — BURST 1",
    description: "GM: center the hidden mine under " + mover.name
      + ". Its Burst 1 affects every character in the area."
  });
  const template = placed?.[0]?.template;
  if (!template) return false;
  async function rebakedResolveMine(api, origin, template, kind, item) {
  const data = template.getFlag("lancer-automations", "rebakedSeederMine");
  const base = Number(template.elevation ?? 0);
  const maxRise = data?.hopping ? 10 : 0;
  const targets = api.tokensInTemplate(template).filter(target =>
    target?.actor && Number(target.document?.elevation ?? 0) >= base
    && Number(target.document?.elevation ?? 0) <= base + maxRise);
  for (const target of targets) {
    const stat = { Sealant: "HULL", Explosive: "AGILITY",
      Shock: "SYSTEMS", Thermite: "ENGINEERING" }[kind];
    const saves = await api.executeSaveVsEffect([target], {
      stat, title: kind + " Mine", origin,
      cardDescription: "Resolve the " + kind + " Mine effect."
    });
    if (!saves?.[0]?.result?.completed) continue;
    const passed = saves[0].passed;
    if (kind === "Explosive")
      await api.executeDamageRoll(origin, [target],
        String(api.tierValue(origin, [8, 12, 16])), "Explosive",
        "Explosive Mine", { half_damage: passed });
    if (kind === "Thermite") {
      await api.executeDamageRoll(origin, [target],
        String(api.tierValue(origin, [4, 5, 6])), "Heat",
        "Thermite Mine", { half_damage: passed });
      if (!passed) await api.applyEffectsToTokens({
        tokens: [target], effectNames: [{ name: "Thermite Mine — Adjacent Sight Only",
          icon: item?.img ?? "icons/svg/eye.svg", isCustom: true }],
        note: "Can draw line of sight only to adjacent spaces until end of next turn.",
        duration: api.untilEndOfTurn(target, 1)
      });
    }
    if (!passed && kind === "Sealant")
      await api.applyEffectsToTokens({
        tokens: [target], effectNames: ["immobilized"],
        note: "Sealant Mine: then Slowed until end of subsequent turn.",
        duration: api.untilEndOfTurn(target, 1)
      });
    if (!passed && kind === "Shock")
      await api.applyEffectsToTokens({
        tokens: [target], effectNames: ["jammed"],
        note: "Shock Mine: then Impaired until end of subsequent turn.",
        duration: api.untilEndOfTurn(target, 1)
      });
  }
}
  try {
    await api.setItemResource(item, 0);
    if (api.hasReactionAvailable(token)) await api.setReaction(token, false);
    await rebakedResolveMine(api, token, template, kinds[choice.choiceIdx], item);
  } finally { await template.delete(); }
  return true;
}

reactions.evaluate:
function evaluate(type, data, token, item, name, api) {
  const subject = data.triggeringToken;
  if (type === "onActivation")
    return subject?.id === token.id && data.item?.id === item.id;
  if (type === "onDeploy")
    return subject?.id === token.id && data.item?.id === item.id;
  if (!subject) return false;
  const drones = canvas.tokens.placeables.filter(drone =>
    drone.document.getFlag("lancer-automations",
      "rebakedLatchOwnerUuid") === token.actor?.uuid
    && drone.document.getFlag("lancer-automations",
      "rebakedLatchItemId") === item.id);
  if (type === "onTurnStart")
    return drones.some(drone => drone.document.getFlag(
      "lancer-automations", "rebakedLatchTargetId") === subject.id);
  return false;
}

reactions.activationCode:
async function activation(type, data, token, item, name, api) {
  const gmId = api.getActiveGMId();
  if (!gmId || !game.users.get(gmId)?.active) {
    ui.notifications.warn("Latch Drone requires an active GM.");
    return;
  }
  await data.sendMessageToReactor({
    event: type, subjectId: data.triggeringToken?.id,
    deployedIds: (data.deployedTokens ?? []).map(drone => drone?.id)
      .filter(Boolean)
  }, gmId, { wait: true });
}

reactions.onInit:
async function onInit(token, item, api) {
  if (game.user.id === api.getActiveGMId()
    && !globalThis.__rebakedLatchCleanupRegistered) {
    globalThis.__rebakedLatchCleanupRegistered = true;
    const clearBonus = async droneDoc => {
      const targetId = droneDoc.getFlag("lancer-automations",
        "rebakedLatchTargetId");
      const actorUuid = droneDoc.getFlag("lancer-automations",
        "rebakedLatchTargetActorUuid");
      if (!actorUuid) return;
      const host = canvas.tokens.get(targetId)?.actor
        ?? await fromUuid(actorUuid);
      if (host) await api.removeConstantBonus(host,
        "rebaked-support-latch-" + droneDoc.id);
    };
    Hooks.on("deleteToken", async droneDoc => {
      await clearBonus(droneDoc);
      for (const drone of [...canvas.tokens.placeables]) {
        const ownerUuid = drone.document.getFlag("lancer-automations",
          "rebakedLatchOwnerUuid");
        const hostId = drone.document.getFlag("lancer-automations",
          "rebakedLatchTargetId");
        if (ownerUuid && (hostId === droneDoc.id
          || ownerUuid === droneDoc.actor?.uuid))
          await drone.document.delete();
      }
    });
    Hooks.on("updateActor", async actor => {
      if (Number(actor.system?.hp?.value ?? 1) > 0) return;
      for (const drone of canvas.tokens.placeables) {
        if (drone.actor?.uuid !== actor.uuid) continue;
        await clearBonus(drone.document);
      }
    });
    for (const host of canvas.tokens.placeables) {
      if (!host.actor) continue;
      for (const bonus of api.getConstantBonuses(host.actor)) {
        if (!bonus.id?.startsWith("rebaked-support-latch-")) continue;
        const droneId = bonus.id.slice("rebaked-support-latch-".length);
        const drone = canvas.tokens.get(droneId);
        if (!drone || Number(drone.actor?.system?.hp?.value ?? 0) <= 0)
          await api.removeConstantBonus(host.actor, bonus.id);
      }
    }
  }
  if (!item) return;
  const sources = [];
  for (const tier of [1, 2, 3]) {
    const sourceName = "Re:Baked Latch Drone T" + tier + " (NPC)";
    let source = null;
    for (const pack of game.packs.filter(pack => pack.documentName === "Actor")) {
      const entry = (await pack.getIndex()).find(entry => entry.name === sourceName);
      if (!entry) continue;
      const candidate = await pack.getDocument(entry._id);
      if (candidate?.type === "deployable" && candidate.system?.lid) {
        source = candidate;
        break;
      }
    }
    if (!source) {
      ui.notifications.warn("Latch Drone: import Rebaked_NPC_Deployables_Public_v1.lcp, then reload Foundry to register its Deployables entry.");
      return;
    }
    sources.push({ lid: source.system.lid, tier });
  }
  const previous = item.getFlag("lancer-automations", "extraDeployables") ?? [];
  if (item.system?.deployables?.length)
    await item.update({ "system.deployables": [] });
  if (previous.length !== 3 || previous.some((lid, index) =>
    lid !== sources[index].lid)) {
    await api.addItemFlags(item, {
      extraDeployables: [], extraDeployableLidsViaUI: [],
      extraDeployableOpts: {}
    });
    await api.addExtraDeploymentLids(item, sources);
  }
  if (item.getFlag("lancer-automations", "deployRange") !== 5
    || item.getFlag("lancer-automations", "deployCount") !== 1)
    await api.addItemFlags(item, { deployRange: 5, deployCount: 1 });
  await api.setHidePrimaryAction(item);
}

reactions.onMessage:
async function onMessage(type, data, token, item, name, api) {
  if (!game.user.isGM) return false;
  const attacher = globalThis.tokenAttacher;
  const own = () => canvas.tokens.placeables.filter(drone =>
    drone.document.getFlag("lancer-automations",
      "rebakedLatchOwnerUuid") === token.actor?.uuid
    && drone.document.getFlag("lancer-automations",
      "rebakedLatchItemId") === item.id);
  const clear = async (drone, destroy) => {
    const targetId = drone.document.getFlag("lancer-automations",
      "rebakedLatchTargetId");
    const target = canvas.tokens.get(targetId);
    const actorUuid = drone.document.getFlag("lancer-automations",
      "rebakedLatchTargetActorUuid");
    const actor = target?.actor ?? (actorUuid ? await fromUuid(actorUuid) : null);
    if (target && attacher?.detachElementFromToken)
      await attacher.detachElementFromToken(drone, target, true);
    if (actor) await api.removeConstantBonus(actor,
      "rebaked-support-latch-" + drone.id);
    if (destroy && canvas.tokens.get(drone.id)) await drone.document.delete();
  };
  if (["onActivation", "onDeploy"].includes(data.event)) {
    for (const old of own()) await clear(old, true);
    if (data.event === "onActivation") return true;
  }
  if (data.event === "onTurnStart") {
    for (const drone of own().filter(candidate =>
      candidate.document.getFlag("lancer-automations",
        "rebakedLatchTargetId") === data.subjectId)) {
      const target = canvas.tokens.get(data.subjectId);
      if (!target?.actor || Number(drone.actor?.system?.hp?.value ?? 0) <= 0)
        continue;
      const current = Number(target.actor.system?.hp?.value ?? 0);
      const maximum = Number(target.actor.system?.hp?.max ?? current);
      if (current <= 0 || maximum <= current) continue;
      const amount = Number(api.tierValue(token, [5, 8, 10]));
      await target.actor.update({ "system.hp.value":
        Math.min(maximum, current + amount) });
      ui.notifications.info(target.name + " regains "
        + Math.min(amount, maximum - current) + " HP from Latch Drone.");
    }
    return true;
  }
  for (const id of data.deployedIds ?? []) {
  const drone = canvas.tokens.get(id);
  if (!drone?.actor
    || api.getLAFlag(drone.document, "ownerActorUuid") !== token.actor?.uuid
    || drone.document.getFlag("lancer-automations", "rebakedLatchTargetId"))
    continue;
  const target = canvas.tokens.placeables.find(candidate =>
    ['mech', 'npc', 'pilot'].includes(candidate.actor?.type)
    && candidate.bounds.contains(drone.center.x, drone.center.y));
  if (!target?.actor || api.getMinGridDistance(token, target) > 5) {
    await drone.document.delete();
    continue;
  }
  const droneDoc = drone.document;
  const sourceActor = game.actors.get(droneDoc.actorId);
  if (sourceActor?.name !== "Latch Drone")
    await sourceActor?.update({ name: "Latch Drone" });
  if (droneDoc.name !== "Latch Drone")
    await droneDoc.update({ name: "Latch Drone" });
  if (!attacher?.attachElementToToken) {
    ui.notifications.error("Latch Drone requires Token Attacher.");
    await drone.document.delete();
    continue;
  }
  await attacher.attachElementToToken(drone, target, true);
  await drone.document.setFlag("lancer-automations",
    "rebakedLatchOwnerUuid", token.actor.uuid);
  await drone.document.setFlag("lancer-automations",
    "rebakedLatchItemId", item.id);
  await drone.document.setFlag("lancer-automations",
    "rebakedLatchTargetId", target.id);
  await drone.document.setFlag("lancer-automations",
    "rebakedLatchTargetActorUuid", target.actor.uuid);
  await api.addConstantBonus(target.actor, {
    id: "rebaked-support-latch-" + drone.id,
    name: "Latch Drone — Accuracy",
    type: "accuracy", val: 1,
    rollTypes: ["check", "attack", "tech_attack"],
    context: { latchDroneId: drone.id },
    condition: function(state, actor, flowData, context) {
      const source = canvas.tokens.get(context.latchDroneId);
      return !!source && Number(source.actor?.system?.hp?.value ?? 0) > 0;
    }
  });
  }
  return true;
}

reactions.evaluate:
function evaluate(type, data, token, item) {
    return data.triggeringToken?.id === token.id
      && (type !== "onActivation" || data.item?.id === item.id);
  }

reactions.activationCode:
async function activation(type, data, token, item, name, api) {
    const gmId = api.getActiveGMId();
    if (!gmId || !game.users.get(gmId)?.active) return;
    await data.sendMessageToReactor({ event: type, action: name }, gmId,
      { wait: true });
