reactions.onMessage:
async function onMessage(type, data, token, item, name, api) {
    if (!game.user.isGM || !token?.actor) return false;
    const flag = "rebakedSeederMine";
    const kinds = ["Sealant", "Explosive", "Shock", "Thermite"];
    const own = () => canvas.tokens.placeables.filter(mine =>
      mine.document.getFlag("lancer-automations", flag)?.ownerActorUuid
        === token.actor.uuid);
    const resolve = async mine => {
      const state = mine.document.getFlag("lancer-automations", flag);
      if (!state || state.resolved) return;
      await mine.document.setFlag("lancer-automations", flag,
        { ...state, resolved: true });
      const owner = canvas.tokens.get(state.ownerId);
      const origin = owner ?? await fromUuid(state.ownerActorUuid);
      const targets = canvas.tokens.placeables.filter(other =>
        ["mech", "npc", "pilot"].includes(other.actor?.type)
        && api.getMinGridDistance(mine, other) <= 1
        && (state.hopping
          ? Number(other.document.elevation ?? 0) >= Number(mine.document.elevation ?? 0)
            && Number(other.document.elevation ?? 0) <= Number(mine.document.elevation ?? 0) + 10
          : Math.abs(Number(other.document.elevation ?? 0)
            - Number(mine.document.elevation ?? 0)) <= 0.1));
      try {
        for (const target of targets) {
          const stat = { Sealant: "HULL", Explosive: "AGILITY",
            Shock: "SYSTEMS", Thermite: "ENGINEERING" }[state.kind];
          const saves = await api.executeSaveVsEffect([target], {
            stat, title: state.kind + " Mine", origin,
            cardDescription: "Resolve the " + state.kind + " Mine effect."
          });
          if (!saves?.[0]?.result?.completed) continue;
          const passed = saves[0].passed;
          if (state.kind === "Explosive")
            await api.executeDamageRoll(origin, [target],
              String(api.tierValue(origin, [8, 12, 16])), "Explosive",
              "Explosive Mine", { half_damage: passed });
          if (state.kind === "Thermite") {
            await api.executeDamageRoll(origin, [target],
              String(api.tierValue(origin, [4, 5, 6])), "Heat",
              "Thermite Mine", { half_damage: passed });
            if (!passed) await api.applyEffectsToTokens({
              tokens: [target],
              effectNames: [{ name: "Thermite Mine — Adjacent Sight Only",
                icon: item.img, isCustom: true }],
              note: "Can draw line of sight only to adjacent spaces until the end of next turn.",
              duration: api.untilEndOfTurn(target, 1)
            });
          }
          if (!passed && state.kind === "Sealant")
            await api.applyEffectsToTokens({ tokens: [target],
              effectNames: ["immobilized"],
              note: "Sealant Mine: then Slowed until the end of the subsequent turn.",
              duration: api.untilEndOfTurn(target, 1) });
          if (!passed && state.kind === "Shock")
            await api.applyEffectsToTokens({ tokens: [target],
              effectNames: ["jammed"],
              note: "Shock Mine: then Impaired until the end of the subsequent turn.",
              duration: api.untilEndOfTurn(target, 1) });
        }
        await api.removeActorFlags(token.actor,
          { rebakedSeederSpeedDeployerLocked: true });
      } finally {
        if (canvas.scene.tokens.get(mine.id)) await mine.document.delete();
      }
    };
    if (data.event === "onDestroyed" || data.event === "onTokenRemoved") {
      for (const mine of own()) {
        const state = mine.document.getFlag("lancer-automations", flag);
        await mine.document.setFlag("lancer-automations", flag,
          { ...state, ownerDestroyed: true });
      }
      return true;
    }
    if (data.action === "Reveal Seeder Mine (GM)"
      || data.action === "Resolve Seeder Mine Disarm (GM)") {
      const mines = own();
      if (!mines.length) {
        ui.notifications.info("This Seeder has no deployed mines.");
        return false;
      }
      const chosen = await api.startChoiceCard({
        title: data.action, item, originToken: token, owner: token,
        userIdControl: api.getActiveGMId(), mode: "or",
        description: "Choose the mine after the character's Systems check.",
        choices: mines.map((mine, index) => ({
          text: (index + 1) + ". "
            + mine.document.getFlag("lancer-automations", flag).kind
            + " Mine", icon: "fas fa-bomb" }))
      });
      const mine = mines[chosen?.choiceIdx];
      if (!mine) return false;
      if (data.action === "Reveal Seeder Mine (GM)") {
        await mine.document.update({ hidden: false });
        await api.removeEffectsByNameFromTokens({ tokens: [mine],
          effectNames: ["hidden"], notify: false });
        return true;
      }
      const outcome = await api.askCard({
        title: "DISARM SEEDER MINE", item, originToken: token,
        owner: token, relatedToken: mine,
        description: "Did the adjacent character pass their quick-action Systems check? A failed check detonates the mine.",
        yesText: "Passed — disarm", noText: "Failed — detonate"
      });
      if (!outcome) return false;
      if (outcome?.confirmed) {
        await mine.document.delete();
        await api.removeActorFlags(token.actor,
          { rebakedSeederSpeedDeployerLocked: true });
      } else await resolve(mine);
      return true;
    }
    const speedItem = api.findItemByLid(token.actor,
      "npc-rebake_npcf_speed_deployer_seeder");
    const speed = !!speedItem && !speedItem.system?.destroyed;
    const locked = api.getActorFlags(token.actor,
      "rebakedSeederSpeedDeployerLocked") === true;
    let count = 1;
    if (speed && !locked) {
      const amount = await api.startChoiceCard({
        title: "SPEED DEPLOYER — MINE COUNT", item,
        originToken: token, owner: token,
        userIdControl: api.getActiveGMId(), mode: "or",
        description: "Choose how many mines to lay (maximum three).",
        choices: [1, 2, 3].map(value => ({
          text: String(value) + (value === 1 ? " mine" : " mines"),
          icon: "fas fa-bomb" }))
      });
      if (!Number.isInteger(amount?.choiceIdx)) return false;
      count = amount.choiceIdx + 1;
    }
    const rules = {
      Sealant: "Burst 1. Hull save or Immobilized until the end of the next turn, then Slowed until the end of the subsequent turn.",
      Explosive: "Burst 1. Agility save; 8/12/16 Explosive damage, or half on success.",
      Shock: "Burst 1. Systems save or Jammed until the end of the next turn, then Impaired until the end of the subsequent turn.",
      Thermite: "Burst 1. Engineering save; 4/5/6 Heat and line of sight only to adjacent spaces until the end of the next turn. On success, half Heat only."
    };
    const sources = {};
    for (const kind of kinds) {
      let source = game.actors.find(actor => actor.type === "deployable"
        && actor.getFlag("lancer-automations", "rebakedSeederMineSource") === kind);
      if (!source) source = await Actor.create({
        name: kind + " Mine", type: "deployable",
        img: "modules/lancer-automations/icons/land-mine.svg",
        system: { lid: "dep_rebaked_seeder_" + kind.toLowerCase() + "_mine",
          type: "Mine", detail: rules[kind],
          hp: { value: 5, max: 5, min: 0 }, evasion: 5, edef: 5,
          size: 0.5, activations: 0 },
        prototypeToken: { name: kind + " Mine", width: 1, height: 1,
          actorLink: false, hidden: true,
          disposition: token.document.disposition,
          texture: { src: "modules/lancer-automations/icons/land-mine.svg" } },
        ownership: { default: 0 },
        flags: { "lancer-automations": { rebakedSeederMineSource: kind,
          customMineDetection: true } }
      });
      if (!source) return false;
      if (!api.getActorFlags(source, "customMineDetection"))
        await api.addActorFlags(source, { customMineDetection: true });
      sources[kind] = source;
    }
    if (!game.modules.get("grid-aware-auras")?.active) {
      ui.notifications.error("Lay Mines requires Grid-Aware Auras.");
      return false;
    }
    let deployed = 0;
    for (let index = 0; index < count; index++) {
      const selected = await api.startChoiceCard({
        title: "LAY MINES — TYPE", item, originToken: token, owner: token,
        userIdControl: api.getActiveGMId(), mode: "or",
        description: "Choose the mine type, then place it in a free space within Range 3.",
        choices: kinds.map(kind => ({ text: kind + " Mine", icon: "fas fa-bomb" }))
      });
      if (!Number.isInteger(selected?.choiceIdx)) break;
      const kind = kinds[selected.choiceIdx];
      const previous = own();
      let replacement = null;
      if (previous.length >= 3) {
        const pick = await api.startChoiceCard({
          title: "LAY MINES — REPLACE ONE", item,
          originToken: token, owner: token,
          userIdControl: api.getActiveGMId(), mode: "or",
          description: "Choose an existing mine to deactivate after placing this one.",
          choices: previous.map((mine, i) => ({
            text: (i + 1) + ". "
              + mine.document.getFlag("lancer-automations", flag).kind,
            icon: "fas fa-bomb" }))
        });
        replacement = previous[pick?.choiceIdx];
        if (!replacement) break;
      }
      const placed = await api.placeDeployable({
        deployable: sources[kind], ownerActor: token.actor, systemItem: item,
        consumeUse: false, range: 3, count: 1, at: token,
        title: "LAY " + kind.toUpperCase() + " MINE"
      });
      // LA's placeDeployable returns TokenDocuments, not canvas Token objects.
      const mineDoc = Array.isArray(placed) ? placed[0] : placed;
      const mine = canvas.tokens.get(mineDoc?.id);
      if (!mine?.document) break;
      if (canvas.tokens.placeables.some(other => other.id !== mine.id
        && other.bounds?.intersects(mine.bounds))) {
        await mine.document.delete();
        ui.notifications.warn("Lay Mines requires a free space.");
        break;
      }
      const hoppingItem = api.findItemByLid(token.actor,
        "npc-rebake_npcf_hopping_mines_seeder");
      const hopping = !!hoppingItem && !hoppingItem.system?.destroyed;
      await mine.document.update({ hidden: true, name: kind + " Mine" });
      await mine.document.setFlag("lancer-automations", flag, {
        ownerId: token.id, ownerActorUuid: token.actor.uuid,
        itemId: item.id, kind, hopping, ownerDestroyed: false,
        resolved: false
      });
      await api.addTokenFlags(mine.document, { wasArmed: true });
      const auraName = "Seeder " + kind + " Mine — " + mine.id;
      await api.ensureAura(mine, {
        name: auraName, unified: false, radius: 1, innerRadius: 0,
        fillColor: "#9a6638", lineColor: "#ffc769",
        fillOpacity: 0.13, lineOpacity: 0.8,
        ownerVisibility: { default: true },
        nonOwnerVisibility: { default: false, hovered: false,
          targeted: false, turn: false },
        macros: [{ mode: "ENTER", targetTokens: "ALL",
          function: async function (subject, parent, aura, options) {
            if (options?.isInit || options?.isPreview || !subject?.actor
              || !parent?.document) return;
            const la = game.modules.get("lancer-automations")?.api;
            if (!la || game.user.id !== la.getActiveGMId()) return;
            const flag = "rebakedSeederMine";
            const state = parent.document.getFlag("lancer-automations", flag);
            if (!state || state.resolved) return;
            const owner = canvas.tokens.get(state.ownerId);
            if (!state.ownerDestroyed
              && (!owner?.actor || !la.isHostile(owner, subject))) return;
            const base = Number(parent.document.elevation ?? 0);
            const height = Number(subject.document.elevation ?? 0);
            if (state.hopping ? height < base || height > base + 10
              : Math.abs(height - base) > 0.1) return;
            const seeder = owner ?? await fromUuid(state.ownerActorUuid);
            const sourceItem = seeder?.actor?.items?.get(state.itemId)
              ?? seeder?.items?.get(state.itemId);
            if (!seeder || !sourceItem) return;
            await parent.document.setFlag("lancer-automations", flag,
              { ...state, resolved: true });
            try {
              const targets = canvas.tokens.placeables.filter(other =>
                ["mech", "npc", "pilot"].includes(other.actor?.type)
                && la.getMinGridDistance(parent, other) <= 1
                && (state.hopping
                  ? Number(other.document.elevation ?? 0) >= base
                    && Number(other.document.elevation ?? 0) <= base + 10
                  : Math.abs(Number(other.document.elevation ?? 0) - base) <= 0.1));
              for (const target of targets) {
                const stat = { Sealant: "HULL", Explosive: "AGILITY",
                  Shock: "SYSTEMS", Thermite: "ENGINEERING" }[state.kind];
                const saves = await la.executeSaveVsEffect([target], {
                  stat, title: state.kind + " Mine", origin: seeder,
                  cardDescription: "Resolve the " + state.kind + " Mine effect."
                });
                if (!saves?.[0]?.result?.completed) continue;
                const passed = saves[0].passed;
                if (state.kind === "Explosive")
                  await la.executeDamageRoll(seeder, [target],
                    String(la.tierValue(seeder, [8, 12, 16])), "Explosive",
                    "Explosive Mine", { half_damage: passed });
                if (state.kind === "Thermite") {
                  await la.executeDamageRoll(seeder, [target],
                    String(la.tierValue(seeder, [4, 5, 6])), "Heat",
                    "Thermite Mine", { half_damage: passed });
                  if (!passed) await la.applyEffectsToTokens({
                    tokens: [target],
                    effectNames: [{ name: "Thermite Mine — Adjacent Sight Only",
                      icon: sourceItem.img, isCustom: true }],
                    note: "Can draw line of sight only to adjacent spaces until the end of next turn.",
                    duration: la.untilEndOfTurn(target, 1)
                  });
                }
                if (!passed && state.kind === "Sealant")
                  await la.applyEffectsToTokens({ tokens: [target],
                    effectNames: ["immobilized"],
                    note: "Sealant Mine: then Slowed until the end of the subsequent turn.",
                    duration: la.untilEndOfTurn(target, 1) });
                if (!passed && state.kind === "Shock")
                  await la.applyEffectsToTokens({ tokens: [target],
                    effectNames: ["jammed"],
                    note: "Shock Mine: then Impaired until the end of the subsequent turn.",
                    duration: la.untilEndOfTurn(target, 1) });
              }
              const actor = seeder.actor ?? seeder;
              await la.removeActorFlags(actor,
                { rebakedSeederSpeedDeployerLocked: true });
            } finally {
              if (canvas.scene.tokens.get(parent.id)) await parent.document.delete();
            }
          } }]
      });
      if (!api.findAura(mine, auraName)) {
        await mine.document.delete();
        ui.notifications.error("Seeder Mine: its GM trigger aura was not created.");
        break;
      }
      // Assert the Foundry visibility toggle after deployment and aura setup.
      if (!mine.document.hidden) await mine.document.update({ hidden: true });
      if (replacement) await replacement.document.delete();
      deployed++;
    }
    if (deployed > 1) await api.addActorFlags(token.actor,
      { rebakedSeederSpeedDeployerLocked: true });
    return deployed > 0;
  }

reactions.evaluate:
