    && data.weapon?.system?.lid === "npc-rebake_npcf_flamethrower_pyro";
}

reactions.activationCode:
async function activation(type, data, token, item, name, api) {
  const existing = canvas.scene.templates.filter(zone =>
    zone.getFlag("lancer-automations", "rebakedLingeringFlames")?.ownerTokenId === token.id);
  for (const zone of existing) await zone.delete();
  const gmId = api.getActiveGMId();
  if (!gmId || !game.users.get(gmId)?.active) return;
  api.afterFlow(data, () => data.sendMessageToReactor({}, gmId, { wait: true }));
}

reactions.onMessage:
async function onMessage(type, data, token, item, name, api) {
  if (!game.user.isGM) return false;
  const placed = await api.placeZone(token, {
    type: "Blast", size: 0, range: 5, count: 3,
    title: "LINGERING FLAMES — THREE FREE SPACES",
    centerLabel: "FLAME", fillColor: "#e46d20", borderColor: "#ffc366",
    description: "GM: place each single-space patch in a free space of the Flamethrower's Cone 5 area. The picker does not itself enforce the original cone."
  });
  const hook = (trigger, code) => ({
    id: foundry.utils.randomID(), trigger, actionType: "code",
    targetFilter: "ALL", asGM: true, code, macroUuid: "",
    effectName: "", effectMode: "apply"
  });
  for (const entry of placed ?? []) {
    const zone = entry?.template;
    if (!zone) continue;
    if (api.tokensInTemplate(zone).length) {
      await zone.delete();
      ui.notifications.warn("Lingering Flames: choose a free space in the Flamethrower area.");
      continue;
    }
    await zone.update({
      "flags.lancer-automations.rebakedLingeringFlames": {
        ownerTokenId: token.id, itemId: item.id
      },
      "flags.templatemacro.actions": [
        hook("whenTurnStart", "const api = game.modules.get(\"lancer-automations\")?.api;\nconst ownerId = template.getFlag(\"lancer-automations\", \"rebakedLingeringFlames\")?.ownerTokenId;\nconst owner = canvas.tokens.get(ownerId);\nconst target = token?.object ?? token;\nif (!api || !owner?.actor || !target?.actor) return;\nawait api.executeDamageRoll(owner, [target],\n  String(api.tierValue(owner, [2, 3, 4])), \"Burn\", \"Lingering Flames\");"),
        hook("whenEntered", "const api = game.modules.get(\"lancer-automations\")?.api;\nconst target = token?.object ?? token;\nconst combat = game.combat;\nif (!api || !target?.actor || !combat) return;\nconst key = combat.id + \":\" + combat.round;\nconst used = { ...(template.getFlag(\"lancer-automations\", \"rebakedLingeringEntered\") ?? {}) };\nif (used[target.id] === key) return;\nused[target.id] = key;\nawait template.setFlag(\"lancer-automations\", \"rebakedLingeringEntered\", used);\nawait template.callMacro(\"whenTurnStart\", {\n  userId: game.user.id, gmId: api.getActiveGMId(), tokenId: target.id,\n  coords: { previous: null, current: { x: template.x, y: template.y } }\n});")
      ]
    });
  }
  return true;
}

reactions.evaluate:
