reactions.activationCode:
async function activation(type, data, token, item, name, api) {
    if (type !== "onActivation") {
      const gmId = api.getActiveGMId();
      if (gmId && game.users.get(gmId)?.active)
        await data.sendMessageToReactor({ clearJavelin: true }, gmId, { wait: true });
      return;
    }
    const key = "rebakedHornetJavelinTargetId";
    const flags = { rebakedHornetJavelin: item.id, sourceTokenId: token.id };
    const clear = async () => {
      const previous = canvas.tokens.get(api.getActorFlags(token.actor, key));
      if (previous) await api.removeEffectsByNameFromTokens({
        tokens: [previous], effectNames: ["immobilized", "shredded"],
        extraFlags: flags, notify: false
      });
      await api.removeActorFlags(token.actor, { [key]: true });
    };
    const target = (await api.chooseToken(token, {
      title: "LOCK/HOLD JAVELINS — TARGET", count: 1, range: 5,
      includeSelf: false, soft: false,
      description: "GM: choose a character within Range 5 and line of sight."
    }))?.[0];
    if (!target || api.getMinGridDistance(token, target) > 5) return;
    await clear();
    const saves = await api.executeSaveVsEffect([target], {
      stat: "HULL", title: "Lock/Hold Javelins", origin: token,
      cardDescription: "On failure, Immobilized and Shredded until removed by a full-action Hull save, Hornet reuse, or scene end."
    });
    if (!saves?.[0]?.result?.completed || saves[0].passed) return;
    await api.applyEffectsToTokens({
      tokens: [target], effectNames: ["immobilized", "shredded"],
      note: "Javelin tether: target or adjacent character may remove with a successful Hull save as a full action (GM handles this attempt).",
      duration: { label: "indefinite" }
    }, flags);
    await api.addActorFlags(token.actor, { [key]: target.id });
  }

