async function activation(type, data, token, item, name, api) {
    const targets = [...new Set((data.targets ?? [])
      .map(hit => hit?.target).filter(target => target?.actor))];
    for (const target of targets) {
      const ownerId = api.getTokenOwnerUserId(target);
      const chooser = ownerId && game.users.get(ownerId)?.active
        ? ownerId : api.getActiveGMId();
      const answer = await api.askCard({
        title: "LURE — TARGET'S CHOICE", item,
        originToken: token, relatedToken: target, owner: target,
        userIdControl: chooser,
        description: target.name + ": choose to move your Speed toward the Specter now, or become Slowed and Impaired until the end of your next turn.",
        yesText: "Move Toward Specter", noText: "Slowed + Impaired"
      });
      if (!answer) continue;
      if (answer.confirmed) {
        await api.moveTokenRuler(target, {
          range: Number(api.tokenSpeed(target)) || 0,
          cost: 0, free: true, action: "walk", urgent: true,
          title: "LURE — MOVE TOWARD SPECTER",
          description: "GM: move " + target.name + " its full Speed toward "
            + token.name + ", or as far as a legal path allows. Adjudicate obstructions."
        });
        continue;
      }
      await api.applyEffectsToTokens({
        tokens: [target], effectNames: ["slow", "impaired"],
        note: "Lure", duration: api.untilEndOfTurn(target, 1)
      }, { rebakedSpecterLure: item.id });
    }
  }

async function activation(type, data, token, item, name, api) {
    const gmId = api.getActiveGMId();
    if (!gmId || !game.users.get(gmId)?.active) {
      ui.notifications.warn("Machine Pistol movement requires an active GM.");
      return;
    }
    const choice = await api.startChoiceCard({
