reactions.activationCode:
async function activation(type, data, token, item, name, api) {
  const key = "rebakedGoliathMagGauntletTargetId";
  const flags = { rebakedGoliathMagGauntlet: item.id, sourceTokenId: token.id };
  const prior = canvas.tokens.get(api.getActorFlags(token.actor, key));
  if (type === "onDestroyed" || type === "onTokenRemoved") {
    if (prior) await api.removeEffectsByNameFromTokens({
      tokens: [prior], effectNames: ["grappled"], extraFlags: flags,
      notify: false
    });
    await api.removeActorFlags(token.actor, { [key]: true });
    return;
  }
  if (prior && api.findEffectsOnToken(prior, "grappled", {
    extraFlags: flags
  }).length) {
    ui.notifications.warn("Mag Gauntlet: this Goliath is already grappling a target this way.");
    return;
  }
  if (prior) await api.removeActorFlags(token.actor, { [key]: true });
  const target = (await api.chooseToken(token, {
    title: "MAG GAUNTLET — TARGET", count: 1,
    range: "sensors", includeSelf: false, soft: false,
    description: "GM: choose a character within Sensors and line of sight."
  }))?.[0];
  if (!target || api.getMinGridDistance(token, target) > api.getSensorRange_WithBonus(token)) return;
  const saves = await api.executeSaveVsEffect([target], {
    stat: "HULL", title: "Mag Gauntlet", origin: token,
    cardDescription: "On failure, the target is pulled 3 spaces toward the Goliath; if adjacent, it becomes Grappled."
  });
  if (!saves?.[0]?.result?.completed || saves[0].passed) return;
  if (api.getMinGridDistance(token, target) > 1)
    await api.knockBackToken([target], -3, {
      triggeringToken: token, actionName: "Mag Gauntlet", item,
      title: "MAG GAUNTLET — PULL 3",
      description: "GM: pull up to 3 spaces directly toward the Goliath, stopping at obstructions."
    });
  if (api.getMinGridDistance(token, target) > 1) return;
  await api.applyEffectsToTokens({
    tokens: [target], effectNames: ["grappled"], note: "Mag Gauntlet",
    duration: { label: "indefinite" }
  }, flags);
  await api.addActorFlags(token.actor, { [key]: target.id });
}

