    if (!ally?.actor || !api.isFriendly(token, ally)
      || !api.hasLineOfSight(token, ally)) return false;
    const choice = await api.startChoiceCard({
      title: "FALSE IDOL — DESTINATION", item, originToken: token,
      relatedToken: ally, owner: token, mode: "or",
      description: "Choose a remaining construct for " + ally.name
        + ". The GM must place them in sufficient free space at that location.",
      choices: constructs.map((template, index) => ({
        text: "Construct " + (index + 1) + " (" + Math.round(template.x)
          + ", " + Math.round(template.y) + ")",
        icon: "fas fa-clone"
      }))
    });
    const idol = constructs[choice?.choiceIdx];
    if (!idol) return false;
    const start = { x: ally.document.x, y: ally.document.y,
      elevation: ally.document.elevation };
    const moved = await api.moveTokenRuler(ally, {
      range: api.getMinGridDistance(ally, token) + 5,
      cost: 0, free: true, action: "blink", urgent: true,
      title: "FALSE IDOL — TELEPORT TO CONSTRUCT",
      description: "GM: teleport " + ally.name + " to a free position overlapping the chosen construct. The construct disappears on success."
    });
    if (!moved) return false;
    if (!api.tokensInTemplate(idol).some(other => other.id === ally.id)) {
      await ally.document.update(start, { teleport: true,
        lancerFreeMovement: true, IgnorePreMove: true });
      ui.notifications.warn("False Idol teleport must end at the selected construct; movement was undone.");
      return false;
    }
    await idol.delete();
    return true;
  }
  const next = [];
  for (let index = 0; index < 3; index++) {
    let zone = null;
    while (!zone) {
      const placed = await api.placeZone(token, {
        type: "Blast", size: 0, range: 5, los: true, count: 1,
        centerLabel: "FALSE IDOL", fillColor: "#6c7fc1",
        borderColor: "#c1d6ff",
        title: "MANIFEST FALSE IDOLS — " + (index + 1) + "/3",
        description: "GM: place one Size 1 construct in a free space within Range 5 and line of sight."
      });
      const candidate = placed?.[0]?.template;
      if (!candidate) {
        for (const created of next) await created.delete();
        return false;
      }
      const overlap = api.tokensInTemplate(candidate).length > 0
        || next.some(other => Math.hypot(other.x - candidate.x,
          other.y - candidate.y) < canvas.grid.size / 2);
      if (overlap) {
        await candidate.delete();
        ui.notifications.warn("False Idols require three distinct free spaces.");
        continue;
      }
      zone = candidate;
    }
    next.push(zone);
  }
  const hook = (trigger, code) => ({
    id: foundry.utils.randomID(), trigger, actionType: "code",
    targetFilter: "ALL", asGM: true, code,
    macroUuid: "", effectName: "", effectMode: "apply"
  });
  const enterCode = "const api = game.modules.get(\"lancer-automations\")?.api;\nconst state = template.getFlag(\"lancer-automations\", \"rebakedMirageFalseIdol\");\nconst owner = canvas.tokens.get(state?.ownerTokenId);\nconst entering = token?.object ?? token;\nif (!api || !state || !owner?.actor || !entering?.actor) return;\nconst flags = { rebakedMirageFalseIdolTemplate: template.id };\nif (!api.isHostile(owner, entering)) {\n  await api.applyEffectsToTokens({\n    tokens: [entering], effectNames: [\"cover_soft\"],\n    note: \"Manifest False Idols: soft cover while inside the construct.\",\n    duration: { label: \"indefinite\" }, notify: false\n  }, flags);\n  return;\n}\nawait template.delete();\nconst saves = await api.executeSaveVsEffect([entering], {\n  stat: \"SYSTEMS\", title: \"Manifest False Idols\", origin: owner,\n  cardDescription: \"Failure: take tier Heat and become Jammed until the end of your next turn.\"\n});\nif (!saves?.[0]?.result?.completed || saves[0].passed) return;\nawait api.executeDamageRoll(owner, [entering],\n  String(api.tierValue(owner, [2, 3, 4])), \"Heat\", \"Manifest False Idols\");\nawait api.applyEffectsToTokens({\n  tokens: [entering], effectNames: [\"jammed\"],\n  note: \"Manifest False Idols\",\n  duration: api.untilEndOfTurn(entering, 1)\n}, { rebakedMirageFalseIdolHit: state.idolId });";
  const leaveCode = "const api = game.modules.get(\"lancer-automations\")?.api;\nconst leaving = token?.object ?? token;\nif (!api || !leaving?.actor) return;\nawait api.removeEffectsByNameFromTokens({\n  tokens: [leaving], effectNames: [\"cover_soft\"],\n  extraFlags: { rebakedMirageFalseIdolTemplate: template.id },\n  notify: false\n});";
  const deleteCode = "const api = game.modules.get(\"lancer-automations\")?.api;\nif (!api) return;\nawait api.removeEffectsByNameFromTokens({\n  tokens: canvas.tokens.placeables, effectNames: [\"cover_soft\"],\n  extraFlags: { rebakedMirageFalseIdolTemplate: template.id },\n  notify: false\n});";
  for (const zone of next) await zone.update({
    "flags.lancer-automations.rebakedMirageFalseIdol": {
      idolId: foundry.utils.randomID(), ownerActorUuid: token.actor.uuid,
      ownerTokenId: token.id, itemId: item.id
    },
    "flags.templatemacro.actions": [
      hook("whenEntered", enterCode), hook("whenLeft", leaveCode),
      hook("whenDeleted", deleteCode)
    ]
  });
  for (const prior of owned())
    if (!next.some(zone => zone.id === prior.id)) await prior.delete();
  await api.setItemResource(item, false);
  return true;
}

