  if (type === "onDamage")
    return data.triggeringToken?.id === token.id
      && data.weapon?.system?.lid === "npc-rebake_npcf_combat_shotgun_sentinel"
      && !!data.target?.actor
      && (data.damages ?? []).some(value => Number(value) > 0);
