reactions.activationCode:
async function activation(type, data, token, item, name, api) {
  const markName = "Sentinel's Mark";
  const flagKey = "rebakedSentinelMarkSourceId";
  if (type === "onTurnStart") {
    await api.clearMarks(token, markName, { flagKey });
    return;
  }
  if (type === "onDamage") {
    const target = data.target;
    const hpBefore = Number(target.actor.system?.hp?.value ?? 0);
    const overshieldBefore = Number(target.actor.system?.overshield?.value ?? 0);
    api.afterFlow(data, async () => {
      if (!target?.actor || !canvas.tokens.get(target.id)) return;
      const hpAfter = Number(target.actor.system?.hp?.value ?? 0);
      const overshieldAfter = Number(target.actor.system?.overshield?.value ?? 0);
      if (hpAfter >= hpBefore && overshieldAfter >= overshieldBefore) return;
      await api.applyMark(token, [target], {
        effect: { name: markName, icon: item.img, isCustom: true },
        note: "Tagged Sentinel Overwatch attacks gain +1 Accuracy; clears at the start of the Sentinel's turn.",
        duration: { label: "indefinite" }, flagKey
      });
    });
    return;
  }
  const targets = [
    ...(data.targets ?? []),
    ...(data.flowState?.data?.acc_diff?.targets ?? []),
    ...(game.user?.targets ?? [])
  ].map(entry => entry?.target ?? entry?.token ?? entry?.object ?? entry)
    .filter(target => target?.actor);
  const markedIds = [...new Set(targets
    .filter(target => api.findEffectsOnToken(target, markName, {
      extraFlags: { rebakedSentinelMarkSourceId: token.id }
    }).length > 0)
    .map(target => target.id))];
  if (!markedIds.length) return;
  await api.injectBonusToFlowState(data.flowState, {
    id: "rebaked-sentinel-marker-shells-" + item.id,
    name: "Marker Shells", type: "accuracy", val: 1,
    applyTo: markedIds, rollTypes: ["attack"]
  });
  ui.notifications.info("Marker Shells: marked targets also ignore Invisible against this Overwatch attack; GM should disregard the Invisible roll if shown.");
}

