async function activation(type, data, token, item, name, api) {
  const targets = [...new Set((data.targets ?? [])
    .map(hit => hit?.target).filter(target => target?.actor
      && api.isHostile(token, target)))];
  for (const target of targets) {
    const ally = (await api.chooseToken(token, {
      title: "METAFOLD SHOVE — SWAP ALLY", count: 1,
      includeSelf: true, soft: false,
      filter: candidate => candidate.id !== target.id
        && api.isFriendly(token, candidate)
        && api.hasLineOfSight(token, candidate)
        && api.getMinGridDistance(target, candidate) <= 5
        && api.hasStatus(target, "flying") === api.hasStatus(candidate, "flying"),
      description: "GM: choose an ally in Mirage line of sight within Range 5 of "
        + target.name + ". Both must either be flying or not flying."
    }))?.[0];
    if (!ally?.actor || !api.isFriendly(token, ally)
      || !api.hasLineOfSight(token, ally)
      || api.getMinGridDistance(target, ally) > 5
      || api.hasStatus(target, "flying") !== api.hasStatus(ally, "flying"))
      continue;
    const a = { x: target.document.x, y: target.document.y,
      elevation: target.document.elevation };
    const b = { x: ally.document.x, y: ally.document.y,
      elevation: ally.document.elevation };
    await canvas.scene.updateEmbeddedDocuments("Token", [
      { _id: target.id, ...b }, { _id: ally.id, ...a }
    ], { teleport: true, isDrag: true,
      lancerFreeMovement: true, IgnorePreMove: true });
  }
}

async function activation(triggerType, data, token, item, name, api) {
