async function activation(triggerType, data, token, item, name, api) {
    const key = "rebakedAceMissileSwarmLockOn";
    if (triggerType === "onAttack") {
      const targetsFromAttack = data => data.targets ?? [];
      const ids = targetsFromAttack(data)
        .filter(target => api.hasStatus(target, "lockon"))
        .map(target => target.id);
      api.setFlowFlag(data, key, [...new Set(ids)]);
      return;
    }
    const lockOnIds = new Set(api.getFlowFlag(data, key) ?? []);
    const hitResults = data.flowState?.data?.hit_results ?? [];
    const attackResults = data.flowState?.data?.attack_results ?? [];
    for (const entry of data.targets ?? []) {
      const target = entry?.target;
      if (!target) continue;
      if (api.isFriendly(token, target)) {
        for (let index = 0; index < hitResults.length; index++) {
          if (hitResults[index]?.target?.id !== target.id) continue;
          hitResults[index].hit = false;
          hitResults[index].miss = true;
          hitResults[index].crit = false;
          if (attackResults[index]) {
            attackResults[index].hit = false;
            attackResults[index].miss = true;
            attackResults[index].crit = false;
          }
        }
        continue;
      }
      if (!lockOnIds.has(target.id)) continue;
      await api.injectBonusToFlowState(data.flowState, {
        name: "Missile Swarm — Lock On", type: "damage", damageMode: "add",
        damage: [{ val: String(api.tierValue(token, [3, 4, 5])), type: "Explosive" }],
        applyTo: [target.id], rollTypes: ["damage"]
      });
    }
  }

