      name: "Printed Cube — " + token.name,
      title: "MOBILE PRINTER — SIZE 2 CUBE",
      description: "GM: place a Size 2 hard-cover cube in a free area within Range 3."
    });
    const cube = (Array.isArray(placed) ? placed : [placed])
      .find(result => result?.documentName === "Token" || result?.document?.documentName === "Token");
    if (!cube) return false;
    const placedCube = canvas.tokens.get(cube.id);
    if (placedCube && !api.hasStatus(placedCube, "bulwark"))
      await api.applyEffectsToTokens({
        tokens: [placedCube], effectNames: ["bulwark"],
        duration: { label: "indefinite" }, notify: false
      });
    const cubeDoc = cube.document ?? cube;
    const old = canvas.tokens.placeables.filter(other =>
      other.id !== cube.id
      && api.getLAFlag(other.document, "rebakedPrintedCubeOwner") === token.actor.uuid
      && api.getLAFlag(other.document, "rebakedPrintedCubeMode") === "mobile");
    await api.setLAFlag(cubeDoc, "rebakedPrintedCubeOwner",
      token.actor.uuid);
    await api.setLAFlag(cubeDoc, "rebakedPrintedCubeMode", "mobile");
    for (const previous of old) await previous.document.delete();

      if (!game.modules.get("grid-aware-auras")?.active) {
        ui.notifications.error("Spike Barrier: Grid-Aware Auras is not active.");
      } else {
        try {
          const auraName = "Spike Barrier — " + token.id;
          await api.setLAFlag(cube.document ?? cube,
            "rebakedSpikeBarrierOwnerTokenId", token.id);
          await api.ensureAura(cube, {
            name: auraName, radius: 1, innerRadius: 0,
            fillColor: "#9f3030", lineColor: "#ff7070",
            fillOpacity: 0.22, lineOpacity: 0.9,
            ownerVisibility: { default: true },
            nonOwnerVisibility: { default: true },
            macros: [{
              mode: "ENTER", targetTokens: "ALL",
              actionType: "code", code: "const la = game.modules.get(\"lancer-automations\")?.api;\nif (!la || game.user.id !== la.getActiveGMId()\n  || options?.isPreview || options?.isInit || !game.combat\n  || !token?.actor || !parent?.document || token.id === parent.id) return;\nconst owner = canvas.tokens.get(la.getLAFlag(parent.document,\n  \"rebakedSpikeBarrierOwnerTokenId\"));\nif (!owner?.actor || token.id === owner.id) return;\nconst key = game.combat.id + \":\" + game.combat.round;\nconst hits = { ...(la.getLAFlag(parent.document,\n  \"rebakedSpikeBarrierHits\") ?? {}) };\nif (hits[token.id] === key) return;\nhits[token.id] = key;\nawait la.setLAFlag(parent.document, \"rebakedSpikeBarrierHits\", hits);\nawait la.executeDamageRoll(owner, [token],\n  String(la.tierValue(owner, [2, 3, 4])), \"Kinetic\", \"Spike Barrier\", { ap: true });\nconst saves = await la.executeSaveVsEffect([token], {\n  stat: \"AGILITY\", title: \"Spike Barrier\", origin: owner,\n  cardDescription: \"Failure: lose all remaining voluntary movement this turn.\"\n});\nif (saves?.[0]?.result?.completed && !saves[0].passed)\n  await la.applyEffectsToTokens({\n    tokens: [token],\n    effectNames: [{ name: \"Spike Barrier — Movement Spent\",\n      icon: \"icons/svg/spikes.svg\", isCustom: true }],\n    note: \"No more voluntary movement this turn.\",\n    duration: la.untilEndOfTurn(token), notify: false\n  }, { rebakedSpikeBarrierOwner: owner.id });"
            }]
          });
          if (!api.findAura(cube, auraName))
            ui.notifications.error("Spike Barrier: aura creation returned without a visible aura. Check the GM console.");
          else ui.notifications.info("Spike Barrier aura attached to " + cube.name + ".");
        } catch (error) {
          console.error("Spike Barrier aura creation failed", error);
          ui.notifications.error("Spike Barrier aura creation failed; see GM console.");
        }
      }

    return true;
  }

