async function onMessage(type, data, token, item, name, api) {
  if (!game.user.isGM) return false;
  const ownerUuid = token.actor?.uuid;
  const moved = new Set();
  const turrets = () => canvas.tokens.placeables.filter(other =>
    other.actor?.type === "deployable"
    && api.getLAFlag(other.document, "ownerActorUuid") === ownerUuid
    && !moved.has(other.id));
  for (let index = 0; index < 2; index++) {
    if (!turrets().length) break;
    const choice = await api.askCard({
      title: "MOBILE TURRETS", item, originToken: token, owner: token,
      description: "Move " + (index === 0 ? "a" : "one more")
        + " Deployable Turret up to 3 spaces?",
      yesText: "Choose Turret", noText: "Done"
    });
    if (!choice?.confirmed) break;
    const turret = (await api.chooseToken(token, {
      title: "MOBILE TURRETS — SELECT TURRET",
      count: 1, soft: true, includeSelf: false,
      filter: other => turrets().some(owned => owned.id === other.id),
      description: "GM: select one of this Engineer's Deployable Turrets."
    }))?.[0];
    if (!turret || !turrets().some(owned => owned.id === turret.id)) break;
    moved.add(turret.id);
    await api.moveTokenRuler(turret, {
      range: 3, cost: 0, free: true, action: "walk", urgent: true,
      title: "MOBILE TURRETS — MOVE 3",
      description: "GM: move the chosen Deployable Turret up to 3 spaces."
    });
  }
  return moved.size > 0;
}

