const mover = triggerData.triggeringToken ?? triggerData.token;
if (!mover)
    return false;

const targetId = api.getActorFlags(reactorToken.actor, "suppressTargetId");
if (!targetId || mover.id !== targetId)
    return false;

if (!api.hasLineOfSight(reactorToken, mover))
    return false;

const suppressed = api.findEffectsOnToken(
    mover,
    "Suppress",
    { extraFlags: { suppressSourceId: reactorToken.id } }
).length > 0;
if (!suppressed)
    return false;

const round = game.combat?.round ?? 0;
if (round > 0) {
    const used = api.getActorFlags(
        reactorToken.actor,
        "moving_target_" + item.id + "_round_" + round
    ) ?? [];
    if (Array.isArray(used) && used.includes("_self"))
        return false;
}

return true;

reactions.activationCode:
async function activation(triggerType, triggerData, reactorToken, item, activationName, api) {
    const mover = triggerData.triggeringToken ?? triggerData.token;
    if (!mover) return;

    const gmId = api.getActiveGMId();
    if (!gmId || !game.users.get(gmId)?.active) {
        ui.notifications.warn("Moving Target: No active GM is available to resolve the attack.");
        return;
    }

    const lmg = api.findItemByLid(
        reactorToken.actor,
        "npc-rebake_npcf_light_machine_gun_archer"
    );
    if (!lmg) {
        ui.notifications.warn("Moving Target: Light Machine Gun not found on " + reactorToken.name + ".");
        return;
    }

    const preConfirm = async () => {
        const ask = await api.askCard({
            title: "MOVING TARGET",
            icon: api.getActivationIcon("reaction"),
            description: "<b>" + mover.name + "</b> is starting to move while Suppressed by <b>" + reactorToken.name + "</b>. Fire the Light Machine Gun before they move?",
            item,
            originToken: reactorToken,
            relatedToken: mover,
            owner: reactorToken,
            yesText: "Fire",
            yesIcon: "fas fa-crosshairs",
            noText: "Let Them Move",
            noIcon: "fas fa-person-running"
        });

        if (!ask?.confirmed) return false;

        const activeGMId = api.getActiveGMId();
        if (!activeGMId || !game.users.get(activeGMId)?.active) {
            ui.notifications.warn("Moving Target: The GM is no longer available to resolve the attack.");
            return false;
        }

        await triggerData.sendMessageToReactor(
            { moverTokenId: mover.id },
            activeGMId,
            { wait: true }
        );
        return false;
    };

    triggerData.cancelTriggeredMove(
        "<b>" + reactorToken.name + "</b> may use Moving Target against <b>" + mover.name + "</b>.",
        false,
        api.getTokenOwnerUserId(mover),
        preConfirm,
        null,
        { item, originToken: reactorToken, relatedToken: mover }
    );
}

reactions.onMessage:
async function onMessage(triggerType, data, reactorToken, item, activationName, api) {
    if (!game.user.isGM) return;

    const mover = canvas.tokens.get(data?.moverTokenId);
    if (!mover) {
        ui.notifications.warn("Moving Target: The moving token is no longer on this scene.");
        return;
    }

    const lmg = api.findItemByLid(
        reactorToken.actor,
        "npc-rebake_npcf_light_machine_gun_archer"
    );
    if (!lmg) {
        ui.notifications.warn("Moving Target: Light Machine Gun not found on " + reactorToken.name + ".");
        return;
    }

    const available = await api.consumeOncePerRound(
        reactorToken,
        "moving_target_" + item.id
    );
    if (!available) {
        ui.notifications.warn("Moving Target has already been used this round.");
        return;
    }

    await api.setReaction(reactorToken, false);

    await api.removeEffectsByNameFromTokens({
        tokens: [mover],
        effectNames: ["Suppress", "impaired"],
        extraFlags: { suppressSourceId: reactorToken.id },
        notify: false
    });
    await api.removeActorFlags(reactorToken.actor, {
        suppressTargetId: true,
        suppressLosLost: true
    });

    const suppressItem = api.findItemByLid(
        reactorToken.actor,
        "npc-rebake_npcf_suppress_archer"
    );
    if (suppressItem && api.getActivatedItems(reactorToken).some(active => active.id === suppressItem.id))
        await api.endItemActivation(suppressItem, reactorToken);

    const hasSuperiorSentinel = reactorToken.actor.items.some(feature =>
        feature.system?.lid === "npc-rebake_npcf_superior_sentinel_archer"
    );
    const bonusId = "superior-sentinel-moving-target-" + item.id;
    if (hasSuperiorSentinel) {
        await api.addGlobalBonus(reactorToken.actor, {
            id: bonusId,
            name: "Superior Sentinel",
            type: "accuracy",
            val: 1,
            rollTypes: ["attack"],
            applyTo: [mover.id]
        }, { origin: reactorToken });
    }

    try {
        await api.attackWith(lmg, [mover]);
    }
    catch (error) {
        console.error("Moving Target: Light Machine Gun attack failed.", error);
        ui.notifications.error("Moving Target: the Light Machine Gun attack could not be completed.");
    }
    finally {
        if (hasSuperiorSentinel)
            await api.removeGlobalBonus(reactorToken.actor, bonus => bonus.id === bonusId);
    }
}

