async function onMessage(type, data, token, item, name, api) {
  if (!game.user.isGM) return null;
  const mover = canvas.tokens.get(data.moverId);
  if (!mover?.actor || !api.isHostile(token, mover)
    || api.getMinGridDistance(token, mover) > 20
    || !api.hasLineOfSight(token, mover)) return null;
  const markName = "Sniper's Mark";
  const marked = api.findEffectsOnToken(mover, markName, {
    extraFlags: { sniperSourceId: token.id }
  }).length > 0;
  const answer = await api.askCard({
    title: "MOVING TARGET", item, originToken: token,
    relatedToken: mover, owner: token,
    description: marked
      ? mover.name + " is moving with this Sniper's Mark. Fire the Anti-Materiel Rifle before movement continues?"
      : mover.name + " is moving in Range 20 and line of sight. Force them to choose between stopping Prone or taking Sniper's Mark?",
    yesText: marked ? "Fire Now" : "Use Moving Target",
    noText: "Decline"
  });
  if (!answer?.confirmed || !api.hasReactionAvailable(token)) return null;
  if (marked) {
    const rifle = api.findItemByLid(token.actor,
      "npc-rebake_npcf_anti_materiel_rifle_sniper");
    if (!rifle) {
      ui.notifications.warn("Moving Target: Anti-Materiel Rifle not found.");
      return null;
    }
    if (!await api.consumeOncePerRound(token,
      "rebaked_sniper_moving_target_" + item.id)) return null;
    await api.setReaction(token, false);
    await api.beginWeaponAttackFlow(rifle, { targets: [mover] }, {
      sniperMovingTarget: true
    });
    return "attack";
  }
  const choice = await api.startChoiceCard({
    title: "MOVING TARGET — CHOOSE CONSEQUENCE",
    item, originToken: token, relatedToken: mover,
    userIdControl: api.getTokenOwnerUserId(mover) ?? api.getActiveGMId(),
    mode: "or",
    description: mover.name + " must choose one: immediately stop, give up remaining movement, and fall Prone; or gain Sniper's Mark and continue moving.",
    choices: [
      { text: "Stop and Fall Prone", icon: "fas fa-person-falling" },
      { text: "Take Sniper's Mark", icon: "fas fa-crosshairs" }
    ]
  });
  if (choice?.choiceIdx !== 0 && choice?.choiceIdx !== 1) return null;
  if (!await api.consumeOncePerRound(token,
    "rebaked_sniper_moving_target_" + item.id)) return null;
  await api.setReaction(token, false);
  if (choice.choiceIdx === 0) {
    await api.applyEffectsToTokens({
      tokens: [mover], effectNames: ["prone"], note: "Moving Target"
    }, { rebakedSniperMovingTarget: item.id });
    return "prone";
  }
  await api.clearMarks(token, markName, { flagKey: "sniperSourceId" });
  await api.applyMark(token, [mover], {
    effect: { name: markName, icon: item.img, isCustom: true },
    note: "Ignored while Prone or benefiting from Hard or Soft Cover.",
    duration: { label: "indefinite" }, flagKey: "sniperSourceId",
    extraOptions: { sniperSourceName: token.name }
  });
  return "mark";
}

