function evaluate(type, data, token, item, name, api) {
  const attacker = data.triggeringToken;
  if (!attacker?.actor || api.isFriendly(token, attacker)
    || !api.hasReactionAvailable(token)
    || !api.checkGate(token, "rebaked_mirage_multiplicity_" + item.id))
    return false;
  return (data.targets ?? []).some(entry => {
    const ally = entry?.target;
    return ally?.actor && ally.actor.type !== "deployable"
      && entry.hit !== false && entry.miss !== true
      && api.isFriendly(token, ally)
      && api.getMinGridDistance(token, ally)
        <= api.getSensorRange_WithBonus(token)
      && api.hasLineOfSight(token, ally);
  });
}

