async function activation(type, data, token, item, name, api) {
  const gmId = api.getActiveGMId();
  if (!gmId || !game.users.get(gmId)?.active) {
    ui.notifications.warn("Multiplicity requires an active GM.");
    return;
  }
  const eligible = [...new Set((data.targets ?? [])
    .filter(entry => entry?.target?.actor
      && entry.hit !== false && entry.miss !== true)
    .map(entry => entry.target)
    .filter(ally => ally.actor.type !== "deployable"
      && api.isFriendly(token, ally)
      && api.getMinGridDistance(token, ally)
        <= api.getSensorRange_WithBonus(token)
      && api.hasLineOfSight(token, ally))
    .map(ally => ally.id))];
  if (!eligible.length) return;
  const result = await data.sendMessageToReactor({
    phase: "save", attackerId: data.triggeringToken?.id,
    eligible
  }, gmId, { wait: true });
  if (!result?.targetId) return;
  if (result.failedSave) {
    await api.injectBonusToFlowState(data.flowState, {
      id: "rebaked-mirage-multiplicity-" + item.id,
      name: "Multiplicity — Resistance",
      type: "target_modifier", subtype: "half_damage",
      applyTo: [result.targetId], rollTypes: ["damage"]
    });
    return;
  }
  api.afterFlow(data, () => data.sendMessageToReactor({
    phase: "teleport", targetId: result.targetId
  }, gmId, { wait: true }));
}

reactions.onMessage:
async function onMessage(type, data, token, item, name, api) {
  if (!game.user.isGM) return null;
  if (data.phase === "teleport") {
    const target = canvas.tokens.get(data.targetId);
    if (!target?.actor) return null;
    await api.moveTokenRuler(target, {
      range: 5, cost: 0, free: true, action: "blink", urgent: true,
      title: "MULTIPLICITY — TELEPORT 5",
      description: "GM: teleport the defended ally up to 5 spaces."
    });
    await api.applyEffectsToTokens({
      tokens: [target], effectNames: ["cover_soft"],
      note: "Multiplicity", duration: api.untilEndOfTurn(target, 1)
    }, { rebakedMirageMultiplicity: item.id });
    return true;
  }
  const attacker = canvas.tokens.get(data.attackerId);
  const eligible = (data.eligible ?? []).map(id => canvas.tokens.get(id))
    .filter(ally => ally?.actor && api.isFriendly(token, ally)
      && api.getMinGridDistance(token, ally)
        <= api.getSensorRange_WithBonus(token)
      && api.hasLineOfSight(token, ally));
  if (!attacker?.actor || !eligible.length
    || !api.hasReactionAvailable(token)) return null;
  const answer = await api.askCard({
    title: "MULTIPLICITY", item, originToken: token,
    relatedToken: attacker, owner: token,
    description: "An ally was hit. Spend Mirage's Reaction? The attacker saves Systems; failure halves damage, success permits teleport 5 and Soft Cover.",
    yesText: "Use Multiplicity", noText: "Decline"
  });
  if (!answer?.confirmed) return null;
  const target = eligible.length === 1 ? eligible[0]
    : (await api.chooseToken(token, {
      title: "MULTIPLICITY — ALLY HIT", count: 1, soft: true,
      filter: other => eligible.some(ally => ally.id === other.id),
      description: "GM: choose one allied character hit by this attack."
    }))?.[0];
  if (!target || !eligible.some(ally => ally.id === target.id))
    return null;
  if (!await api.consumeOncePerRound(token,
    "rebaked_mirage_multiplicity_" + item.id)) return null;
  await api.setReaction(token, false);
  const saves = await api.executeSaveVsEffect([attacker], {
    stat: "SYSTEMS", title: "Multiplicity", origin: token,
    cardDescription: "Failure: target resists all damage from this attack. Success: normal damage, then Mirage teleports the target 5 and grants Soft Cover."
  });
  if (!saves?.[0]?.result?.completed) return null;
  return { targetId: target.id, failedSave: !saves[0].passed };
}

