async function activation(type, data, token, item, name, api) {
  const choice = await api.askCard({
    title: "NAPALM BOMB", item, originToken: token, owner: token,
    description: "Detonate a Blast 1 now, or place a persistent Blast 1 burning patch in a completely free area?",
    yesText: "Burning Patch", noText: "Detonate Now"
  });
  if (!choice) return;
  const persistent = choice.confirmed === true;
  const placed = await api.placeZone(token, {
    type: "Blast", size: 1, range: 5, count: 1, los: false,
    title: persistent ? "NAPALM BOMB — FREE PATCH" : "NAPALM BOMB — DETONATION",
    centerLabel: "NAPALM", fillColor: "#b94a22",
    borderColor: "#ffaf55",
    description: persistent
      ? "GM: place in a completely free Blast 1 area within Range 5."
      : "GM: place Blast 1 within Range 5; all characters inside make Agility saves."
  });
  const zone = placed?.[0]?.template;
  if (!zone) return;
  const targets = api.tokensInTemplate(zone).filter(target => target?.actor);
  if (persistent && targets.length) {
    await zone.delete();
    ui.notifications.warn("Napalm Bomb: the persistent patch must be placed in a completely free Blast 1 area. No charge was spent.");
    return;
  }
  const oldZones = canvas.scene.templates.filter(other =>
    other.id !== zone.id
    && other.getFlag("lancer-automations", "rebakedPyroNapalm")?.ownerTokenId === token.id);
  for (const old of oldZones) await old.delete();
  await api.setItemResource(item, false);
  if (!persistent) {
    try {
      for (const target of targets) {
        const saves = await api.executeSaveVsEffect([target], {
          stat: "AGILITY", title: "Napalm Bomb", origin: token,
          cardDescription: "Failure: take tier Burn and tier Heat."
        });
        if (!saves?.[0]?.result?.completed || saves[0].passed) continue;
        const amount = String(api.tierValue(token, [2, 3, 4]));
        await api.executeDamageRoll(token, [target], amount, "Burn", "Napalm Bomb");
        await api.executeDamageRoll(token, [target], amount, "Heat", "Napalm Bomb");
      }
    } finally { await zone.delete(); }
    return;
  }
  const hook = (trigger, code) => ({
    id: foundry.utils.randomID(), trigger,
    actionType: "code", targetFilter: "ALL", asGM: true,
    code, macroUuid: "", effectName: "", effectMode: "apply"
  });
  await zone.update({
    "flags.lancer-automations.rebakedPyroNapalm": {
      ownerTokenId: token.id, itemId: item.id
    },
    "flags.templatemacro.actions": [
      hook("whenTurnStart", "const api = game.modules.get(\"lancer-automations\")?.api;\nconst patch = template.getFlag(\"lancer-automations\", \"rebakedPyroNapalm\");\nconst owner = canvas.tokens.get(patch?.ownerTokenId);\nconst target = token?.object ?? token;\nif (!api || !owner || !target?.actor) return;\nconst saves = await api.executeSaveVsEffect([target], {\n  stat: \"AGILITY\", title: \"Napalm Bomb — Burning Patch\", origin: owner,\n  cardDescription: \"Failure: take tier Burn and tier Heat.\"\n});\nif (!saves?.[0]?.result?.completed || saves[0].passed) return;\nconst amount = String(api.tierValue(owner, [2, 3, 4]));\nawait api.executeDamageRoll(owner, [target], amount, \"Burn\", \"Napalm Bomb\");\nawait api.executeDamageRoll(owner, [target], amount, \"Heat\", \"Napalm Bomb\");"),
      hook("whenEntered", "const api = game.modules.get(\"lancer-automations\")?.api;\nconst target = token?.object ?? token;\nconst combat = game.combat;\nif (!api || !target?.actor || !combat) return;\nconst key = combat.id + \":\" + combat.round;\nconst used = { ...(template.getFlag(\"lancer-automations\", \"rebakedPyroNapalmEntered\") ?? {}) };\nif (used[target.id] === key) return;\nused[target.id] = key;\nawait template.setFlag(\"lancer-automations\", \"rebakedPyroNapalmEntered\", used);\nawait template.callMacro(\"whenTurnStart\", {\n  userId: game.user.id, gmId: api.getActiveGMId(),\n  tokenId: target.id,\n  coords: { previous: null, current: { x: template.x, y: template.y } }\n});")
    ]
  });
}

