    filter: other => api.isFriendly(token, other),
    description: "GM: choose an allied character in Sensors and line of sight."
  }))?.[0];
  if (!ally?.actor || !api.isFriendly(token, ally)
    || !api.hasLineOfSight(token, ally)) return false;
  if (!api.hasReactionAvailable(ally)) {
    ui.notifications.warn("Pathfinder: that ally has already spent its Reaction.");
    return false;
  }
  if (!await api.consumeOncePerRound(token,
    "rebaked_scout_pathfinder_" + item.id)) return false;
  const moved = await api.moveTokenRuler(ally, {
    range: Number(api.tokenSpeed(ally)) || 0,
    cost: 0, free: true, action: "walk", urgent: true,
    title: "PATHFINDER — BOOST",
    description: "GM: the ally may Boost up to Speed as a Reaction; adjudicate reactions and engagement normally."
  });
  if (moved) await api.setReaction(ally, false);
  return true;
}

reactions.evaluate:
function evaluate(type, data, token, item, name, api) {
  if (type === "onActivation")
    return data.triggeringToken?.id === token.id && data.item?.id === item.id;
  const targetId = api.getActorFlags(token.actor, "rebakedGoliathPinnedTargetId");
  if (!targetId) return false;
  if (type === "onDamage")
    return data.triggeringToken?.id === targetId && data.target?.id === token.id
      && (data.damages ?? []).some(value => Number(value) > 0);
  if (type === "onStatusApplied")
    return data.triggeringToken?.id === token.id
      && String(data.statusId).toLowerCase() === "stunned";
  if (type === "onExitCombat")
    return data.triggeringToken?.id === token.id || !game.combat;
  const removed = data.triggeringToken ?? data.token ?? data.tokenDocument;
  return removed?.id === token.id || removed?.id === targetId
    || data.tokenId === targetId;
}

