async function activation(type, data, token, item, name, api) {
  if (type !== "onActivation") {
    const gmId = api.getActiveGMId();
    if (gmId && game.users.get(gmId)?.active)
      await data.sendMessageToReactor({ clearPin: true }, gmId, { wait: true });
    return;
  }
  const key = "rebakedGoliathPinnedTargetId";
  const flags = { rebakedGoliathPin: item.id, sourceTokenId: token.id };
  const clear = async () => {
    const prior = canvas.tokens.get(api.getActorFlags(token.actor, key));
    if (prior) await api.removeEffectsByNameFromTokens({
      tokens: [prior], effectNames: ["immobilized", "impaired"],
      extraFlags: flags, notify: false
    });
    await api.removeEffectsByNameFromTokens({
      tokens: [token], effectNames: ["immobilized"],
      extraFlags: flags, notify: false
    });
    await api.removeActorFlags(token.actor, { [key]: true });
  };
  const target = (await api.chooseToken(token, {
    title: "PIN — TARGET", count: 1, range: 2,
    includeSelf: false, soft: false,
    description: "GM: choose a character within Range 2."
  }))?.[0];
  if (!target || api.getMinGridDistance(token, target) > 2) return;
  await clear();
  await api.applyEffectsToTokens({
    tokens: [target], effectNames: ["immobilized", "impaired"],
    note: "Pin: ends when the target damages the Goliath, or the Goliath is Stunned/destroyed or pins someone else.",
    duration: { label: "indefinite" }
  }, flags);
  await api.applyEffectsToTokens({
    tokens: [token], effectNames: ["immobilized"],
    note: "Pin", duration: { label: "indefinite" }
