async function onInit(reactorToken, item, api) {
    if (!reactorToken?.actor || !item) return;
    await api.ensureLinkedBonus({
      items: [item],
      bonusData: {
        id: "cataphract-point-defense-resistance-v2",
        name: "Point-Defense Shield",
        type: "resistance",
        damageTypes: ["all"], rollTypes: ["damage"],
        condition: (state, actor, data, context) => {
          const api = game.modules.get("lancer-automations")?.api;
          const defender = canvas.tokens.get(context?.ownerTokenId);
          const attacker = state?.actor?.token?.object
            ?? state?.actor?.getActiveTokens?.()?.[0];
          if (!api || !defender || !attacker || !api.isHostile(defender, attacker)) return false;
          const hostiles = canvas.tokens.placeables.filter(other =>
            other.id !== defender.id && other.actor && api.isHostile(defender, other)
          );
          const distances = hostiles.map(other => ({
            id: other.id, distance: api.getMinGridDistance(defender, other)
          }));
          const nearest = Math.min(...distances.map(entry => entry.distance));
          return distances.filter(entry => entry.distance === nearest).length === 1
            && distances.some(entry => entry.id === attacker.id && entry.distance === nearest);
        }
      },
      addOptions: { duration: "constant" }
    });
  }

