        return;
      }
      api.setFlowFlag(data, flag, choice.choiceIdx === 0 ? "ranged" : "melee");
      return;
    }
    const mode = api.getFlowFlag(data, flag);
    const hits = (data.targets ?? []).filter(entry => entry.target);
    if (mode !== "melee" && mode !== "ranged") {
      ui.notifications.warn("Ram Cannon: firing mode was not recorded; resolve its on-hit effect manually.");
