reactions.activationCode:
async function activation(type, data, token, item, name, api) {
  if (type === "onPreDamage") {
    const bonusId = "rebaked-operator-raptor-crit-" + item.id;
    await api.addGlobalBonus(token.actor, {
      id: bonusId, name: "Raptor Plasma Rifle — Critical Burn",
      type: "damage", damageMode: "change_type", damageScope: "base",
      damage: [{ from: "Energy", to: "Burn" }],
      itemId: item.id, rollTypes: ["damage"]
    }, { origin: token, duration: "indefinite" });
    if (!api.afterFlow(data, () => api.removeGlobalBonus(token.actor, bonusId)))
      await api.removeGlobalBonus(token.actor, bonusId);
    return;
  }
  const state = data.flowState?.data;
  const targetId = data.target?.id;
  if (!state || !targetId) return;
  const rows = (state.targets ?? []).filter(row =>
    row.target?.id === targetId && row.crit === true);
  if (!rows.length) return;
  for (const row of rows)
    for (const damage of row.damage ?? [])
      if (String(damage.type).toLowerCase() === "energy")
        damage.type = "Burn";
  for (let i = 0; i < (data.types ?? []).length; i++)
    if (String(data.types[i]).toLowerCase() === "energy")
      data.types[i] = "Burn";
  const hitRows = (state.targets ?? []).filter(row => row.hit || row.crit);
  if (hitRows.length && hitRows.every(row => row.crit)) {
    for (const result of [...(state.damage_results ?? []),
      ...(state.crit_damage_results ?? [])])
      if (String(result.d_type).toLowerCase() === "energy")
        result.d_type = "Burn";
    for (const damage of state.damage ?? [])
      if (String(damage.type).toLowerCase() === "energy")
        damage.type = "Burn";
  }
}

