async function onMessage(type, data, token, item, name, api) {
  if (!game.user.isGM) return false;
  const attacker = canvas.tokens.get(data.attackerId);
  if (!attacker?.actor || !api.hasReactionAvailable(token)
    || !api.checkGate(token, "rebaked_ronin_rebound_" + item.id)) return false;
  const use = await api.askCard({
    title: "REBOUND", item, originToken: token,
    relatedToken: attacker, owner: token,
    description: "Spend the Ronin's Reaction to roll Rebound against " + attacker.name + "? On 4+, resist this attack and rebound it. On 3 or less, you may Boost towards them.",
    yesText: "Use Rebound", noText: "Decline"
  });
  if (!use?.confirmed) return false;
  if (!await api.consumeOncePerRound(token,
    "rebaked_ronin_rebound_" + item.id)) return false;
  await api.setReaction(token, false);
  const roll = await new Roll("1d6").evaluate();
  await roll.toMessage({
    speaker: ChatMessage.getSpeaker({ token: token.document }),
    flavor: "Rebound — 4+ resists and rebounds the attack"
  });
  if (Number(roll.total) >= 4) {
    const weapon = attacker.actor?.items?.get(data.weaponId);
    if (weapon) await api.attackWith(weapon, [attacker]);
    else ui.notifications.warn("Rebound: repeat the ranged attack against its attacker manually; weapon not found.");
    return true;
  }
  const answer = await api.askCard({
    title: "REBOUND — BOOST", item, originToken: token, owner: token,
    description: "Roll 3 or less: Boost towards " + attacker.name + "?",
    yesText: "Boost", noText: "Stay"
  });
  if (answer?.confirmed) await api.moveTokenRuler(token, {
    range: Number(token.actor?.system?.speed ?? 0),
    cost: 0, free: true, action: "forced", urgent: true,
    title: "REBOUND — BOOST",
    description: "GM: move Ronin towards the triggering attacker, up to its Speed."
  });
  return false;
}

