  const answer = await api.askCard({
    title: "REFLEXIVE BLOW", item, originToken: token,
    relatedToken: attacker, owner: token,
    description: attacker.name + " is attacking " + ward.name
      + ". Move up to Speed toward the ward and attack the hostile with Overwatch before their roll?",
    yesText: "Protect Ward", noText: "Decline"
  });
