  await api.moveTokenRuler(token, {
    range: Number(api.tokenSpeed(token)) || 0,
    cost: 0, free: true, action: "displace", urgent: true,
    title: "REFLEXIVE BLOW — TOWARD " + ward.name,
    description: "GM: move by the most direct route toward the ward, up to Speed. Ignore engagement and reactions; adjudicate terrain."
  });
  const distance = api.getMinGridDistance(token, attacker);
  const lids = [
    "npc-rebake_npcf_combat_shotgun_sentinel",
    "npc-rebake_npcf_retractable_sword_sentinel"
  ];
  const weapons = lids.map(lid => api.findItemByLid(token.actor, lid))
    .filter(weapon => !!weapon
      && distance <= Number(api.getMaxWeaponRanges_WithBonus(weapon)?.Threat ?? 0));
  if (!weapons.length) {
    ui.notifications.warn("Reflexive Blow: no equipped Overwatch weapon reaches the attacker from this position.");
    return true;
  }
  const weapon = weapons.length === 1 ? weapons[0] : await api.pickCard(weapons, {
    title: "REFLEXIVE BLOW — OVERWATCH WEAPON", item,
    originToken: token,
    description: "GM: choose a weapon whose Threat includes " + attacker.name + "."
  });
  if (!weapon) return true;
  await api.beginWeaponAttackFlow(weapon, { targets: [attacker] }, {
    overwatchAttack: true, reflexiveBlow: true
  });
  return true;
}

