    centerLabel: "NANITE CLOUD", fillColor: "#58a6a8",
    borderColor: "#b5f3ec",
    description: "GM: place the cloud within Range 5. It grants allies inside +1 Accuracy on checks and saves."
  });
  const zone = placed?.[0]?.template;
  if (!zone) return;
  for (const old of ownClouds()) await old.delete();
  const hook = (trigger, code) => ({
    id: foundry.utils.randomID(), trigger,
    actionType: "code", targetFilter: "ALL", asGM: true,
    code, macroUuid: "", effectName: "", effectMode: "apply"
  });
  await zone.update({
    "flags.lancer-automations.rebakedSupportRemoteCloud": {
      ownerTokenId: token.id, itemId: item.id
    },
    "flags.templatemacro.actions": [
      hook("whenEntered", "const api = game.modules.get(\"lancer-automations\")?.api;\nconst cloud = template.getFlag(\"lancer-automations\", \"rebakedSupportRemoteCloud\");\nconst owner = canvas.tokens.get(cloud?.ownerTokenId);\nconst target = token?.object ?? token;\nif (!api || !owner || !target?.actor || !api.isFriendly(owner, target)) return;\nawait api.addConstantBonus(target.actor, {\n  id: \"rebaked-support-remote-cloud-shared\",\n  name: \"Remote Cloud — Checks and Saves\",\n  type: \"accuracy\", val: 1, rollTypes: [\"check\"]\n});"),
      hook("whenLeft", "const api = game.modules.get(\"lancer-automations\")?.api;\nconst target = token?.object ?? token;\nif (!api || !target?.actor) return;\nconst stillCovered = canvas.scene.templates.some(other => {\n  if (other.id === template.id) return false;\n  const cloud = other.getFlag(\"lancer-automations\", \"rebakedSupportRemoteCloud\");\n  const owner = canvas.tokens.get(cloud?.ownerTokenId);\n  return owner && api.isFriendly(owner, target)\n    && api.tokensInTemplate(other).some(inside => inside.id === target.id);\n});\nif (!stillCovered) await api.removeConstantBonus(target.actor,\n  \"rebaked-support-remote-cloud-shared\");"),
      hook("whenDeleted", "const api = game.modules.get(\"lancer-automations\")?.api;\nif (!api) return;\nfor (const target of canvas.tokens.placeables) {\n  if (!target?.actor) continue;\n  const stillCovered = canvas.scene.templates.some(other => {\n    if (other.id === template.id) return false;\n    const cloud = other.getFlag(\"lancer-automations\", \"rebakedSupportRemoteCloud\");\n    const owner = canvas.tokens.get(cloud?.ownerTokenId);\n    return owner && api.isFriendly(owner, target)\n      && api.tokensInTemplate(other).some(inside => inside.id === target.id);\n  });\n  if (!stillCovered) await api.removeConstantBonus(target.actor,\n    \"rebaked-support-remote-cloud-shared\");\n}")
    ]
  });
  for (const affected of api.tokensInTemplate(zone)) {
    await zone.callMacro("whenEntered", {
      userId: game.user.id, gmId: api.getActiveGMId(),
      tokenId: affected.id,
      coords: { previous: null, current: { x: zone.x, y: zone.y } }
    });
  }
}

