async function activation(type, data, token, item, name, api) {
  const target = (await api.chooseToken(token, {
    title: "REMOTE REBOOT — ALLY", count: 1, range: 5,
    includeSelf: false, soft: false,
    filter: candidate => api.isFriendly(token, candidate),
    description: "GM: choose an allied character within Range 5."
  }))?.[0];
  if (!target || !api.isFriendly(token, target)
    || api.getMinGridDistance(token, target) > 5) return;
  const conditions = [
    { id: "impaired", label: "Impaired" },
    { id: "jammed", label: "Jammed" },
    { id: "stunned", label: "Stunned" },
    { id: "slow", label: "Slowed" }
  ];
  for (let count = 0; count < 2; count++) {
    const active = conditions.filter(effect => api.hasStatus(target, effect.id));
    if (!active.length) break;
    const chosen = await api.startChoiceCard({
      title: "REMOTE REBOOT — CLEAR CONDITION", item, originToken: token,
      relatedToken: target, owner: token, mode: "or",
      description: "Clear one condition from " + target.name + " (up to two total).",
      choices: active.map(effect => ({ text: effect.label, icon: "fas fa-wrench" }))
    });
    if (chosen?.choiceIdx == null) break;
    const effect = active[chosen.choiceIdx];
    if (effect) await api.removeEffectsByNameFromTokens({
      tokens: [target], effectNames: [effect.id]
    });
  }
  const followUp = await api.startChoiceCard({
    title: "REMOTE REBOOT — FOLLOW-UP", item, originToken: token,
    relatedToken: target, owner: token, mode: "or",
    description: "The ally may move up to their Speed or stand from Prone.",
    choices: [
      { text: "Move Speed", icon: "fas fa-person-running" },
      { text: "Stand from Prone", icon: "fas fa-person" },
      { text: "Neither", icon: "fas fa-times" }
    ]
  });
  if (followUp?.choiceIdx === 0) await api.moveTokenRuler(target, {
    range: Math.max(0, Number(target.actor?.system?.speed ?? 0)),
    cost: 0, free: true, action: "walk", urgent: true,
    title: "REMOTE REBOOT — MOVE",
    description: "GM: move the allied character up to their Speed. Normal engagement and reactions apply."
  });
  if (followUp?.choiceIdx === 1 && api.hasStatus(target, "prone"))
    await api.removeEffectsByNameFromTokens({
      tokens: [target], effectNames: ["prone"]
    });
}

