reactions.onMessage:
async function onMessage(type, data, token, item, name, api) {
  if (!game.user.isGM) return false;
  const ownerUuid = token.actor?.uuid;
  const turrets = canvas.tokens.placeables.filter(other =>
    other.actor?.type === "deployable"
    && api.getLAFlag(other.document, "ownerActorUuid") === ownerUuid);
  if (!turrets.length) {
    ui.notifications.warn("Repurpose: this Engineer has no Deployable Turret.");
    return false;
  }
  const allies = canvas.tokens.placeables.filter(other => other?.actor
    && other.actor.type !== "deployable"
    && api.isFriendly(token, other)
    && turrets.some(turret => api.getMinGridDistance(turret, other) <= 1));
  if (!allies.length) {
    ui.notifications.warn("Repurpose: no allied character is adjacent to a Deployable Turret.");
    return false;
  }
  const ally = (await api.chooseToken(token, {
    title: "REPURPOSE — CHOOSE ALLY", count: 1, soft: true,
    filter: other => allies.some(candidate => candidate.id === other.id),
    description: "GM: choose an allied character adjacent to one of this Engineer's turrets."
  }))?.[0];
  if (!ally || !allies.some(candidate => candidate.id === ally.id)) return false;
  const eligible = turrets.filter(turret =>
    api.getMinGridDistance(turret, ally) <= 1);
  const turret = eligible.length === 1 ? eligible[0]
    : (await api.chooseToken(token, {
      title: "REPURPOSE — CHOOSE TURRET", count: 1, soft: true,
      filter: other => eligible.some(candidate => candidate.id === other.id),
      description: "GM: choose the adjacent Deployable Turret to destroy."
    }))?.[0];
  if (!turret || !eligible.some(candidate => candidate.id === turret.id)) return false;
  const choice = await api.askCard({
    title: "REPURPOSE", item, originToken: token, relatedToken: ally,
    owner: token,
    description: "Destroy " + turret.name + " to give " + ally.name
      + " tier Overshield, or +1 Accuracy on attacks, checks, and saves until the end of their next turn?",
    yesText: "Gain Overshield", noText: "Gain +1 Accuracy"
  });
  if (!choice) return false;
  if (!await api.consumeOncePerRound(token,
    "rebaked_engineer_repurpose_" + item.id)) return false;
  if (choice.confirmed) {
    const amount = Number(api.tierValue(token, [3, 4, 5]));
    const current = Number(ally.actor.system?.overshield?.value ?? 0);
    if (amount > current)
      await ally.actor.update({ "system.overshield.value": amount });
  } else {
    await api.addGlobalBonus(ally.actor, {
      id: "rebaked-engineer-repurpose-" + item.id + "-" + token.id,
      name: "Repurpose", type: "accuracy", val: 1,
      rollTypes: ["attack", "tech_attack", "check"]
    }, { duration: "end", durationTurns: 1,
      origin: ally, refresh: true });
  }
  await turret.document.delete();
  return true;
}

