reactions.activationCode:
async function activation(type, data, token, item, name, api) {
  const target = (await api.chooseToken(token, {
    title: "SEALANT GUN — TARGET", count: 1,
    range: 5, includeSelf: true, soft: false,
    filter: candidate => api.hasLineOfSight(token, candidate),
    description: "GM: choose an allied or hostile character in line of sight and Range 5."
  }))?.[0];
  if (!target?.actor || api.getMinGridDistance(token, target) > 5
    || !api.hasLineOfSight(token, target)) return;
  if (target.id === token.id || api.isFriendly(token, target)) {
    const burn = Number(target.actor.system?.burn ?? 0);
    if (burn > 0) await api.updateTokenSystem(target, { "system.burn": 0 });
    await api.applyEffectsToTokens({
      tokens: [target], effectNames: ["slow"], note: "Sealant Gun",
      duration: api.untilEndOfTurn(target, 1)
    }, { rebakedSupportSealantGun: item.id });
    return;
  }
  if (!api.isHostile(token, target)) return;
  const saves = await api.executeSaveVsEffect([target], {
    stat: "AGILITY", title: "Sealant Gun", origin: token,
    cardDescription: "On failure, become Slowed until the end of your next turn. Whether the save succeeds or fails, Burst 1 around you becomes difficult terrain for the scene."
  });
  if (!saves?.[0]?.result?.completed) return;
  if (!saves[0].passed) await api.applyEffectsToTokens({
    tokens: [target], effectNames: ["slow"], note: "Sealant Gun",
    duration: api.untilEndOfTurn(target, 1)
  }, { rebakedSupportSealantGun: item.id });
  const placed = await api.placeZone(token, {
    type: "Burst", size: 1, count: 1,
    title: "SEALANT GUN — BURST 1",
    description: "GM: place Burst 1 around " + target.name
      + ". For Size 2 targets, choose the hex center that covers the intended area.",
    centerLabel: "SEALANT", fillColor: "#677f77",
    borderColor: "#b0d2bb",
    difficultTerrain: { movementPenalty: 1, isFlatPenalty: true }
  });
  const zone = placed?.[0]?.template;
  if (zone) await zone.setFlag("lancer-automations",
    "rebakedSupportSealant", {
      ownerTokenId: token.id, itemId: item.id, sceneId: canvas.scene?.id
    });
}

