async function activation(type, data, token, item, name, api) {
  const targets = await api.chooseToken(token, {
    title: "SEEKER VOLLEY — HOSTILES", count: -1, range: 15,
    includeSelf: false, soft: false,
    filter: candidate => api.isHostile(token, candidate),
    description: "GM: select every hostile character in line of sight and Range 15."
  });
  if (!targets?.length) return;
  const damage = String(api.tierValue(token, [4, 5, 6]));
  for (const target of targets) {
    if (!api.isHostile(token, target) || api.getMinGridDistance(token, target) > 15) continue;
    const saves = await api.executeSaveVsEffect([target], {
      stat: "SYSTEMS", title: "Seeker Volley", origin: token,
      cardDescription: "On failure, gain Lock On and take full Explosive damage; on success, take half damage only."
    });
    if (!saves?.[0]?.result?.completed) continue;
    if (!saves[0].passed) await api.applyEffectsToTokens({
      tokens: [target], effectNames: ["lockon"], note: "Seeker Volley"
    });
    await api.executeDamageRoll(token, [target], damage,
      "Explosive", "Seeker Volley", { half_damage: saves[0].passed });
  }
}

