reactions.onMessage:
async function onMessage(type, data, token, item, name, api) {
    if (!game.user.isGM) return false;
    const placed = await api.placeZone(token, {
      type: "Cone", size: 5, range: 0, count: 1,
      title: "SEISMIC DESTROYER — CONE 5",
      description: "GM: aim a Cone 5 from the Demolisher."
    });
    const zone = placed?.[0]?.template;
    if (!zone) return false;
    try {
      await api.setItemResource(item, false);
      const affected = api.tokensInTemplate(zone).filter(target =>
        target?.actor && target.actor.type !== "deployable"
        && !api.hasStatus(target, "flying"));
      for (const target of affected) {
        const saves = await api.executeSaveVsEffect([target], {
          stat: "AGILITY", title: "Seismic Destroyer", origin: token,
          cardDescription: "Failure: knocked Prone. Flying characters are unaffected."
        });
        if (saves?.[0]?.result?.completed && !saves[0].passed)
          await api.applyEffectsToTokens({
            tokens: [target], effectNames: ["prone"],
            note: "Seismic Destroyer"
          });
      }
      const destroyed = await api.askCard({
        title: "SEISMIC DESTROYER — TERRAIN", item,
        originToken: token, owner: token,
        description: "GM: apply " + api.tierValue(token, [10, 20, 30])
          + " AP Kinetic damage to every object and terrain piece in the Cone. Was any destroyed? If so, every affected non-flying character takes extra tier Kinetic damage.",
        yesText: "Terrain Destroyed", noText: "None Destroyed"
      });
      if (destroyed?.confirmed && affected.length)
        await api.executeDamageRoll(token, affected,
          String(api.tierValue(token, [4, 6, 8])),
          "Kinetic", "Seismic Destroyer — Collapse");
      return true;
    } finally {
      await zone.delete();
    }
  }

