async function onMessage(type, data, token, item, name, api) {
    if (!game.user.isGM) return false;
    const cubes = canvas.tokens.placeables.filter(other =>
      api.getLAFlag(other.document, "rebakedPrintedCubeOwner")
        === token.actor?.uuid
      && ["mobile", "extruding"].includes(
        api.getLAFlag(other.document, "rebakedPrintedCubeMode")));
    if (!cubes.length) {
      ui.notifications.warn("Seismic Repulsor: no printed cube remains.");
      return false;
    }
    const cube = cubes.length === 1 ? cubes[0]
      : (await api.chooseToken(token, {
        title: "SEISMIC REPULSOR — CUBE", count: 1, soft: true,
        filter: other => cubes.some(source => source.id === other.id),
        description: "GM: choose one of this Barricade's printed cubes."
      }))?.[0];
    if (!cube || !cubes.some(source => source.id === cube.id)) return false;
    await api.setItemResource(item, false);
    const affected = canvas.tokens.placeables.filter(other => other?.actor
      && other.id !== cube.id
      && other.actor.type !== "deployable"
      && !api.hasStatus(other, "flying")
      && api.getMinGridDistance(cube, other) <= 3);
    for (const target of affected) {
      const saves = await api.executeSaveVsEffect([target], {
        stat: "HULL", title: "Seismic Repulsor", origin: token,
        cardDescription: "Failure: push 3 spaces directly away from the cube; hostile characters also fall Prone."
      });
      if (!saves?.[0]?.result?.completed || saves[0].passed) continue;
      await api.moveTokenRuler(target, {
        range: 3, cost: 0, free: true, action: "forced", urgent: true,
        awayFrom: cube,
        title: "SEISMIC REPULSOR — PUSH 3",
        description: "GM: move directly away from the selected cube, stopping at obstructions."
      });
      if (api.isHostile(token, target))
        await api.applyEffectsToTokens({
          tokens: [target], effectNames: ["prone"],
          note: "Seismic Repulsor"
        });
    }
    await cube.document.delete();
    return true;
  }

