async function onMessage(type, data, token, item, name, api) {
  if (!game.user.isGM || !data.selfErase) return false;
  const deniable = api.findItemByLid(token.actor,
    "npc-rebake_npcf_deniable_asset_operator");
  if (deniable && !deniable.system?.destroyed) {
    const answer = await api.askCard({
      title: "DENIABLE ASSET — FINAL TELEPORT",
      item: deniable, originToken: token, owner: token,
      description: "Teleport up to Speed as a Reaction before Self-Erasure detonates?",
      yesText: "Teleport", noText: "Detonate Here"
    });
    if (answer?.confirmed) await api.moveTokenRuler(token, {
      range: Number(token.actor?.system?.speed ?? 0),
      cost: 0, free: true, action: "blink", urgent: true,
      title: "DENIABLE ASSET — TELEPORT",
      description: "GM: teleport the destroyed Operator up to Speed before its explosion."
    });
  }
  const targets = canvas.tokens.placeables.filter(other =>
    other.id !== token.id && other.actor
      && api.getMinGridDistance(token, other) <= 1);
  const damage = String(api.tierValue(token,
    deniable && !deniable.system?.destroyed ? [6, 8, 10] : [4, 6, 8]));
  for (const target of targets) {
    const saves = await api.executeSaveVsEffect([target], {
      stat: "AGILITY", title: "Self-Erasure", origin: token,
      cardDescription: "Failure: full Energy damage and Blinded until the end of your next turn. Success: half damage only."
    });
    if (!saves?.[0]?.result?.completed) continue;
    await api.executeDamageRoll(token, [target], damage, "Energy",
      "Self-Erasure", { half_damage: saves[0].passed });
    if (!saves[0].passed) await api.applyEffectsToTokens({
      tokens: [target], effectNames: ["blinded"],
      note: "Self-Erasure: line of sight only to adjacent spaces.",
      duration: api.untilEndOfTurn(target, 1)
    }, { rebakedOperatorSelfErasure: item.id });
  }
  if (canvas.tokens.get(token.id)) await token.document.delete();
  return true;
}

