  }).length > 0;
}

reactions.activationCode:
async function activation(type, data, token, item, name, api) {
  const source = { rebakedScoutSensorLinkId: token.id, rebakedScoutSensorLinkItemId: item.id };
  if (type === "onInitAttack" || type === "onInitTechAttack") {
    await api.injectBonusToFlowState(data.flowState, {
      id: "rebaked-sensor-link-sight-" + item.id,
      name: "Sensor Link — Sight", type: "target_modifier",
      subtype: "no_invisible", rollTypes: ["attack", "tech_attack"]
    });
    return;
  }
  const clearLink = async () => {
    await api.removeEffectsByNameFromTokens({
      tokens: canvas.tokens.placeables, effectNames: ["Sensor Link"],
      extraFlags: source, notify: false
    });
    await api.removeEffectsByNameFromTokens({
      tokens: [token], effectNames: ["immobilized"],
      extraFlags: source, notify: false
    });
  };
  if (type === "onDestroyed") {
    await clearLink();
    return;
  }
  const ally = (await api.chooseToken(token, {
    title: "SENSOR LINK — ALLIED CHARACTER", count: 1,
    range: 3, includeSelf: false, soft: false,
    filter: other => api.isFriendly(token, other),
    description: "GM: choose an allied character within Range 3. They gain Sight until the end of the Scout's next turn."
  }))?.[0];
  if (!ally?.actor || !api.isFriendly(token, ally)
    || api.getMinGridDistance(token, ally) > 3) return;
  await clearLink();
  const duration = api.untilEndOfTurn(token, 1);
  await api.applyEffectsToTokens({
    tokens: [token], effectNames: ["immobilized"],
    note: "Sensor Link", duration, notify: false
  }, source);
  await api.applyEffectsToTokens({
    tokens: [ally],
    effectNames: [{ name: "Sensor Link", icon: item.img, isCustom: true }],
    note: "Sight: ignore Hidden and Invisible until the end of the Scout's next turn.",
    duration, notify: false
  }, source);
}

reactions.evaluate:
function evaluate(type, data, token, item, name, api) {
  if (data.triggeringToken?.id !== token.id
    || data.weapon?.system?.lid !== "npc-rebake_npcf_anti_materiel_rifle_sniper") return false;
  if (type === "onAttack") {
    const ids = new Set((data.targets ?? []).map(target => target?.id));
    const uuids = new Set((data.flowState?.data?.acc_diff?.targets ?? [])
      .map(entry => entry?.targetUuid));
    return canvas.tokens.placeables.some(other =>
      (ids.has(other.id) || uuids.has(other.document.uuid))
      && api.findEffectsOnToken(other, "Sniper's Mark", {
        extraFlags: { sniperSourceId: token.id }
      }).length > 0
      && !api.hasStatus(other, "prone", "cover_hard", "cover_soft"));
  }
  const choice = api.getFlowFlag(data, "rebakedSharpshooterChoice");
  return Number.isInteger(choice) && choice >= 0 && choice < 4;
}

reactions.activationCode:
async function activation(type, data, token, item, name, api) {
  const options = [
    { label: "Head — Hull save or adjacent sight only", stat: "HULL", effect: "Sharpshooter — Adjacent Sight Only" },
    { label: "Legs — Agility save or Immobilized", stat: "AGILITY", effect: "immobilized" },
    { label: "Hardpoints — Systems save or Jammed", stat: "SYSTEMS", effect: "jammed" },
    { label: "Body — Engineering save or Shredded", stat: "ENGINEERING", effect: "shredded" }
  ];
  if (type === "onAttack") {
    const chosen = await api.startChoiceCard({
      title: "SHARPSHOOTER — CALLED SHOT", item, originToken: token,
      owner: token, mode: "or", userIdControl: api.getActiveGMId(),
      description: "Choose a called shot before rolling against a character with this Sniper's Mark, or fire normally. The extra effect only applies on a hit.",
      choices: [...options.map(option => ({ text: option.label, icon: "fas fa-crosshairs" })),
        { text: "Fire normally", icon: "fas fa-arrow-right" }]
    });
    if (chosen?.choiceIdx >= 0 && chosen.choiceIdx < options.length)
      api.setFlowFlag(data, "rebakedSharpshooterChoice", chosen.choiceIdx);
    return;
  }
  const option = options[Number(api.getFlowFlag(data, "rebakedSharpshooterChoice"))];
  if (!option) return;
  const targets = [...new Set([
    ...(data.hitTokens ?? []),
    ...(data.targets ?? []).map(entry => entry?.target)
  ].filter(target => target?.actor))];
  for (const target of targets) {
    if (!api.findEffectsOnToken(target, "Sniper's Mark", {
      extraFlags: { sniperSourceId: token.id }
    }).length || api.hasStatus(target, "prone", "cover_hard", "cover_soft")) continue;
    const saves = await api.executeSaveVsEffect([target], {
      stat: option.stat, title: "Sharpshooter — " + option.label,
      origin: token,
      cardDescription: "Failure: " + option.effect + " until the end of the target's next turn."
    });
    if (!saves?.[0]?.result?.completed || saves[0].passed) continue;
    await api.applyEffectsToTokens({
      tokens: [target],
      effectNames: [option.effect === "Sharpshooter — Adjacent Sight Only"
        ? { name: option.effect, icon: item.img, isCustom: true }
        : option.effect],
      note: "Sharpshooter", duration: api.untilEndOfTurn(target, 1)
    }, { rebakedSharpshooterSource: item.id });
  }
}

