reactions.activationCode:
async function activation(triggerType, triggerData, reactorToken, item, activationName, api) {
    const markName = "Sniper's Mark";
    const fallProneAction = "Fall Prone (Sniper's Mark)";

    if (triggerType === "onActivation") {
        const chosen = await api.chooseToken(reactorToken, {
            count: 1,
            range: 20,
            filter: (target) => api.hasLineOfSight(reactorToken, target),
            filterWarning: "Target must be within Range 20 and line of sight.",
            title: "SNIPER'S MARK",
            description: "Choose a character to mark. Choosing the currently marked character removes the Mark."
        });

        if (!chosen?.length) return;

        const target = chosen[0];
        const wasMarked = api.findEffectsOnToken(target, markName, {
            extraFlags: { sniperSourceId: reactorToken.id }
        }).length > 0;

        await api.clearMarks(reactorToken, markName, {
            flagKey: "sniperSourceId"
        });

        if (wasMarked) {
            ui.notifications.info(`Sniper's Mark removed from ${target.name}.`);
            return;
        }

        await api.applyMark(reactorToken, [target], {
            effect: {
                name: markName,
                icon: item.img,
                isCustom: true
            },
            note: "Ignored while Prone or benefiting from Hard or Soft Cover.",
            duration: { label: "indefinite" },
            flagKey: "sniperSourceId",
            extraOptions: {
                sniperSourceName: reactorToken.name
            }
        });

        ui.notifications.info(`${target.name} gains the Sniper's Mark.`);
        return;
    }

    const markedToken = triggerData.triggeringToken;
    if (!markedToken?.actor) return;

    if (triggerType === "onStatusApplied") {
        await api.addExtraActions(markedToken.actor, {
            name: fallProneAction,
            activation: "Free",
            detail: "Drop Prone as a free action while you have the Sniper's Mark."
        });
        return;
    }

    const stillMarked = api.findEffectsOnToken(markedToken, markName, {
        excludeId: triggerData.effect?.id
    }).length > 0;

    if (!stillMarked) {
        await api.removeExtraActions(markedToken.actor, fallProneAction);
    }
}

