reactions.activationCode:
async function activation(type, data, token, item, name, api) {
  const pendingKey = "rebakedBastionStackUpPending";
  const usageKey = "rebakedBastionStackUpUsage";
  const roundKey = game.combat?.id + ":" + game.combat?.round;
  if (type === "onPreMove") {
    const used = api.getActorFlags(token.actor, usageKey) ?? {};
    const eligible = canvas.tokens.placeables.filter(other =>
      other.id !== token.id && other.actor
        && api.isFriendly(token, other)
        && api.getMinGridDistance(token, other, data.startPos, false) <= 1
        && Number(used[roundKey + ":" + other.id] ?? 0)
          < Number(other.actor.system?.speed ?? 0));
    if (!eligible.length) return;
    const gmId = api.getActiveGMId();
    await data.cancelTriggeredMove(
      "Stack Up: choose an ally adjacent to Bastion before it moves.",
      false, gmId,
      async () => {
        await api.removeActorFlags(token.actor, { [pendingKey]: true });
        const selected = await api.chooseToken(token, {
          title: "STACK UP — FOLLOWING ALLY",
          count: 1, selection: eligible,
          includeSelf: false, soft: false, urgent: true,
          filter: candidate => eligible.some(ally => ally.id === candidate.id),
          description: "GM: choose an ally adjacent at the start of this move. Cancel to move Bastion alone."
        });
        const ally = selected?.[0];
        if (ally && eligible.some(candidate => candidate.id === ally.id))
          await api.addActorFlags(token.actor, { [pendingKey]: {
            allyId: ally.id, combatId: game.combat?.id,
            round: game.combat?.round,
            fromX: data.startPos?.x, fromY: data.startPos?.y
          } });
        return false;
      }
    );
    return;
  }
  const pending = api.getActorFlags(token.actor, pendingKey);
  await api.removeActorFlags(token.actor, { [pendingKey]: true });
  if (!pending || pending.combatId !== game.combat?.id
    || pending.round !== game.combat?.round
    || pending.fromX !== data.startPos?.x
    || pending.fromY !== data.startPos?.y) return;
  const ally = canvas.tokens.get(pending.allyId);
  if (!ally?.actor) return;
  const used = { ...(api.getActorFlags(token.actor, usageKey) ?? {}) };
  const key = roundKey + ":" + ally.id;
  const remaining = Math.max(0,
    Number(ally.actor.system?.speed ?? 0) - Number(used[key] ?? 0));
  const allowance = Math.min(Number(data.distanceMoved ?? 0), remaining);
  if (allowance <= 0) return;
  const moved = await api.moveTokenRuler(ally, {
    range: allowance, cost: 0, free: true, action: "forced", urgent: true,
    title: "STACK UP — MIRROR BASTION",
    description: "GM: mirror Bastion's completed movement as closely as possible. This movement ignores engagement and reactions."
  });
  if (moved) {
    used[key] = Number(used[key] ?? 0) + allowance;
    await api.addActorFlags(token.actor, { [usageKey]: used });
  }
}

