reactions.activationCode:
async function activation(type, data, token, item, name, api) {
  const flagKey = "rebakedOperatorStrikeAndFade";
  if (type === "onTurnStart") {
    await api.addActorFlags(token.actor, {
      [flagKey]: { attacked: false, offenseGranted: false,
        defenseGranted: false, standardMode: null }
    });
    return;
  }
  const record = { attacked: false, offenseGranted: false,
    defenseGranted: false, standardMode: null,
    ...(api.getActorFlags(token.actor, flagKey) ?? {}) };
  if (type === "onAttack" || type === "onTechAttack") {
    if (!record.attacked) await api.addActorFlags(token.actor, {
      [flagKey]: { ...record, attacked: true }
    });
    return;
  }
  const standardMove = data.moveLeg?.start === "standard"
    || data.moveLeg?.end === "standard";
  if (!record.attacked) {
    if (record.offenseGranted
      || (standardMove && record.standardMode === "defense")) return;
    const rifle = api.findItemByLid(token.actor,
      "npc-rebake_npcf_raptor_plasma_rifle_operator");
    if (!rifle) return;
    await api.addGlobalBonus(token.actor, {
      id: "rebaked-operator-strike-offense-" + item.id,
      name: "Strike and Fade — Strike",
      type: "accuracy", val: 1,
      rollTypes: ["attack"], itemLids: [rifle.system.lid]
    }, { duration: "end", durationTurns: 0,
      origin: token, refresh: true });
    await api.addActorFlags(token.actor, {
      [flagKey]: { ...record, offenseGranted: true,
        standardMode: standardMove ? "offense" : record.standardMode }
    });
    return;
  }
  if (record.defenseGranted
    || (standardMove && record.standardMode === "offense")) return;
  await api.addGlobalBonus(token.actor, {
    id: "rebaked-operator-strike-defense-" + item.id,
    name: "Strike and Fade — Fade",
    type: "difficulty", val: 1,
    rollTypes: ["attack"], applyToTargetter: true
  }, { duration: "end", durationTurns: 1,
    origin: token, refresh: true });
  await api.addActorFlags(token.actor, {
    [flagKey]: { ...record, defenseGranted: true,
      standardMode: standardMove ? "defense" : record.standardMode }
  });
}

