    ui.notifications.warn("Superhot requires an active GM.");
    return;
  }
  const used = await data.sendMessageToReactor({
    attackerId: data.triggeringToken.id,
    weaponId: data.weapon?.id,
    attackType: data.attackType
  }, gmId, { wait: true });
  if (used !== true) return;
  const damageEntry = (data.flowState?.data?.targets ?? [])
    .find(entry => entry.target?.id === token.id);
  if (!damageEntry || damageEntry.half_damage) return;
  damageEntry.damage = (damageEntry.damage ?? []).map(part => ({
    ...part,
    amount: Math.ceil(Number(part.amount ?? part.val ?? 0) / 2)
  }));
  damageEntry.half_damage = true;
}

reactions.onMessage:
async function onMessage(type, data, token, item, name, api) {
  if (!game.user.isGM) return false;
  const attacker = canvas.tokens.get(data.attackerId);
  if (!attacker?.actor || !api.hasReactionAvailable(token)
    || !api.checkGate(token, "rebaked_pyro_superhot_" + item.id))
    return false;
  const answer = await api.askCard({
    title: "SUPERHOT", item, originToken: token,
    relatedToken: attacker, owner: token,
    description: "Spend the Pyro's Reaction and take 4 Heat to resist this attack's damage? If it is melee, the attacker must also pass an Engineering save or take tier Burn.",
    yesText: "Use Superhot", noText: "Decline"
  });
  if (!answer?.confirmed) return false;
  if (!await api.consumeOncePerRound(token,
    "rebaked_pyro_superhot_" + item.id)) return false;
  await api.setReaction(token, false);
  await api.executeDamageRoll(token, [token], "4", "Heat",
    "Superhot — Reactor Heat");
  const weapon = attacker.actor.items.get(data.weaponId);
  const kind = String((weapon ? api.getWeaponType(weapon) : null)
    ?? data.attackType ?? "").toLowerCase();
  if (kind !== "melee") return true;
  const saves = await api.executeSaveVsEffect([attacker], {
    stat: "ENGINEERING", title: "Superhot", origin: token,
    cardDescription: "Failure: take tier Burn from the Pyro's Superhot reaction."
  });
  if (saves?.[0]?.result?.completed && !saves[0].passed)
    await api.executeDamageRoll(token, [attacker],
      String(api.tierValue(token, [3, 4, 5])), "Burn", "Superhot");
  return true;
}

