reactions.activationCode:
async function activation(type, data, token, item, name, api) {
    const placed = await api.placeZone(token, {
      type: "Line", size: 10, count: 1,
      title: "MICRO-MISSILE BARRAGE", centerLabel: "MISSILES",
      fillColor: "#e86944", borderColor: "#ffc28f",
      description: "GM: place a Line 10 originating from the Assault. It affects every character in the area."
    });
    const zone = placed?.[0]?.template;
    if (!zone) return;
    const targets = api.tokensInTemplate(zone).filter(target => target.id !== token.id);
    await api.setItemResource(item, false);
    const damage = String(api.tierValue(token, [6, 8, 10]));
    try {
      for (const target of targets) {
        let hasCover = api.hasStatus(target, "cover_soft", "cover_hard");
        if (!hasCover) {
          const cover = await api.askCard({
            title: "MICRO-MISSILES — COVER", item, originToken: token,
            relatedToken: target, owner: token,
            userIdControl: api.getActiveGMId(),
            description: "Does " + target.name + " have cover from this barrage (including terrain or zones)?",
            yesText: "Has Cover", noText: "No Cover"
          });
          if (!cover) continue;
          hasCover = cover.confirmed === true;
        }
        const result = await api.executeSaveVsEffect([target], {
