reactions.onMessage:
async function onMessage(type, data, token, item, name, api) {
    if (!game.user.isGM) return false;
    const flags = { rebakedTacticalCloakSource: item.id };
    const invisible = () => api.findEffectsOnToken(token, "invisible", {
      extraFlags: flags }).length > 0;
    const restore = async () => {
      if (!invisible()) await api.applyEffectsToTokens({
        tokens: [token], effectNames: ["invisible"],
        note: "Tactical Cloak: permanently Invisible until disabled.",
        duration: { label: "indefinite" }, notify: false
      }, flags);
    };
    if (data.event === "onDestroyed" || data.event === "onTokenRemoved") {
      await api.removeEffectsByNameFromTokens({
        tokens: [token], effectNames: ["invisible"],
        extraFlags: flags, notify: false
      });
      await api.removeActorFlags(token.actor, {
        rebakedTacticalCloakDisabled: true,
        rebakedTacticalCloakRearm: true
      });
      return true;
    }
    if (data.event === "onTurnStart") {
      if (api.getActorFlags(token.actor, "rebakedTacticalCloakDisabled"))
        await api.addActorFlags(token.actor,
          { rebakedTacticalCloakRearm: true });
      else await restore();
      return true;
    }
    if (data.event === "onTurnEnd") {
      if (api.getActorFlags(token.actor, "rebakedTacticalCloakDisabled")
        && api.getActorFlags(token.actor, "rebakedTacticalCloakRearm")) {
        await api.removeActorFlags(token.actor, {
          rebakedTacticalCloakDisabled: true,
          rebakedTacticalCloakRearm: true
        });
        await restore();
      }
      return true;
    }
    if (api.getActorFlags(token.actor, "rebakedTacticalCloakDisabled")) {
      ui.notifications.info("Tactical Cloak is already disabled.");
      return false;
    }
    const challengers = await api.chooseToken(token, {
      title: "TACTICAL CLOAK — CHALLENGER", count: 1,
      includeSelf: false, soft: true,
      filter: other => other?.actor && other.id !== token.id
        && api.getMinGridDistance(other, token)
          <= Number(other.actor.system?.sensor_range ?? 0),
      description: "GM: choose the character spending a Quick Action. They must have the Specter within their own Sensors; Hidden does not prevent this contest."
    });
    const challenger = challengers?.[0];
    if (!challenger?.actor || api.getMinGridDistance(challenger, token)
      > Number(challenger.actor.system?.sensor_range ?? 0)) return false;
    const gate = "rebaked_tactical_cloak_disrupt";
    if (!api.checkGate(challenger, gate)) {
      ui.notifications.warn(challenger.name + " has already challenged a Tactical Cloak this round.");
      return false;
    }
    const result = await api.executeContestedCheck(challenger, "SYSTEMS",
      token, "SYSTEMS", {
        title: "Tactical Cloak — Contested Systems",
        sendToOwner: true, sourceItem: item
      });
    if (!result?.completed) return false;
    if (!await api.consumeOncePerRound(challenger, gate)) return false;
    if (result.winner?.id === challenger.actor.id) {
      await api.addActorFlags(token.actor, {
        rebakedTacticalCloakDisabled: true,
        rebakedTacticalCloakRearm: false
      });
      await api.removeEffectsByNameFromTokens({
        tokens: [token], effectNames: ["invisible"],
        extraFlags: flags, notify: false
      });
      ui.notifications.info("Tactical Cloak disabled until the end of the Specter's next turn.");
      return true;
    }
    await api.moveTokenRuler(token, {
      range: Number(api.tokenSpeed(token)) || 0,
      cost: 0, free: true, action: "blink", urgent: true,
      title: "TACTICAL CLOAK — TELEPORT",
      description: "GM: the failed contest allows the Specter to teleport up to its Speed."
    });
    return true;
  }

reactions.evaluate:
function evaluate(type, data, token, item, name, api) {
  const source = data.triggeringToken;
  if (type === "onActivation")
    return source?.id === token.id && data.item?.id === item.id;
  const state = token.document.getFlag("lancer-automations",
    "rebakedEngineerTargetDesignation");
  if (!state?.windowRound || !game.combat?.started) return false;
  if (type === "onTurnEnd")
    return source?.id === token.id
      && Number(game.combat.round) > Number(state.windowRound);
  return type === "onDestroyed" && !!source?.document
    && source.id !== token.id
    && api.getLAFlag(source.document, "ownerActorUuid") === token.actor?.uuid
    && Number(state.destroyedTurrets ?? 0) < 2
    && !(state.countedTurretIds ?? []).includes(source.id)
    && Number(game.combat.round) <= Number(state.windowRound) + 1;
}

