async function onMessage(type, data, token, item, name, api) {
  if (!game.user.isGM) return false;
  const key = "rebakedEngineerTargetDesignation";
  const state = token.document.getFlag("lancer-automations", key) ?? {};
  if (data.event === "onTurnEnd") {
    await token.document.setFlag("lancer-automations", key,
      { ...state, windowRound: null, destroyedTurrets: 0,
        countedTurretIds: [] });
    return true;
  }
  if (data.event === "onDestroyed") {
    const answer = await api.askCard({
      title: "TARGET DESIGNATOR — TURRET DESTROYED", item,
      originToken: token, owner: token,
      description: "Was this Engineer's Deployable Turret destroyed by a hostile character before the end of the Engineer's next turn? Count only qualifying hostile destructions.",
      yesText: "Hostile Destroyed It", noText: "Do Not Count"
    });
    if (!answer?.confirmed) return false;
    if (!data.turretId || (state.countedTurretIds ?? []).includes(data.turretId))
      return false;
    const count = Math.min(2, Number(state.destroyedTurrets ?? 0) + 1);
    await token.document.setFlag("lancer-automations", key,
      { ...state, destroyedTurrets: count,
        countedTurretIds: [...(state.countedTurretIds ?? []), data.turretId] });
    if (count >= 2) {
      await api.setItemResource(item, true);
      ui.notifications.info("Target Designator recharged: two turrets were destroyed by hostiles.");
    }
    return true;
  }
  const target = (await api.chooseToken(token, {
    title: "TARGET DESIGNATOR — MARK TARGET", count: 1,
    range: "sensors", includeSelf: false, soft: false,
    filter: other => other?.actor && other.actor.type !== "deployable"
      && api.hasLineOfSight(token, other),
    description: "GM: choose a character within Sensors and line of sight. Up to two owned turrets may attack it at turn end."
  }))?.[0];
  if (!target?.actor || !api.hasLineOfSight(token, target)) return false;
  await api.applyEffectsToTokens({
    tokens: [target], effectNames: ["lockon"],
    note: "Target Designator: Lock On"
  });
  await token.document.setFlag("lancer-automations", key, {
    targetId: target.id, windowRound: Number(game.combat?.round ?? 0),
    destroyedTurrets: 0, countedTurretIds: []
  });
  await api.setItemResource(item, false);
  return true;
}

