async function activation(type, data, token, item, name, api) {
  const target = (await api.chooseToken(token, {
    title: "TELEFRAG — TARGET", count: 1,
    range: 15, includeSelf: false, soft: false,
    filter: candidate => api.hasLineOfSight(token, candidate),
    description: "GM: choose a character in line of sight within Range 15. The Operator telefrags their occupied space before blinking away."
  }))?.[0];
  if (!target?.actor || api.getMinGridDistance(token, target) > 15
    || !api.hasLineOfSight(token, target)) return;
  await api.setItemResource(item, false);
  const damage = String(api.tierValue(token, [4, 5, 6]));
  const saves = await api.executeSaveVsEffect([target], {
    stat: "AGILITY", title: "Telefrag", origin: token,
    cardDescription: "Failure: full AP Energy damage, Jammed and Shredded until the end of next turn. Success: half AP Energy damage only."
  });
  if (saves?.[0]?.result?.completed) {
    await api.executeDamageRoll(token, [target], damage, "Energy",
      "Telefrag", { ap: true, half_damage: saves[0].passed });
    if (!saves[0].passed) await api.applyEffectsToTokens({
      tokens: [target], effectNames: ["jammed", "shredded"],
      note: "Telefrag", duration: api.untilEndOfTurn(target, 1)
    }, { rebakedOperatorTelefrag: item.id });
  }
  await api.executeDamageRoll(token, [token], "1d6", "Energy",
    "Telefrag — Backlash", { ap: true });
  if (api.hasStatus(token, "destroyed") || !canvas.tokens.get(token.id)) return;
  while (true) {
    const plans = await api.moveTokenRuler(token, {
      range: -1, cost: 0, free: true, action: "blink",
      planOnly: true, urgent: true,
      title: "TELEFRAG — EXIT TELEPORT",
      description: "GM: choose a free destination within Range 5 of "
        + target.name + ". The selected destination is checked before teleporting."
    });
    const final = plans?.[0]?.path?.at(-1);
    if (!final) return;
    if (api.getMinGridDistance(token, target,
      { x: final.x, y: final.y }) > 5) {
      ui.notifications.warn("Telefrag: choose a destination within Range 5 of the target.");
      continue;
    }
    await api.moveToken(token, {
      destination: { x: final.x + token.w / 2,
        y: final.y + token.h / 2 },
      action: "blink", cost: 0
    });
    return;
  }
}

