reactions.onInit:
async function onInit(token, item, api) {
  if (!item) return;
  const sources = [];
  for (const tier of [1, 2, 3]) {
    const sourceName = "Re:Baked Titan-Snare Drone T" + tier + " (NPC)";
    let source = null;
    for (const pack of game.packs.filter(pack => pack.documentName === "Actor")) {
      const entry = (await pack.getIndex()).find(entry => entry.name === sourceName);
      if (!entry) continue;
      const candidate = await pack.getDocument(entry._id);
      if (candidate?.type === "deployable" && candidate.system?.lid) {
        source = candidate;
        break;
      }
    }
    if (!source) {
      ui.notifications.warn("Titan-Snare Drone: import Rebaked_NPC_Deployables_Public_v1.lcp, then reload Foundry to register its Deployables entry.");
      return;
    }
    sources.push({ lid: source.system.lid, tier });
  }
  const previous = item.getFlag("lancer-automations", "extraDeployables") ?? [];
  if (item.system?.deployables?.length)
    await item.update({ "system.deployables": [] });
  if (previous.length !== 3 || previous.some((lid, index) =>
    lid !== sources[index].lid)) {
    await api.addItemFlags(item, {
      extraDeployables: [], extraDeployableLidsViaUI: [],
      extraDeployableOpts: {}
    });
    await api.addExtraDeploymentLids(item, sources);
  }
  if (item.getFlag("lancer-automations", "deployRange") !== 1
    || item.getFlag("lancer-automations", "deployCount") !== 1)
    await api.addItemFlags(item, { deployRange: 1, deployCount: 1 });
  await api.setHidePrimaryAction(item);
}

reactions.onMessage:
async function onMessage(type, data, token, item, name, api) {
    if (!game.user.isGM) return false;
    if (data.event === "onDeploy") {
      for (const id of data.deployedIds ?? []) {
      const droneToken = canvas.tokens.get(id);
      if (!droneToken?.actor
        || api.getLAFlag(droneToken.document, "ownerActorUuid") !== token.actor?.uuid)
        continue;
      const droneDoc = droneToken.document;
      await api.setLAFlag(droneDoc, "rebakedTitanSnareOwner", token.actor.uuid);
      await api.setLAFlag(droneDoc, "rebakedTitanSnareItem", item.id);
      const sourceActor = game.actors.get(droneDoc.actorId);
      if (sourceActor?.name !== "Titan-Snare Drone")
        await sourceActor?.update({ name: "Titan-Snare Drone" });
      if (droneDoc.name !== "Titan-Snare Drone")
        await droneDoc.update({ name: "Titan-Snare Drone" });
      if (!game.modules.get("grid-aware-auras")?.active) {
        ui.notifications.error("Titan-Snare Drone requires Grid-Aware Auras for its Immobilized field.");
        return true;
      }
      const auraName = "Titan-Snare Drone — " + droneDoc.id;
      await api.ensureAura(droneToken, {
        name: auraName, radius: 3, innerRadius: 0,
        fillColor: "#586eb1", lineColor: "#91b8ff",
        fillOpacity: 0.12, lineOpacity: 0.8,
        ownerVisibility: { default: true },
        nonOwnerVisibility: { default: true },
        macros: ["ENTER", "TARGET_TURN_START"].map(mode => ({
          mode, targetTokens: "ALL",
          function: async function (subject, parent, aura, options) {
            if (options?.isPreview || !subject?.actor || !parent?.document
              || subject.id === parent.id) return;
            const la = game.modules.get("lancer-automations")?.api;
            if (!la || game.user.id !== la.getActiveGMId()
              || !la.isHostile(parent, subject)
              || Number(parent.actor?.system?.hp?.value ?? 0) <= 0)
              return;
            const flags = { rebakedTitanSnareDroneId: parent.id };
            if (la.findEffectsOnToken(subject, "immobilized",
              { extraFlags: flags }).length) return;
            await la.applyEffectsToTokens({
              tokens: [subject], effectNames: ["immobilized"],
              note: "Titan-Snare Drone: until this drone is destroyed.",
              duration: { label: "indefinite" }, notify: false
            }, flags);
          }
        }))
      });
      if (!api.findAura(droneToken, auraName))
        ui.notifications.error("Titan-Snare Drone aura did not attach; check the GM console.");
      for (const subject of canvas.tokens.placeables) {
        if (!subject?.actor || !api.isHostile(token, subject)
          || api.getMinGridDistance(subject, droneToken) > 3) continue;
        const flags = { rebakedTitanSnareDroneId: droneToken.id };
        if (api.findEffectsOnToken(subject, "immobilized",
          { extraFlags: flags }).length) continue;
        await api.applyEffectsToTokens({
          tokens: [subject], effectNames: ["immobilized"],
          note: "Titan-Snare Drone: until this drone is destroyed.",
          duration: { label: "indefinite" }, notify: false
        }, flags);
      }
      }
      return true;
    }
    const subject = canvas.tokens.get(data.subjectId);
    if (["onDestroyed", "onTokenRemoved"].includes(data.event)) {
      await api.removeEffectsByNameFromTokens({
        tokens: canvas.tokens.placeables,
        effectNames: ["immobilized"],
        extraFlags: { rebakedTitanSnareDroneId: data.removedDroneId },
        notify: false
      });
      return true;
    }
    return false;
  }

