reactions.evaluate:
function evaluate(type, data, token, item, name, api) {
    return api.checkGate(token, "rebaked_assault_hunker_" + item.id)
      && (data.flowState?.data?.hit_results ?? []).some(result =>
        result.hit && result.target?.id === token.id);
  }

reactions.activationCode:
async function activation(type, data, token, item, name, api) {
    const gmId = api.getActiveGMId();
    if (!gmId || !game.users.get(gmId)?.active) {
      ui.notifications.warn("Hunker Down requires an active GM.");
      return;
    }
    const mode = await data.sendMessageToReactor({ attackerId: data.triggeringToken?.id }, gmId, { wait: true });
    if (mode !== "hunker") return;
    await api.injectBonusToFlowState(data.flowState, {
      id: "rebaked-assault-hunker-resistance-" + token.id,
      name: "Hunker Down", type: "target_modifier", subtype: "half_damage",
      applyTo: [token.id], rollTypes: ["damage"]
    });
  }

reactions.onMessage:
async function onMessage(type, data, token, item, name, api) {
    if (!game.user.isGM) return null;
    const shock = token.actor.items.some(i =>
      i.system?.lid === "npc-rebake_npcf_trait_shocktrooper" && !i.system?.destroyed);
    const choices = [{ text: "Hunker: resist this damage; become Slowed", icon: "fas fa-shield-alt" }];
    if (shock) choices.push({ text: "Shocktrooper: Boost; +1 Accuracy until end of next turn", icon: "fas fa-person-running" });
    choices.push({ text: "Decline", icon: "fas fa-times" });
    const choice = await api.startChoiceCard({
      mode: "or", title: "HUNKER DOWN", item, originToken: token,
      userIdControl: api.getActiveGMId(),
      description: "An attack hit the Assault. Choose its defensive reaction.", choices
    });
    if (!choice || choice.choiceIdx === choices.length - 1) return null;
    if (!await api.consumeOncePerRound(token, "rebaked_assault_hunker_" + item.id)) return null;
    await api.setReaction(token, false);
    if (choice.choiceIdx === 0) {
      await api.applyEffectsToTokens({
        tokens: [token], effectNames: ["slow"], note: "Hunker Down",
        duration: api.untilEndOfTurn(token, 1)
      }, { rebakedAssaultHunker: item.id });
      return "hunker";
    }
    const speed = Number(api.tokenSpeed(token)) || 0;
    if (speed > 0) await api.moveTokenRuler(token, {
      range: speed, cost: 0, action: "walk", urgent: true,
      title: "SHOCKTROOPER — BOOST",
      description: "GM: Boost the Assault up to Speed. Apply normal engagement and reaction rules."
    });
    await api.addGlobalBonus(token.actor, {
      id: "rebaked-assault-shocktrooper-" + item.id,
      name: "Shocktrooper", type: "accuracy", val: 1,
      rollTypes: ["attack", "check"]
    }, { duration: "end", durationTurns: 1, origin: token });
    return "shocktrooper";
  }

reactions.onInit:
async function onInit(token, item, api) {
if (!token?.actor || !item) return;
await api.ensureLinkedBonus({
  items: [item],
  bonusData: {
    id: "rebaked-assault-rank-discipline-v1",
    name: "Rank Discipline — Allied Mech",
    type: "accuracy", val: 1, rollTypes: ["attack", "check"],
    condition: (state, actor, data, context) => {
      const api = game.modules.get("lancer-automations")?.api;
      const self = canvas.tokens.get(context?.ownerTokenId)
        ?? canvas.tokens.placeables.find(t => t.actor?.id === actor.id);
      if (!api || !self) return false;
      return canvas.tokens.placeables.some(other =>
        other.id !== self.id && other.actor
        && (other.actor.type === "mech" || other.actor.type === "npc")
        && api.isFriendly(self, other)
        && api.getMinGridDistance(self, other) <= 1);
    }
  },
  addOptions: { duration: "constant" }
});
}

reactions.evaluate:
function evaluate(triggerType, data, token, item, name, api) {
    if (triggerType === "onEnterCombat") return data.triggeringToken?.id === token.id;
    return data.triggeringToken?.id === token.id
      && (Number(data.distanceMoved) || 0) > 0
      && api.checkGate(token, "cataphract_trample");
  }

reactions.activationCode:
async function activation(triggerType, data, token, item, name, api) {
    if (triggerType === "onEnterCombat") {
      if (!api.findEffectsOnToken(token, "phasing", {
        extraFlags: { cataphractTrampleSource: item.id }
      }).length) {
        await api.applyEffectsToTokens({
          tokens: [token], effectNames: ["phasing"],
          note: "Trample: may move through characters but cannot end movement in their spaces.",
          duration: { label: "indefinite" }, notify: false
        }, { cataphractTrampleSource: item.id });
      }
      return;
    }
    const answer = await api.askCard({
      title: "CATAPHRACT — TRAMPLE",
      description: "Did this movement pass through a character's space? Trample can damage one such character, once this turn.",
      item, originToken: token, owner: token,
      yesText: "Resolve Trample", noText: "No Trample"
    });
    if (!answer?.confirmed) return;
    const chosen = await api.chooseToken(token, {
      title: "TRAMPLE TARGET", count: 1, range: 20,
      includeSelf: false, soft: true,
      description: "GM: choose a character whose space the Cataphract crossed."
    });
    if (!chosen?.[0]) return;
    if (!await api.consumeOncePerTurn(token, "cataphract_trample")) return;
    await api.executeDamageRoll(token, [chosen[0]],
      api.tierValue(token, [2, 3, 4]), "Kinetic", "Trample");
  }

