reactions.evaluate:
function evaluate(type, data, token, item, name, api) {
    if (type === "onActivation")
      return data.triggeringToken?.id === token.id && data.item?.id === item.id;
    const targetId = api.getActorFlags(token.actor, "rebakedAssassinTransfixTargetId");
    return !!targetId && [token.id, targetId].includes((data.triggeringToken ?? data.token)?.id);
  }

reactions.activationCode:
async function activation(type, data, token, item, name, api) {
    const flags = { assassinTransfixSourceId: token.id, assassinTransfixItemId: item.id };
    const clear = async () => {
      const targetId = api.getActorFlags(token.actor, "rebakedAssassinTransfixTargetId");
      const target = canvas.tokens.get(targetId);
      if (target) await api.removeEffectsByNameFromTokens({
        tokens: [target], effectNames: ["stunned"], extraFlags: flags, notify: false
      });
      await api.removeEffectsByNameFromTokens({
        tokens: [token], effectNames: ["immobilized"], extraFlags: flags, notify: false
      });
      await api.removeActorFlags(token.actor, { rebakedAssassinTransfixTargetId: true });
    };
    if (type !== "onActivation") {
      const targetId = api.getActorFlags(token.actor, "rebakedAssassinTransfixTargetId");
      const target = canvas.tokens.get(targetId);
      const broken = !target || type === "onStructure" || type === "onDestroyed"
        || type === "onTokenRemoved" || api.getMinGridDistance(token, target) > 1;
      if (broken) await clear();
      return;
    }
    const selected = await api.chooseToken(token, {
      title: "TRANSFIX", count: 1, range: 1, includeSelf: false,
      soft: false, description: "Choose an adjacent character."
    });
    const target = selected?.[0];
    if (!target) return;
    await api.setItemResource(item, false);
    const result = await api.executeSaveVsEffect([target], {
      stat: "ENG", title: "Transfix", origin: token,
      cardDescription: "On failure, target becomes Stunned and the Assassin Immobilized until adjacency breaks or the target takes Structure damage."
    });
    if (!result?.[0]?.result?.completed || result[0].passed) return;
    await clear();
    await api.addActorFlags(token.actor, { rebakedAssassinTransfixTargetId: target.id });
    await api.applyEffectsToTokens({
      tokens: [target], effectNames: ["stunned"],
      note: "Transfix", duration: { label: "indefinite" }
    }, flags);
    await api.applyEffectsToTokens({
      tokens: [token], effectNames: ["immobilized"],
      note: "Transfix", duration: { label: "indefinite" }
    }, flags);
  }

reactions.evaluate:
function evaluate(type, data, token, item, name, api) {
    const attacker = data.triggeringToken;
    return !!attacker && attacker.id !== token.id
      && api.getMinGridDistance(token, attacker) <= api.getSensorRange_WithBonus(token)
      && api.checkGate(token, "rebaked_hornet_umbral_" + item.id);
  }

reactions.activationCode:
async function activation(type, data, token, item, name, api) {
    const attacker = data.triggeringToken;
    const gmId = api.getActiveGMId();
    if (!attacker || !gmId || !game.users.get(gmId)?.active) {
      ui.notifications.warn("Umbral Interdiction requires an active GM.");
      return;
    }
    const outcome = await data.sendMessageToReactor({
      attackerId: attacker.id
    }, gmId, { wait: true });
    if (!outcome?.autoMiss) return;
    const reason = "Umbral Interdiction: the impaired attacker failed its Systems check, so the attack misses.";
    if (type === "onInitTechAttack") data.cancelTechAttack(reason);
    else data.cancelAttack(reason);
  }

reactions.onMessage:
async function onMessage(type, data, token, item, name, api) {
    if (!game.user.isGM) return { autoMiss: false };
    const attacker = canvas.tokens.get(data.attackerId);
    if (!attacker || api.getMinGridDistance(token, attacker) > api.getSensorRange_WithBonus(token))
      return { autoMiss: false };
    const impaired = api.hasStatus(attacker, "impaired");
    const choice = await api.askCard({
      title: "UMBRAL INTERDICTION", item, originToken: token,
      relatedToken: attacker, owner: token,
      description: "GM: if the attacker is in line of sight, spend this Reaction? "
        + (impaired
          ? "Already Impaired: a Systems check decides whether its attack misses."
          : "Not Impaired: apply Impaired before its attack resolves."),
      yesText: "Use Reaction", noText: "Let Attack Continue"
    });
    if (!choice?.confirmed) return { autoMiss: false };
    if (!await api.consumeOncePerRound(token,
      "rebaked_hornet_umbral_" + item.id)) return { autoMiss: false };
    await api.setReaction(token, false);
    if (!impaired) {
      await api.applyEffectsToTokens({
        tokens: [attacker], effectNames: ["impaired"],
        note: "Umbral Interdiction",
        duration: api.untilEndOfTurn(attacker, 1)
      }, { rebakedHornetUmbral: item.id });
      return { autoMiss: false };
    }
    const check = await api.executeForceCheck("SYS", [attacker], {
      saveVs: token, sendToOwner: true,
      title: "Umbral Interdiction — Systems Check"
    });
    return { autoMiss: check?.results?.[0]?.completed && !check.results[0].passed };
  }

reactions.evaluate:
function evaluate(type, data, token, item, name, api) {
  const target = data.triggeringToken;
  if (!target?.actor || target.id === token.id) return false;
  if (type === "onInitCheck")
    return String(data.statName ?? "").toUpperCase() === "BURN :: ENG"
      && api.getMinGridDistance(token, target) <= 3;
  if (type === "onTurnStart")
    return api.getMinGridDistance(token, target) <= 3;
  return !!data.startPos
    && api.getMinGridDistance(target, token, data.startPos) > 3
    && api.getMinGridDistance(token, target) <= 3
    && api.checkGate(token,
      "rebaked_pyro_unshielded_entry_" + item.id + "_" + target.id);
}

reactions.activationCode:
async function activation(type, data, token, item, name, api) {
  if (type === "onInitCheck") {
    await api.injectBonusToFlowState(data.flowState, {
      id: "rebaked-pyro-unshielded-burn-check-" + item.id,
      name: "Unshielded Reactor — Burn Check",
      type: "difficulty", val: 1, rollTypes: ["check"]
    });
    return;
  }
  const gmId = api.getActiveGMId();
  if (!gmId || !game.users.get(gmId)?.active) {
    ui.notifications.warn("Unshielded Reactor requires an active GM to apply Heat.");
    return;
  }
  await data.sendMessageToReactor({
    targetId: data.triggeringToken.id, kind: type
  }, gmId, { wait: true });
}

reactions.onMessage:
async function onMessage(type, data, token, item, name, api) {
  if (!game.user.isGM) return false;
  const target = canvas.tokens.get(data.targetId);
  if (!target?.actor || target.id === token.id
    || api.getMinGridDistance(token, target) > 3) return false;
  if (data.kind === "onMove" && !await api.consumeOncePerRound(token,
    "rebaked_pyro_unshielded_entry_" + item.id + "_" + target.id))
    return false;
  await api.executeDamageRoll(token, [target],
    String(api.tierValue(token, [2, 3, 4])), "Heat",
    "Unshielded Reactor");
  return true;
}

reactions.evaluate:
function evaluate(type, data, token, item) {
  return data.triggeringToken?.id === token.id
    && data.techItem?.system?.lid === item.system?.lid
    && (data.targets ?? []).some(hit => hit?.target?.actor);
}

reactions.activationCode:
async function activation(type, data, token, item, name, api) {
  const targets = [...new Set((data.targets ?? [])
    .map(hit => hit?.target).filter(target => target?.actor))];
  for (const target of targets) {
    await api.executeDamageRoll(token, [target],
      String(api.tierValue(token, [2, 3, 4])), "Heat", "Warp Sensors");
    await api.addGlobalBonus(target.actor, {
      id: "rebaked-mirage-warp-sensors-" + item.id + "-" + target.id,
      name: "Warp Sensors — targets have Soft Cover",
      type: "target_modifier", subtype: "soft_cover",
      rollTypes: ["attack"]
    }, { duration: "end", durationTurns: 1,
      origin: target, refresh: true });
  }
}

reactions.evaluate:
function evaluate(type, data, token, item, name, api) {
  if (type === "onTurnStart")
    return data.triggeringToken?.id === token.id;
  if (type === "onDamage")
    return data.target?.id === token.id
      && (data.damages ?? []).some(value => Number(value) > 0);
  const attacker = data.triggeringToken;
  if (!attacker?.actor || api.isFriendly(token, attacker)
    || api.getActorFlags(token.actor, "rebakedWarpTargetingSuppressed"))
    return false;
  return String(data.actionData?.attack_type ?? "").toLowerCase() === "ranged";
}

reactions.activationCode:
async function activation(type, data, token, item, name, api) {
  if (type === "onTurnStart") {
    await api.addActorFlags(token.actor,
      { rebakedWarpTargetingSuppressed: null });
    return;
  }
  if (type === "onDamage") {
    const hpBefore = Number(token.actor?.system?.hp?.value ?? 0);
    const shieldBefore = Number(token.actor?.system?.overshield?.value ?? 0);
    api.afterFlow(data, async () => {
      const hpAfter = Number(token.actor?.system?.hp?.value ?? 0);
      const shieldAfter = Number(token.actor?.system?.overshield?.value ?? 0);
      if (hpAfter < hpBefore || shieldAfter < shieldBefore)
        await api.addActorFlags(token.actor,
          { rebakedWarpTargetingSuppressed: true });
    });
    return;
  }
  const ids = canvas.tokens.placeables
    .filter(defender => defender.actor
      && defender.actor.type !== "deployable"
      && api.isFriendly(token, defender)
      && api.getMinGridDistance(token, defender)
        <= api.getSensorRange_WithBonus(token))
    .map(defender => defender.id);
  if (!ids.length) return;
  await api.injectBonusToFlowState(data.flowState, {
    id: "rebaked-mirage-warp-targeting-" + item.id,
    name: "Warp Targeting — Digital Soft Cover",
    type: "difficulty", val: 1, applyTo: ids,
    rollTypes: ["attack"]
  });
}

async function activation(type, data, token, item, name, api) {
  await api.injectBonusToFlowState(data.flowState, {
    id: "rebaked-assault-rifle-no-cover-" + token.id,
    name: "Heavy Assault Rifle — No Cover",
    type: "accuracy", val: 1, rollTypes: ["attack"],
    applyToCondition: "@@fn:(target, state, reactorToken, entry) => Number(entry?.cover) === 0"
  });
}

reactions.evaluate:
function evaluate(type, data, token, item, name, api) {
    return data.triggeringToken?.id !== token.id
      && (data.targets ?? []).some(target => target?.id === token.id)
      && api.checkGate(token, "rebaked_hornet_weave_" + item.id);
  }

reactions.activationCode:
async function activation(type, data, token, item, name, api) {
    const gmId = api.getActiveGMId();
    if (!gmId || !game.users.get(gmId)?.active) {
      ui.notifications.warn("Weave requires an active GM to confirm the reaction attack.");
      return;
    }
    const reactionAttack = await data.sendMessageToReactor({
      attackerId: data.triggeringToken?.id
    }, gmId, { wait: true });
    if (!reactionAttack) return;
    if (!await api.consumeOncePerRound(token,
      "rebaked_hornet_weave_" + item.id)) return;
    const reason = "Weave: the first reaction attack against the Hornet this round automatically fails.";
    if (type === "onInitTechAttack") data.cancelTechAttack(reason);
    else data.cancelAttack(reason);
  }

reactions.onMessage:
async function onMessage(type, data, token, item, name, api) {
    if (!game.user.isGM) return false;
    const attacker = canvas.tokens.get(data.attackerId);
    const choice = await api.askCard({
      title: "WEAVE — REACTION ATTACK?", item, originToken: token,
      relatedToken: attacker, owner: token,
      description: "Is this the first reaction attack made against the Hornet this round? If so, it automatically misses.",
      yesText: "Reaction — Force Miss", noText: "Not a Reaction"
    });
    return choice?.confirmed === true;
  }

reactions.evaluate:
function evaluate(type, data, token, item, name, api) {
  const mover = data.triggeringToken;
  return !!mover?.actor && mover.id !== token.id
    && api.isHostile(token, mover)
    && api.hasLineOfSight(token, mover)
    && !data.moveInfo?.isInvoluntary
    && api.checkGate(token, "rebaked_sentinel_wrath_lock_" + item.id);
}

