}

reactions.onMessage:
async function onMessage(type, data, token, item, name, api) {
  if (!game.user.isGM) return false;
  const mover = canvas.tokens.get(data.moverId);
  if (!mover?.actor || !api.isHostile(token, mover)
    || !api.hasLineOfSight(token, mover)) return false;
  const answer = await api.askCard({
    title: "WRATH-LOCK", item, originToken: token,
    relatedToken: mover, owner: token,
    description: mover.name + " is moving in line of sight. Boost toward them and give them Lock On as a Reaction?",
    yesText: "Boost and Mark", noText: "Decline"
  });
  if (!answer?.confirmed || !api.hasReactionAvailable(token)) return false;
  if (!await api.consumeOncePerRound(token,
    "rebaked_sentinel_wrath_lock_" + item.id)) return false;
  await api.setReaction(token, false);
  await api.moveTokenRuler(token, {
    range: Number(api.tokenSpeed(token)) || 0,
    cost: 0, free: true, action: "walk", urgent: true,
    title: "WRATH-LOCK — BOOST TOWARD " + mover.name,
    description: "GM: Boost up to Speed directly toward " + mover.name
      + ". Apply normal obstructions, engagement, and reaction rules."
  });
  await api.applyEffectsToTokens({
    tokens: [mover], effectNames: ["lockon"], note: "Wrath-Lock"
  }, { rebakedSentinelWrathLock: item.id });
  return true;
}

reactions.evaluate:
function evaluate(triggerType, data, token, item) {
    if (data.triggeringToken?.id !== token.id) return false;
    return triggerType === "onDestroyed" || data.item?.id === item?.id;
  }

