ui.notifications.info(subject.name + " enters blinkspace until the end of their next turn.");"),
      action("whenTurnStart", "const api = game.modules.get("lancer-automations")?.api;
const subject = token?.object ?? token;
if (!game.user.isGM || !api || !subject?.actor || !game.combat) return;
