async function onMessage(type, data, token, item, name, api) {
  if (!game.user.isGM) return false;
  const mover = canvas.tokens.get(data.moverId);
  if (!mover?.actor || !token?.actor || !api.isHostile(token, mover))
    return false;
  const eligible = () => canvas.tokens.placeables.filter(turret =>
    turret.actor?.type === "deployable"
    && api.getLAFlag(turret.document, "ownerActorUuid") === token.actor.uuid
    && !api.hasStatus(turret, "jammed")
    && !api.hasStatus(turret, "stunned")
    && api.checkGate(turret, "rebaked_engineer_perimeter_overwatch")
    && api.getMinGridDistance(mover, turret) <= 3
    && api.hasLineOfSight(turret, mover));
  const turrets = eligible();
  for (const turret of turrets) {
    if (!mover.actor || !eligible().some(other => other.id === turret.id))
      break;
    const answer = await api.askCard({
      title: "PERIMETER DEFENSE — OVERWATCH",
      item, originToken: turret, relatedToken: mover, owner: token,
      description: mover.name + " began moving within Threat 3 of "
        + turret.name + ". Fire this turret? Once per round per turret.",
      yesText: "Fire Turret", noText: "Hold Fire"
    });
    if (!answer?.confirmed) continue;
    if (!await api.consumeOncePerRound(turret,
      "rebaked_engineer_perimeter_overwatch")) continue;
    const tier = Number(api.getTier(token)) || 1;
    await api.executeBasicAttack(turret.actor, {
      targets: [mover], fxSourceToken: turret,
      attack_type: "Ranged", flat_bonus: tier,
      damage: [{ val: String(3 + tier), type: "Kinetic" }]
