function evaluate(type, data, token, item, name, api) {
  const subject = data.triggeringToken;
  if (type === "onDeploy")
    return subject?.id === token.id && data.item?.id === item.id;
  const drones = canvas.tokens.placeables.filter(drone =>
    api.getLAFlag(drone.document, "rebakedFlareOwner") === token.actor?.uuid
    && api.getLAFlag(drone.document, "rebakedFlareItem") === item.id
    && Number(drone.actor?.system?.hp?.value ?? 0) > 0);
  if (!drones.length) return false;
  if (type === "onInitAttack" || type === "onInitTechAttack")
    return subject?.id === token.id
      && (data.targets ?? []).some(target => target?.actor
        && drones.some(drone => api.getMinGridDistance(target, drone) <= 2));
  if (!subject?.actor) return false;
  if (type === "onStatusApplied"
    && !["hidden", "invisible"].includes(String(data.statusId).toLowerCase()))
    return false;
  if (type === "onMove" && !(Number(data.distanceMoved ?? 0) > 0))
    return false;
  return drones.some(drone => api.getMinGridDistance(subject, drone) <= 2);
}

