reactions.onInit:
async function onInit(token, item, api) {
  if (!item) return;
  const sources = [];
  for (const tier of [1, 2, 3]) {
    const sourceName = "Re:Baked Flare Drone T" + tier + " (NPC)";
    let source = null;
    for (const pack of game.packs.filter(pack => pack.documentName === "Actor")) {
      const entry = (await pack.getIndex()).find(entry => entry.name === sourceName);
      if (!entry) continue;
      const candidate = await pack.getDocument(entry._id);
      if (candidate?.type === "deployable" && candidate.system?.lid) {
        source = candidate;
        break;
      }
    }
    if (!source) {
      ui.notifications.warn("Flare Drone: import Rebaked_NPC_Deployables_Public_v1.lcp, then reload Foundry to register its Deployables entry.");
      return;
    }
    sources.push({ lid: source.system.lid, tier });
  }
  const previous = item.getFlag("lancer-automations", "extraDeployables") ?? [];
  if (item.system?.deployables?.length)
    await item.update({ "system.deployables": [] });
  if (previous.length !== 3 || previous.some((lid, index) =>
    lid !== sources[index].lid)) {
    await api.addItemFlags(item, {
      extraDeployables: [], extraDeployableLidsViaUI: [],
      extraDeployableOpts: {}
    });
    await api.addExtraDeploymentLids(item, sources);
  }
  if (item.getFlag("lancer-automations", "deployRange") !== 25
    || item.getFlag("lancer-automations", "deployCount") !== 1)
    await api.addItemFlags(item, { deployRange: 25, deployCount: 1 });
  await api.setHidePrimaryAction(item);
}

reactions.onMessage:
async function onMessage(type, data, token, item, name, api) {
  if (!game.user.isGM) return false;
  const drones = () => canvas.tokens.placeables.filter(drone =>
    api.getLAFlag(drone.document, "rebakedFlareOwner") === token.actor?.uuid
    && api.getLAFlag(drone.document, "rebakedFlareItem") === item.id);
  const clearInArea = async subject => {
    const source = subject?.actor && drones().find(drone =>
      api.getMinGridDistance(subject, drone) <= 2);
    if (!source) return;
    const present = ["hidden", "invisible"].filter(status =>
      api.hasStatus(subject, status));
    if (!present.length) return;
    await api.removeEffectsByNameFromTokens({
      tokens: [subject], effectNames: present, notify: false
    });
    const cleared = present.filter(status => !api.hasStatus(subject, status));
    if (!cleared.length) return;
    const labels = cleared.map(status =>
      status === "hidden" ? "Hidden" : "Invisible");
    await ChatMessage.create({
      speaker: { alias: "Flare Drone" },
      content: "<p><strong>Flare Drone:</strong> " + subject.name
        + " loses " + labels.join(" and ")
        + " inside " + source.name + "'s light.</p>"
    });
  };
  if (data.event === "onDeploy") {
    const old = drones();
    for (const id of data.deployedIds ?? []) {
    const drone = canvas.tokens.get(id);
    if (!drone?.actor
      || api.getLAFlag(drone.document, "ownerActorUuid") !== token.actor?.uuid)
      continue;
    const droneDoc = drone.document;
    if (!api.hasLineOfSight(token, drone)) {
      await droneDoc.delete();
      ui.notifications.warn("Flare Drone must be placed within line of sight.");
      continue;
    }
    await api.setLAFlag(droneDoc, "rebakedFlareOwner", token.actor.uuid);
    await api.setLAFlag(droneDoc, "rebakedFlareItem", item.id);
    const sourceActor = game.actors.get(droneDoc.actorId);
    if (sourceActor?.name !== "Flare Drone")
      await sourceActor?.update({ name: "Flare Drone" });
    if (droneDoc.name !== "Flare Drone")
      await droneDoc.update({ name: "Flare Drone" });
    if (game.modules.get("grid-aware-auras")?.active) {
      const auraName = "Flare Drone — Burst 2 — " + drone.id;
      await api.ensureAura(drone, {
        name: auraName, unified: false, radius: 2, innerRadius: 0,
        fillColor: "#f4ce55", lineColor: "#fff2ab",
        fillOpacity: 0.16, lineOpacity: 0.9,
        lineDashOffsetAnimation: -5,
        ownerVisibility: { default: true },
        nonOwnerVisibility: { default: true }
      });
      if (!api.findAura(drone, auraName))
        ui.notifications.warn("Flare Drone: its Burst 2 aura did not appear.");
    } else {
      ui.notifications.warn("Flare Drone: Grid-Aware Auras is inactive; its Burst 2 area is not visible.");
    }
    for (const previous of old) await previous.document.delete();
    for (const subject of canvas.tokens.placeables) await clearInArea(subject);
    }
    return true;
  }
  const subject = canvas.tokens.get(data.subjectId);
  await clearInArea(subject);
  return true;
}

reactions.evaluate:
function evaluate(type, data, token, item, name, api) {
  if (!data.triggeringToken?.actor || data.triggeringToken.id === token.id
    || !api.hasReactionAvailable(token)) return false;
  const weapon = data.weapon;
  const tier = Math.max(1, Number(data.triggeringToken.actor.system?.tier ?? 1));
  const raw = weapon?.type === "npc_feature"
    ? weapon.system?.damage?.[tier - 1]
    : weapon?.system?.active_profile?.damage ?? weapon?.system?.damage;
  const damage = Array.isArray(raw) ? raw : [];
  if (!damage.some(part => ["kinetic", "explosive"].includes(String(part.type ?? "").toLowerCase())))
    return false;
  return (data.targets ?? []).some(target => target?.actor
    && target.id !== token.id && api.isFriendly(token, target)
    && api.getMinGridDistance(token, target) <= 2
    && api.hasLineOfSight(token, target));
}

reactions.activationCode:
async function activation(type, data, token, item, name, api) {
  const gmId = api.getActiveGMId();
  if (!gmId || !game.users.get(gmId)?.active) {
    ui.notifications.warn("Attractor Field needs an active GM.");
    return;
  }
  const targets = (data.targets ?? []).filter(target => target?.actor
    && target.id !== token.id && api.isFriendly(token, target)
    && api.getMinGridDistance(token, target) <= 2
    && api.hasLineOfSight(token, target));
  if (!targets.length) return;
  const area = (data.weapon?.system?.active_profile?.range
    ?? data.weapon?.system?.range ?? [])
    .some(entry => ["blast", "burst", "line", "cone"].includes(String(entry.type ?? "").toLowerCase()));
  const choices = targets.map(target => ({ text: "Protect " + target.name }));
  choices.push({ text: "Decline" });
  const result = await api.startChoiceCard({
    title: "ATTRACTOR FIELD", item, originToken: token,
    relatedToken: data.triggeringToken, userIdControl: gmId,
    description: "Spend the Goliath's Reaction and recharge to become the target of this Kinetic or Explosive attack?"
      + (area ? " This is an area attack: reposition its template toward the Goliath before resolving, and review every affected target in the attack HUD." : ""),
    choices
  });
  const chosen = targets[result?.choiceIdx];
  if (!chosen || !api.hasReactionAvailable(token)) return;
  const hud = data.flowState?.data?.acc_diff;
  if (typeof hud?.replaceTargets !== "function") {
    ui.notifications.error("Attractor Field: this attack flow cannot replace targets.");
    return;
  }
  const current = hud.targets.map(entry => entry.targetUuid);
  const replacement = current.map(uuid => uuid === chosen.document.uuid ? token.document.uuid : uuid);
  if (!replacement.includes(token.document.uuid)) {
    ui.notifications.error("Attractor Field: the protected ally is no longer targeted.");
    return;
  }
  hud.replaceTargets([...new Set(replacement)]);
  await api.setReaction(token, false);
  await api.setItemResource(item, false);
  if (area) ui.notifications.info("Attractor Field: GM, reposition the area template toward the Goliath and review the final targets before rolling.");
}

