      title: "MELT — TARGET HEX", centerLabel: "MELT / BURST 2",
      fillColor: "#f06a29", borderColor: "#ffd08a",
      description: "GM: center this Burst 2 marker on the hex containing the target object, deployable, or Drone."
    });
    const zone = placed?.[0]?.template;
    if (!zone) return;
    try {
      const bonus = Number(token.actor?.system?.tier ?? 0);
      const attack = await new Roll("1d20 + @bonus", { bonus }).evaluate();
      await attack.toMessage({
        speaker: ChatMessage.getSpeaker({ token: token.document }),
        flavor: "Melt — ranged attack against object Evasion 5 (NPC Tier " + bonus + ")"
      });
      if (Number(attack.total) < 5) {
        ui.notifications.info("Melt missed the object (Evasion 5); no splash occurs.");
        return;
      }
      const occupants = [...new Map(api.tokensInTemplate(zone)
        .filter(candidate => ["mech", "npc", "pilot"].includes(candidate?.actor?.type))
        .map(candidate => [candidate.id, candidate])).values()];
      await api.askCard({
        title: "MELT — OBJECT HIT", item,
        originToken: token, owner: token,
        description: "The object was hit. GM: apply 20 AP Energy to it. "
          + "Thermal Lance will automatically damage these characters in Burst 2: "
          + (occupants.map(target => target.name).join(", ") || "none") + ".",
        yesText: "Continue", noText: "Continue"
      });
      if (!occupants.length) return;
      const damage = String(api.tierValue(token, [6, 8, 10]));
      const result = await api.executeDamageRoll(token, occupants,
        damage, "Energy", "Melt — Thermal Lance hits",
        { has_normal_hit: true, add_burn: false });
      if (!result.completed) return;

      // Melt counts these as Thermal Lance hits, but does not fire the weapon.
      // Its Heat (Self) tag therefore does not apply.
      const round = Number(game.combat?.round);
      if (Number.isFinite(round)) {
        const key = "rebakedScourerThermalLanceHits";
        const history = { ...(api.getActorFlags(token.actor, key) ?? {}) };
        const focus = api.findItemByLid(token.actor,
          "npc-rebake_npcf_focus_down_scourer");
        const supercharged = api.findItemByLid(token.actor,
          "npc-rebake_npcf_supercharged_scourer");
        for (const target of occupants) {
          const previous = Number(history[target.id]);
          history[target.id] = round;
          if (!focus || previous !== round - 1) continue;
          await api.executeDamageRoll(token, [target],
            String(api.tierValue(token, [5, 6, 7])), "Burn", "Focus Down",
            { add_burn: true });
          if (supercharged) await api.applyEffectsToTokens({
            tokens: [target], effectNames: ["shredded", "slow"],
            note: "Supercharged — Focus Down",
            duration: api.untilEndOfTurn(target, 1)
          }, { rebakedScourerSupercharged: supercharged.id });
        }
        await api.addActorFlags(token.actor, { [key]: history });
      }
      if (api.findItemByLid(token.actor,
        "npc-rebake_npcf_thermal_overload_scourer")
        && api.getActorFlags(token.actor, "rebakedScourerCoolingThisTurn") === false) {
        const primaryIds = new Set(occupants.map(target => target.id));
        const splash = new Set();
        for (const hit of occupants)
          for (const nearby of canvas.tokens.placeables)
            if (["mech", "npc", "pilot"].includes(nearby.actor?.type)
              && !primaryIds.has(nearby.id)
              && api.getMinGridDistance(hit, nearby) <= 1) splash.add(nearby);
        if (splash.size) await api.executeDamageRoll(token, [...splash],
          String(api.tierValue(token, [3, 4, 5])), "Burn", "Thermal Overload",
          { add_burn: true });
      }
    } finally {
      if (canvas.scene?.templates?.get(zone.id)) await zone.delete();
    }
  }

reactions.evaluate:
function evaluate(type, data, token, item, name, api) {
  return data.triggeringToken?.id === token.id
    && data.weapon?.id === item.id
    && (data.targets ?? []).some(entry => entry.target?.actor);
}

reactions.activationCode:
async function activation(type, data, token, item, name, api) {
  const target = (data.targets ?? []).find(entry => entry.target?.actor)?.target;
  if (!target || api.hasStatus(target, "shredded")) return;
  const armor = Math.max(0, Number(target.actor.system?.armor) || 0);
  if (!armor) return;
  await api.injectBonusToFlowState(data.flowState, {
    id: "rebaked-monowire-armor-" + item.id,
    name: "Monowire Sword — double Armor",
    type: "damage", damageMode: "add",
    damage: [{ val: String(-armor), type: "Kinetic" }],
    applyTo: [target.id], rollTypes: ["damage"]
  });
}
